    public function __construct($key, $i18n)
    {
        $api = getenv('TELEGRAM_API') ?: 'api.telegram.org';
        $this->key      = $key;
        $this->api      = "https://$api/bot$key/";
        $this->file     = "https://$api/file/bot$key/";
        $this->clients  = '/config/clients.json';
        $this->clients1 = '/config/clients1.json';
        $this->pac      = '/config/pac.json';
        $this->ip       = getenv('IP');
        $this->i18n     = $i18n;
        $this->language = $this->getPacConf()['language'] ?: 'en';
        $this->dns      = '1.1.1.1, 8.8.8.8';
        $this->mtu      = 1350;
        $this->limit    = $this->getPacConf()['limitpage'] ?: 5;
        $this->adguard  = '/config/AdGuardHome.yaml';
        $this->update   = '/update/json';
        $this->hwid     = '/config/hwid.json';
        $this->logs = [
            'nginx_default_access',
            'nginx_domain_access',
            'upstream_access',
            'xray',
            'ocserv.log',
            'telemt',
        ];
        $this->reg = '~' . implode('|', [
            'GET / HTTP',
            'GET /favicon.ico HTTP',
            preg_quote($this->getHashBot(1))
        ]) . '~';
        $this->ports = [
            'hy'    => '443/udp',
            'wg'    => '51820/udp',
            'wg1'   => '51820/udp',
            'ss'    => '8388',
            'ad'    => '853',
            'dnstt' => '53/udp',
            'telemt' => '443',
        ];
    }

    public function input($data = false)
    {
        $this->admin     = false;
        $this->input_raw = $input = $data ?: json_decode(file_get_contents('php://input'), true);
        $this->input     = [
            'message'           => $input['callback_query']['message']['text'] ?? $input['message']['text'] ?? $input['channel_post']['text'] ?? '',
            'message_id'        => $input['callback_query']['message']['message_id'] ?? $input['message']['message_id'] ?? $input['channel_post']['message_id'],
            'chat'              => $input['message']['chat']['id'] ?? $input['callback_query']['message']['chat']['id'] ?? $input['channel_post']['chat']['id'] ?? $input['my_chat_member']['chat']['id'],
            'from'              => $input['message']['from']['id'] ?? $input['inline_query']['from']['id'] ?? $input['callback_query']['from']['id'] ?? $input['channel_post']['chat']['id'] ?? $input['my_chat_member']['from']['id'],
            'username'          => $input['message']['from']['username'] ?? $input['inline_query']['from']['username'] ?? $input['callback_query']['from']['username'],
            'query'             => $input['inline_query']['query'] ?? '',
            'inlid'             => $input['inline_query']['id'] ?? '',
            'group'             => !empty($input['message']['chat']['type']) && 'group' == $input['message']['chat']['type'],
            'sticker_id'        => $input['message']['sticker']['file_id'] ?? false,
            'channel'           => !empty($input['channel_post']['message_id']),
            'callback'          => $input['callback_query']['data'] ?? false,
            'callback_id'       => $input['callback_query']['id'] ?? false,
            'photo'             => $input['message']['photo'] ?? false,
            'file_name'         => $input['message']['document']['file_name'] ?? false,
            'file_id'           => $input['message']['document']['file_id'] ?? false,
            'caption'           => $input['message']['caption'] ?? false,
            'reply'             => $input['message']['reply_to_message']['message_id'] ?? false,
            'reply_from'        => $input['message']['reply_to_message']['from']['id'] ??  $input['callback_query']['message']['reply_to_message']['from']['id'] ?? false,
            'reply_text'        => $input['message']['reply_to_message']['text'] ?? false,
            'new_member_id'     => $input['my_chat_member']['new_chat_member']['user']['id'] ?? false,
            'new_member_status' => $input['my_chat_member']['new_chat_member']['status'] ?? false,
        ];
        $this->auth();
        if ($this->admin) {
            $this->session();
            // Отпускаем session lock ДО диспатча: PHP сериализует запросы
            // одного юзера на файловом локе сессии, и долгий хендлер (certbot,
            // рестарты, ssh-пробы) замораживал все следующие нажатия. Чтения
            // $_SESSION дальше работают из памяти; точечные записи идут через
            // stashReply()/unstashReply() (reopen → write → close).
            session_write_close();
            $this->action();
        }
        $this->callbackCheck();
    }

    /**
     * Проверка Telegram initData для эндпоинтов /webapp$hash/*.
     *
     * Три независимых условия, все обязательны:
     *
     * 1) Подпись. HMAC по отсортированным парам ключ=значение, ключ выводится
     *    из токена бота. Доказывает только то, что initData выдан Telegram
     *    для ЭТОГО бота.
     * 2) Свежесть (auth_date). initData уезжает query-строкой в POST
     *    /webapp$hash/{save,load} и попадал в access_log целиком. Без окна
     *    жизни строка из лога остаётся валидным пропуском НАВСЕГДА, а он даёт
     *    xray.json (uuid/password/subtoken всех клиентов) и запись шаблонов.
     * 3) Владелец (user.id). Подпись не говорит, КТО открыл webapp: Telegram
     *    подписывает initData любого пользователя тем же ключом. Сейчас
     *    не-админ не получает web_app-кнопку (диспетчер админ-гейтед), но это
     *    соглашение, а не проверка, — сверяем со списком админов явно.
     */
    public function webappAuth(array $get, string $key, array $admins, int $maxAge = 86400, ?int $now = null): bool
    {
        // Массив в hash (?hash[]=x) прошёл бы empty() и упёрся в (string) на
        // массиве — «Array to string conversion» и сравнение со строкой «Array».
        if (empty($get['hash']) || !is_string($get['hash'])) {
            return false;
        }
        $t = $get;
        unset($t['hash']);
        ksort($t);
        $s = [];
        foreach ($t as $k => $v) {
            // Любой параметр массивом («?x[]=1») тоже даёт warning на "$k=$v" и
            // мусор в подписываемой строке. Telegram шлёт только скаляры.
            if (!is_scalar($v)) {
                return $this->webappReject('non-scalar param');
            }
            $s[] = "$k=$v";
        }
        $sk = hash_hmac('sha256', $key, 'WebAppData', true);
        if (!hash_equals(hash_hmac('sha256', implode("\n", $s), $sk), $get['hash'])) {
            return $this->webappReject('bad signature');
        }

        $authDate = (int) ($get['auth_date'] ?? 0);
        $now      = $now ?? time();
        if ($authDate <= 0 || $now - $authDate > $maxAge) {
            return $this->webappReject('stale auth_date');
        }

        // Пустой список админов — бот ещё не присвоен (auth() заполняет его
        // первым написавшим). Пускать в этом состоянии некого.
        if (empty($admins)) {
            return $this->webappReject('no admins configured');
        }
        $wu = is_string($get['user'] ?? null) ? json_decode($get['user'], true) : null;
        if (empty($wu['id'])) {
            return $this->webappReject('no user.id');
        }

        if (!in_array((string) $wu['id'], array_map('strval', $admins), true)) {
            // Штатно сюда попадает чужой, но сюда же попадёт и САМ владелец,
            // если бот присвоен каналом/группой: там auth() кладёт в admin
            // chat.id канала, а initData несёт личный user.id нажавшего. Без
            // этой строки редактор шаблонов просто показывал бы «error».
            return $this->webappReject('user is not admin');
        }

        return true;
    }

    /**
     * Причина отказа — в лог, без единого значения из initData: сама строка
     * (в т.ч. hash) остаётся валидным пропуском до истечения окна.
     */
    private function webappReject(string $reason): bool
    {
        error_log("webappAuth: rejected ($reason)");

        return false;
    }

    /**
     * Запись приватного ключа TLS с правами 0600 БЕЗ окна на 0644.
     *
     * file_put_contents создаёт файл по umask, то есть 0644, и ./certs
     * смонтирован в девять контейнеров — ключ был читаем всем. Проставить
     * chmod после записи мало: между созданием и chmod ключ уже лежит на
     * диске с открытыми правами. Поэтому сначала создаём пустой файл и
     * сужаем права, и только потом пишем содержимое.
     */
    public function writePrivateKey(string $path, string $data): void
    {
        if (!file_exists($path)) {
            @touch($path);
        }
        @chmod($path, 0600);
        file_put_contents($path, $data);
        // Существовавший ранее файл мог быть создан старой версией с 0644.
        @chmod($path, 0600);
    }

    public function auth()
    {
        $file = __DIR__ . '/config.php';
        require $file;
        if (empty($c['admin'])) {
            $c['admin'] = [$this->input['from']];
            file_put_contents($file, "<?php\n\n\$c = " . var_export($c, true) . ";\n");
        } elseif (!is_array($c['admin'])) {
            $c['admin'] = [$c['admin']];
            file_put_contents($file, "<?php\n\n\$c = " . var_export($c, true) . ";\n");
        }
        if (in_array($this->input['from'], $c['admin'])) {
            $this->admin = true;
        }
    }

    public function callbackCheck()
    {
        if (empty($this->callback) && !empty($this->input['callback_id'])) {
            $this->answer($this->input['callback_id'], $GLOBALS['debug'] ? $this->input['callback'] : false);
        }
    }

    public function session()
    {
        session_id($this->input['from']);
        @session_start();
        if (!empty($_SESSION['reply'])) {
            if (empty($this->input['reply'])) {
                foreach ($_SESSION['reply'] as $k => $v) {
                    $this->delete($this->input['chat'], $k);
                }
                unset($_SESSION['reply']);
            }
        }
    }

    // Записи в закрытую сессию (input() отпускает lock до action()) молча
    // теряются, поэтому все записи $_SESSION['reply'] идут через эти хелперы:
    // короткий reopen → write → close, лок держится миллисекунды.
    protected function sessionApply(callable $fn)
    {
        $reopened = false;
        if (session_status() !== PHP_SESSION_ACTIVE) {
            session_id((string) $this->input['from']);
            @session_start();
            $reopened = true;
        }
        $fn();
        if ($reopened) {
            session_write_close();
        }
    }

    public function stashReply($r, array $state)
    {
        if (empty($r['result']['message_id'])) {
            return;
        }
        $this->sessionApply(function () use ($r, $state) {
            $_SESSION['reply'][$r['result']['message_id']] = $state;
        });
    }

    public function unstashReply($messageId)
    {
        $this->sessionApply(function () use ($messageId) {
            unset($_SESSION['reply'][$messageId]);
        });
    }

    public function sd($var, $log = false, $json = false, $raw = false)
    {
        if ($log) {
            if ($json) {
                file_put_contents('/logs/debug', json_encode($var, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
            } elseif ($raw) {
                file_put_contents('/logs/debug', $var);
            } else {
                file_put_contents('/logs/debug', var_export($var, true));
            }
        } else {
            $this->send($this->input['chat'], var_export($var, true), $this->input['message_id']);
        }
    }

    public function action()
    {
        // Инстанс нажатого сообщения (карта wg_msg.json) — пер-запросный
        // $this->wg: кнопки без инстанса в callback_data (delete, client,
        // torrent…) действуют на инстанс СВОЕГО меню, а не на глобальный
        // указатель. Явные роуты с инстансом ниже перекрывают через selectWG.
        if (!empty($this->input['callback']) && ($mi = $this->getWgMsg()) !== null) {
            $this->wg = (int) $mi;
        }
        switch (true) {
            // смена айпи сервера
            // wg-меню с явным инстансом: сначала пере-пиним wg_instance, дальше
            // обычный рендер. Роут без инстанса ниже оставлен для старых
            // сообщений в чатах (они работают через глобальный указатель).
            // ВАЖНО: case с телом должен стоять ВЫШЕ безтеловой группы
            // /menu|/start — иначе те проваливаются (fall-through) в это тело
            // и каждый /start делает selectWG(null) → сброс wg_instance в 0.
            case preg_match('~^/menu (?P<type>wg) (?P<inst>[01]) (?P<arg>(?:-)?\d+)$~', $this->input['callback'], $m):
                $this->selectWG($m['inst']);
                $this->menu(type: $m['type'], arg: $m['arg']);
                break;
            case preg_match('~^/menu$~', $this->input['message'], $m):
            case preg_match('~^/start$~', $this->input['message'], $m):
            case preg_match('~^/menu$~', $this->input['callback'], $m):
            case preg_match('~^/menu (?P<type>addpeer) (?P<arg>(?:-)?\d+)$~', $this->input['callback'], $m):
            case preg_match('~^/menu (?P<type>wg) (?P<arg>(?:-)?\d+)$~', $this->input['callback'], $m):
            case preg_match('~^/menu (?P<type>client) (?P<arg>\d+(?:_(?:-)?\d+)?)$~', $this->input['callback'], $m):
            case preg_match('~^/menu (?P<type>pac|adguard|config|ss|lang|oc|naive|mirror|update|hy|tt|ovpn|l2tp|ikev2)$~', $this->input['callback'], $m):
                $this->menu(type: $m['type'] ?? false, arg: $m['arg'] ?? false);
                break;
            case preg_match('~^/refreshMain$~', $this->input['callback'], $m):
                $this->refreshMain();
                break;
            case preg_match('~^/domainAlias$~', $this->input['callback'], $m):
                $this->domainAliasPrompt();
                break;
            case preg_match('~^/delDomainAlias (\d+)$~', $this->input['callback'], $m):
                $this->delDomainAlias($m[1]);
                break;
            case preg_match('~^/changeWG (\d+)$~', $this->input['callback'], $m):
                $this->changeWG($m[1]);
                break;
            case preg_match('~^/changeTransport(?: ([\w-]+))?$~', $this->input['callback'], $m):
                $this->changeTransport($m[1] ?? false);
                break;
            case preg_match('~^/changeFingerprint(?: (\w+))?$~', $this->input['callback'], $m):
                $this->changeFingerprint($m[1] ?? false);
                break;
            case preg_match('~^/fingerprintMenu$~', $this->input['callback'], $m):
                $this->fingerprintMenu();
                break;
            case preg_match('~^/dpiMenu$~', $this->input['callback'], $m):
                $this->dpiMenu();
                break;
            case preg_match('~^/dpiToggle (\w+)$~', $this->input['callback'], $m):
                $this->dpiToggle($m[1]);
                break;
            case preg_match('~^/dpiNoiseAdd$~', $this->input['callback'], $m):
                $this->dpiNoiseAdd();
                break;
            case preg_match('~^/dpiNoiseDel (\d+)$~', $this->input['callback'], $m):
                $this->dpiNoiseDel((int) $m[1]);
                break;
            case preg_match('~^/dpiSet (\w+)$~', $this->input['callback'], $m):
                $this->dpiSet($m[1]);
                break;
            case preg_match('~^/dpiDefault (\w+)$~', $this->input['callback'], $m):
                $this->dpiDefault($m[1]);
                break;
            case preg_match('~^/dpiFragPresets$~', $this->input['callback'], $m):
                $this->dpiFragPresetsMenu();
                break;
            case preg_match('~^/dpiFragPreset (\w+)$~', $this->input['callback'], $m):
                $this->dpiFragPreset($m[1]);
                break;
            case preg_match('~^/dpiNoisePresets$~', $this->input['callback'], $m):
                $this->dpiNoisePresetsMenu();
                break;
            case preg_match('~^/dpiNoisePreset (\w+)$~', $this->input['callback'], $m):
                $this->dpiNoisePreset($m[1]);
                break;
            case preg_match('~^/dpiGenSpiderX$~', $this->input['callback'], $m):
                $this->dpiGenSpiderX();
                break;
            case preg_match('~^/dpiGenMldsa$~', $this->input['callback'], $m):
                $this->dpiGenMldsa();
                break;
            case preg_match('~^/dpiShowMldsa$~', $this->input['callback'], $m):
                $this->dpiShowMldsa();
                break;
            case preg_match('~^/mirror$~', $this->input['message'], $m):
                $this->menu('mirror');
                break;
            case preg_match('~^/mainOutbound$~', $this->input['callback'], $m):
                $this->mainOutbound();
                break;
            case preg_match('~^/importIps (.+)$~', $this->input['callback'], $m):
                $this->importIps($m[1]);
                break;
            case preg_match('~^/setAsVlessTransport (?P<arg>\d+(?:_(?:-)?\d+)?)$~', $this->input['callback'], $m):
