            case preg_match('~^/tunprocessmode$~', $this->input['callback'], $m):
                $this->tunprocessmode();
                break;
            case preg_match('~^/tunprocess(?: (\d+))?$~', $this->input['callback'], $m):
                $this->tunprocess($m[1] ?: 0);
                break;
            case preg_match('~^/xtlswarp(?: (\d+))?$~', $this->input['callback'], $m):
                $this->xtlswarp($m[1] ?: 0);
                break;
            case preg_match('~^/xtlsproxy(?: (\d+))?$~', $this->input['callback'], $m):
                $this->xtlsproxy($m[1] ?: 0);
                break;
            case preg_match('~^/xtlsapp(?: (\d+))?$~', $this->input['callback'], $m):
                $this->xtlsapp($m[1] ?: 0);
                break;
            case preg_match('~^/xtlsprocess(?: (\d+))?$~', $this->input['callback'], $m):
                $this->xtlsprocess($m[1] ?: 0);
                break;
            case preg_match('~^/xtlssubnet(?: (\d+))?$~', $this->input['callback'], $m):
                $this->xtlssubnet($m[1] ?: 0);
                break;
            case preg_match('~^/xtlsrulesset(?: (\d+))?$~', $this->input['callback'], $m):
                $this->xtlsrulesset($m[1] ?: 0);
                break;
            case preg_match('~^/xtlsdat(?: (\d+))?$~', $this->input['callback'], $m):
                $this->xtlsdat($m[1] ?: 0);
                break;
            case preg_match('~^/datrefresh$~', $this->input['callback'], $m):
                $this->datRefresh();
                break;
            case preg_match('~^/datschedule$~', $this->input['callback'], $m):
                $this->datSchedule();
                break;
            case preg_match('~^/datscheduleset (\d+)$~', $this->input['callback'], $m):
                $this->datScheduleSet((int) $m[1]);
                break;
            case preg_match('~^/templateCopy (\w+)(?: (.+))?$~', $this->input['callback'], $m):
                $this->templateCopy($m[1], $m[2]);
                break;
            case preg_match('~^/delTemplate (\w+)(?: (.+))?$~', $this->input['callback'], $m):
                $this->delTemplate($m[1], $m[2]);
                break;
            case preg_match('~^/downloadOrigin (\w+)$~', $this->input['callback'], $m):
                $this->downloadOrigin($m[1]);
                break;
            case preg_match('~^/downloadTemplate (\w+)(?: (.+))?$~', $this->input['callback'], $m):
                $this->downloadTemplate($m[1], $m[2]);
                break;
            case preg_match('~^/defaultTemplate (\w+)(?: (.+))?$~', $this->input['callback'], $m):
                $this->defaultTemplate($m[1], $m[2]);
                break;
            case preg_match('~^/templates (\w+)$~', $this->input['callback'], $m):
                $this->templates($m[1]);
                break;
            case preg_match('~^/templateAdd (\w+)$~', $this->input['callback'], $m):
                $this->templateAdd($m[1]);
                break;
            case preg_match('~^/changeFakeDomain$~', $this->input['callback'], $m):
                $this->changeFakeDomain();
                break;
            case preg_match('~^/autoCleanLogs$~', $this->input['callback'], $m):
                $this->autoCleanLogs();
                break;
            case preg_match('~^/selfFakeDomain$~', $this->input['callback'], $m):
                $this->selfFakeDomain();
                break;
            case preg_match('~^/include (\w+)$~', $this->input['callback'], $m):
                $this->include($m[1]);
                break;
            case preg_match('~^/exclude (\d+)$~', $this->input['callback'], $m):
                $this->exclude($m[1]);
                break;
            case preg_match('~^/reverse (\d+)$~', $this->input['callback'], $m):
                $this->reverse($m[1]);
                break;
            case preg_match('~^/subzones (\d+)$~', $this->input['callback'], $m):
                $this->subzones($m[1]);
                break;
            case preg_match('~^/proxy$~', $this->input['callback'], $m):
                $this->proxy();
                break;
            case preg_match('~^/addOverrideHtml$~', $this->input['callback'], $m):
                $this->addOverrideHtml();
                break;
            case preg_match('~^/export$~', $this->input['callback'], $m):
                $this->pinBackup();
                break;
            case preg_match('~^/import$~', $this->input['callback'], $m):
                $this->import();
                break;
            case preg_match('~^/importList (\w+)$~', $this->input['callback'], $m):
                $this->importList($m[1]);
                break;
            case preg_match('~^/rename (?P<arg>\d+(?:_(?:-)?\d+)?)$~', $this->input['callback'], $m):
                $this->rename(...explode('_', $m['arg']));
                break;
            case preg_match('~^/timer (?P<arg>\d+(?:_(?:-)?\d+)?)$~', $this->input['callback'], $m):
                $this->timer(...explode('_', $m['arg']));
                break;
            case !empty($this->input['reply']):
                $this->reply();
                break;
        }
    }

    // ── telemt (TeleMT) ─────────────────────────────────────────────────
    // MTProto-прокси (Rust, fake-TLS) из проекта telemt/telemt. Конфиг
    // хранится в pac-conf (telemt_*), сам telemt.toml перегенерируется при
    // каждом рестарте.
    public function telemtBool(array $conf, string $key, bool $default = false): bool
    {
        return array_key_exists($key, $conf) ? !empty($conf[$key]) : $default;
    }

    // Дефолты masking-флагов telemt. mask_shape_hardening у telemt включён по
    // умолчанию (дёшево, работает только на mask-пути, ломает shape-анализ при
    // активном пробинге) — не глушим его на свежем конфиге. Остальные — off.
    public function telemtMaskDefault(string $key): bool
    {
        return $key === 'telemt_mask_hardening';
    }

    public function telemtInt(array $conf, string $key, int $default, int $min, int $max): int
    {
        $value = (int) ($conf[$key] ?? $default);
        return max($min, min($max, $value));
    }

    public function telemtState(bool $enabled): string
    {
        return $this->i18n($enabled ? 'on' : 'off');
    }

    public function telemtToml($conf = false)
    {
        [$conf] = $this->normalizeTelemtUsers($conf ?: $this->getPacConf());
        $domain = $conf['telemt_domain'] ?? 'www.google.com';
        $users  = $conf['telemt_users'] ?? [];
        $userEnabled = is_array($conf['telemt_user_enabled'] ?? null) ? $conf['telemt_user_enabled'] : [];
        $beobachten = $this->telemtBool($conf, 'telemt_beobachten', false);
        $beobachtenMinutes = $this->telemtInt($conf, 'telemt_beobachten_minutes', 10, 1, 1440);
        $maskHardening = $this->telemtBool($conf, 'telemt_mask_hardening', $this->telemtMaskDefault('telemt_mask_hardening'));
        $maskTiming = $this->telemtBool($conf, 'telemt_mask_timing', $this->telemtMaskDefault('telemt_mask_timing'));
        // telemt отказывается стартовать, если aggressive/blur включены без
        // mask_shape_hardening (load.rs: "requires mask_shape_hardening = true").
        // UI-тоггл держит инвариант, но импортированный бэкап или правленый
        // pac-conf могут принести несогласованную пару — гасим её здесь, в
        // единственном месте, которое генерирует telemt.toml.
        $maskAggressive = $maskHardening && $this->telemtBool($conf, 'telemt_mask_aggressive', $this->telemtMaskDefault('telemt_mask_aggressive'));
        $maskBlur = $maskHardening && $this->telemtBool($conf, 'telemt_mask_blur', $this->telemtMaskDefault('telemt_mask_blur'));
        $announce = $this->ip;
        $b      = fn($v) => $v ? 'true' : 'false';
        $q      = fn($v) => json_encode((string) $v, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);

        $showLink = implode(', ', array_map($q, array_keys($users)));
        $t  = "show_link = [$showLink]\n\n";
        $t .= "[general]\n";
        // log_level/disable_colors — поля [general] (а не top-level: там telemt
        // их игнорирует). disable_colors убирает ANSI-escape из /logs/telemt;
        // env NO_COLOR telemt не читает, только этот ключ.
        $t .= "log_level = \"normal\"\n";
        $t .= "disable_colors = true\n";
        $t .= "prefer_ipv6 = false\n";
        $t .= "fast_mode = true\n";
        $t .= "beobachten = " . $b($beobachten) . "\n";
        $t .= "beobachten_minutes = $beobachtenMinutes\n";
        // beobachten пишет наблюдения JA3/JA4 в файл (НЕ в HTTP-API). Кладём
        // его в data-path (/telemt/data ⇄ host ./config/telemt/data ⇄ php
        // /config/telemt/data), чтобы бот читал журнал напрямую, без API.
        $t .= "beobachten_file = " . $q('/telemt/data/beobachten.txt') . "\n";
        $t .= "use_middle_proxy = false\n\n";
        // Ровно один режим активен (radio). Секрет ссылки зависит от него:
        // classic = <hex>, secure = dd<hex>, tls = ee<hex><domainHex>
        // (linkTelemt держит ту же логику). Невалидное значение → tls.
        $mode = $this->telemtModeOf($conf);
        $t .= "[general.modes]\n";
        $t .= "classic = " . $b($mode === 'classic') . "\n";
        $t .= "secure = " . $b($mode === 'secure') . "\n";
        $t .= "tls = " . $b($mode === 'tls') . "\n\n";
        $t .= "[server]\n";
        // В бридж-сети vpnbot telemt всегда слушает 443 внутри контейнера;
        // наружу порт пробрасывается через override (setPort), как у tg.
        $t .= "port = 443\n";
        $t .= "listen_addr_ipv4 = \"0.0.0.0\"\n\n";
        // Управляющий HTTP-API нужен боту для расширенной диагностики
        // (/v1/* эндпоинты: health, stats, security posture). Включаем его
        // ТОЛЬКО когда включён beobachten, и строго на loopback внутри
        // контейнера (listen 127.0.0.1 + whitelist). Наружу 9091 НЕ
        // публикуется (нет ports: в compose), дополнительно режется nft на
        // хосте; бот ходит к API по ssh изнутри контейнера. auth_header пуст —
        // loopback-изоляции network namespace достаточно (как в upstream
        // prod-образе). Когда диагностика выключена — сокет не открывается.
        $t .= "[server.api]\n";
        $t .= "enabled = " . $b($beobachten) . "\n";
        $t .= "listen = \"127.0.0.1:9091\"\n";
        $t .= "whitelist = [\"127.0.0.1/32\", \"::1/128\"]\n\n";
        $t .= "[[server.listeners]]\n";
        $t .= "ip = \"0.0.0.0\"\n";
        // telemt отвергает пустой announce_ip ("invalid IP address syntax") и не
        // стартует вовсе. getenv('IP') бывает пуст, когда стек подняли не через
        // make (make экспортирует IP из hostname -I; .env держит IP пустым, а
        // bare `docker compose up` даёт IP=""). В этом случае ключ опускаем —
        // telemt сам определит announce-адрес, а не падает.
        if ($announce !== '') {
            $t .= "announce_ip = " . $q($announce) . "\n";
        }
        $t .= "\n";
        $t .= "[censorship]\n";
        $t .= "tls_domain = " . $q($domain) . "\n";
        $t .= "mask = true\n";
        // Поведение на ClientHello с ЧУЖИМ SNI (active-probe / сканер портов).
        // Дефолт telemt — "drop" (молча закрыть соединение), но настоящий
        // HTTPS-сервер так не делает: он отдаёт default-vhost или фатальный
        // alert unrecognized_name. Тихий drop сам по себе — пассивный
        // фингерпринт, отличающий прокси от обычного веб-сервера. Ставим
        // "reject_handshake" — на проводе неотличимо от nginx с
        // `ssl_reject_handshake on;` (RFC 6066, alert 112), без cert-mismatch
        // и без исходящего соединения на каждый зонд (в отличие от "mask").
        // Ветка ВАЛИДНОГО SNI + невалидного MTProto по-прежнему уходит в
        // mask-fronting на mask_host (= tls_domain), где и работает весь
        // shape/timing-хардненинг ниже. Значение настраивается в боте
        // (TeleMT -> unknown SNI): mask — прозрачный фронт на mask_host для
        // ЛЮБОГО SNI (FAQ-рекомендация при ошибке "Unknown TLS SNI", удобно при
        // рассинхроне домена ссылки и tls_domain); drop — молчаливое закрытие.
        $sni = $this->telemtSniOf($conf);
        $t .= "unknown_sni_action = \"$sni\"\n";
        $t .= "mask_port = 443\n";
        $t .= "fake_cert_len = 2048\n";
        $t .= "tls_emulation = true\n";
        // Кол-во post-handshake NewSessionTicket. Дефолт telemt И проверенного
        // рабочего конфига = 0. Раньше бот жёстко слал 2
        // «для реализма», но это единственная строка [censorship], меняющая сам
        // КЛИЕНТСКИЙ handshake и отсутствующая в рабочем конфиге — а ровно там
        // клиент рвал связь после TLS («expected 64 bytes, got 0»). Возвращаем
        // дефолт 0; значение можно переопределить ключом telemt_session_tickets.
        $tickets = max(0, min(8, (int) ($conf['telemt_session_tickets'] ?? 0)));
        $t .= "tls_new_session_tickets = $tickets\n";
        $t .= "mask_shape_hardening = " . $b($maskHardening) . "\n";
        $t .= "mask_shape_bucket_floor_bytes = 512\n";
        $t .= "mask_shape_bucket_cap_bytes = 4096\n";
        $t .= "mask_shape_hardening_aggressive_mode = " . $b($maskAggressive) . "\n";
        $t .= "mask_shape_above_cap_blur = " . $b($maskBlur) . "\n";
        $t .= "mask_shape_above_cap_blur_max_bytes = 512\n";
        $t .= "mask_timing_normalization_enabled = " . $b($maskTiming) . "\n";
        $t .= "mask_timing_normalization_floor_ms = 180\n";
        $t .= "mask_timing_normalization_ceiling_ms = 320\n\n";
        $t .= "[access]\n";
        $t .= "replay_check_len = 65536\n";
        $t .= "ignore_time_skew = false\n\n";
        $disabledUsers = array_filter(
            array_keys($users),
            fn($name) => array_key_exists($name, $userEnabled) && empty($userEnabled[$name])
        );
        if ($disabledUsers) {
            $t .= "[access.user_enabled]\n";
            foreach ($disabledUsers as $name) {
                $t .= $q($name) . " = false\n";
            }
            $t .= "\n";
        }
        $t .= "[access.users]\n";
        foreach ($users as $name => $secret) {
            $t .= $q($name) . " = " . $q($secret) . "\n";
        }
        $t .= "\n[[upstreams]]\n";
        $t .= "type = \"direct\"\n";
        $t .= "enabled = true\n";
        $t .= "weight = 10\n";
        return $t;
    }

    public function restartTelemt()
    {
        [$conf, $changed] = $this->normalizeTelemtUsers($this->getPacConf());
        if ($changed) {
            $this->setPacConf($conf);
        }
        @mkdir('/config/telemt/data', 0755, true);
        file_put_contents('/config/telemt/telemt.toml', $this->telemtToml($conf));
        $this->ssh('pkill -9 -x telemt; while pgrep -x telemt >/dev/null; do sleep 0.2; done', 'telemt');
        if (!empty($conf['telemt_users'])) {
            $this->ssh('telemt run --data-path /telemt/data /telemt/telemt.toml', 'telemt', false, '/logs/telemt');
        }
    }

    public function telemtSecret()
    {
        return bin2hex(random_bytes(16));
    }

    // Validated active mode / unknown-SNI policy with safe defaults. NB: keep
    // the bare-access OUT of the in_array ternary — `in_array($conf[k] ?? 'def')
    // ? $conf[k] : 'def'` returns null (E_WARNING) when k is unset, because the
    // true-branch reads the undefined key. Resolve via a temp var instead.
    public function telemtModeOf(array $conf): string
    {
        $m = $conf['telemt_mode'] ?? 'tls';
        return in_array($m, ['classic', 'secure', 'tls'], true) ? $m : 'tls';
    }

    public function telemtSniOf(array $conf): string
    {
        $a = $conf['telemt_unknown_sni'] ?? 'reject_handshake';
        return in_array($a, ['mask', 'reject_handshake', 'drop'], true) ? $a : 'reject_handshake';
    }

    // Версия telemt. Сам бинарь команды версии НЕ имеет (CLI рукописный,
    // неизвестный флаг вроде --version уходит в дефолтный Run — опрашивать
    // бинарь по ssh, как hysteriaVersion(), нельзя), поэтому версию при
    // сборке впекаем в образ файлом /etc/telemt_version
    // (dockerfile/telemt.dockerfile) и читаем ПО SSH ИЗ КОНТЕЙНЕРА — это
    // версия реально запущенного образа. Fallback — build-пин TELEMT_VERSION
    // из .env (образы, собранные до появления файла): он может расходиться с
    // контейнером, пока образ не пересобран.
    public function telemtVersion(): string
    {
        $v = trim((string) $this->ssh('cat /etc/telemt_version 2>/dev/null', 'telemt'));
        if ($v === '') {
            $v = trim((string) getenv('TELEMT_VERSION'));
        }
        if ($v === '') {
            return 'unknown';
        }
        if (preg_match('~\bv?\d+(?:\.\d+)+(?:[-+][0-9A-Za-z.-]+)?\b~', $v, $m)) {
            return htmlspecialchars($m[0], ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        }
        return htmlspecialchars(mb_substr($v, 0, 40, 'UTF-8'), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
    }

    public function normalizeTelemtUsers(array $conf): array
    {
        if (!isset($conf['telemt_users'])) {
            $changed = isset($conf['telemt_user_enabled']);
            unset($conf['telemt_user_enabled']);
            return [$conf, $changed];
        }
        if (!is_array($conf['telemt_users'])) {
            $conf['telemt_users'] = [];
            unset($conf['telemt_user_enabled']);
            return [$conf, true];
        }
        if (!$conf['telemt_users']) {
            if (!empty($conf['telemt_user_enabled'])) {
                $conf['telemt_user_enabled'] = [];
                return [$conf, true];
            }
            return [$conf, false];
        }

        $changed = false;
        $seen    = [];

        foreach ($conf['telemt_users'] as $name => $secret) {
            $secret = strtolower(trim((string) $secret));
            if (
                !preg_match('~^[a-f0-9]{32}$~', $secret)
                || isset($seen[$secret])
            ) {
                do {
                    $secret = $this->telemtSecret();
                } while (isset($seen[$secret]));
                $changed = true;
            } elseif ($conf['telemt_users'][$name] !== $secret) {
                $changed = true;
            }

            $conf['telemt_users'][$name] = $secret;
            $seen[$secret] = true;
        }
        if (!is_array($conf['telemt_user_enabled'] ?? null)) {
            $conf['telemt_user_enabled'] = [];
        }
        foreach (array_keys($conf['telemt_user_enabled']) as $name) {
            if (!array_key_exists($name, $conf['telemt_users'])) {
                unset($conf['telemt_user_enabled'][$name]);
                $changed = true;
            }
        }

        return [$conf, $changed];
    }

    // Resolve a dedicated TeleMT relay by name → ['address'=>.., 'portmap'=>[..]]
    // or null. Separate from the xray $pac['relays'] store on purpose.
    public function telemtRelay($name)
    {
        $r = $this->getPacConf()['telemt_relays'][$name] ?? null;
        return is_array($r) && !empty($r['address']) ? $r : null;
    }

    // Build a tg://proxy link. The secret format depends on the active mode
    // (classic = <hex>, secure = dd<hex>, tls = ee<hex><domainHex>). When a
    // $relay is given, only server+port are swapped (port through the relay's
    // portmap); the secret and the Fake-TLS domain stay untouched — same idea as
    // applyRelay keeping SNI real.
    public function linkTelemt($name, $relay = null)
    {
        [$conf, $changed] = $this->normalizeTelemtUsers($this->getPacConf());
        if ($changed) {
            $this->setPacConf($conf);
            $this->restartTelemt();
        }
        $secret = $conf['telemt_users'][$name] ?? '';
        $domain = $conf['telemt_domain'] ?? 'www.google.com';
        $dhex   = bin2hex($domain);
        $mode   = $this->telemtModeOf($conf);
        $secret = match ($mode) {
            'classic' => $secret,
            'secure'  => "dd$secret",
            default   => "ee$secret$dhex",
        };
        $server = $this->getDomain();
        $port   = $this->getPorts()['telemt']['port'];
        if (is_array($relay) && !empty($relay['address'])) {
            $server = $relay['address'];
            $map    = $relay['portmap'] ?? [];
            $port   = $map[(string) $port] ?? $port;
        }
        return 'tg://proxy?' . http_build_query([
            'server' => $server,
            'port'   => $port,
            'secret' => $secret,
        ], '', '&', PHP_QUERY_RFC3986);
    }

    public function restartXray($c, $norestart = false)
    {
        $c['inbounds'][0]['settings']['clients'] = array_values($c['inbounds'][0]['settings']['clients']);
        $c['log']['access'] = '/logs/xray';
        foreach ($c['inbounds'] as $v) {
            if ($v['tag'] == 'api') {
                $api = true;
                break;
            }
        }
        if (empty($api)) {
            $c['inbounds'][] = [
                "listen"   => "127.0.0.1",
                "port"     => 8080,
                "protocol" => "dokodemo-door",
                "settings" => [
                    "address" => "127.0.0.1"
                ],
                "tag" => "api"
            ];
        }
        foreach ($c['routing']['rules'] as $v) {
            if ($v['outboundTag'] == 'api') {
                $rule = true;
                break;
            }
        }
        if (empty($rule)) {
            $c['routing']['rules'][] = [
                "inboundTag"  => ["api"],
                "outboundTag" => "api",
                "type"        => "field"
            ];
        }

        foreach ($c['inbounds'] as $v) {
            if ($v['tag'] == 'wg-in') {
                $wg = true;
                break;
            }
        }
        if (empty($wg)) {
            $c['inbounds'][] = [
                "port"     => 10808,
                "protocol" => "socks",
                "settings" => [
                    "auth" => "noauth",
                    "udp"  => true,
                    "ip"   => "0.0.0.0"
                ],
                "tag"      => "wg-in",
                "sniffing" => [
                    "destOverride" => [
                        "http",
                        "tls",
                        "quic"
                    ],
                    "enabled" => true
                ]
            ];
        }
        $this->applySniffingToXray($c, $this->getPacConf());
        $this->ensureTrustedXff($c);
        $this->ensureFreedomCompat($c);
        $c['stats'] = new stdClass();
        $c['api'] = [
            'services' => ['StatsService'],
            'tag'      => 'api'
        ];
        $l = new stdClass();
        $l->{'0'} = [
            "statsUserUplink"   => true,
            "statsUserDownlink" => true
        ];
        $c['policy']['levels'] = $l;
        $c['policy']['system'] = [
            "statsInboundUplink"    => true,
            "statsInboundDownlink"  => true,
            "statsOutboundUplink"   => true,
            "statsOutboundDownlink" => true
        ];
        if (empty($norestart)) {
            $this->collectSession();
            file_put_contents('/config/xray.json', json_encode($c, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
            $this->ssh('pkill xray', 'xr');
            // XRAY_LOCATION_ASSET указывает ядру, где искать .dat (ext:/extip: из
            // routes → dat лежат в общем /logs/geodata). Задаём прямо в команде
            // старта — не требует правки override.env и совпадает с datDir().
            $this->ssh('mkdir -p /logs/geodata; XRAY_LOCATION_ASSET=/logs/geodata xray run -config /xray.json > /dev/null 2>&1 &', 'xr');
        } else {
            file_put_contents('/config/xray.json', json_encode($c, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
        }
    }

    // Дотягивает sockopt.trustedXForwardedFor на клиентский inbound, если его
    // транспорт слушает за nginx (ws / xhttp / grpc). changeTransport ставит его
    // сам, но только в момент переключения транспорта — у всех, кто уже сидит на
    // ws/xhttp/trojan-grpc, конфиг иначе остался бы без него до ручного
    // перещёлкивания кнопки. Ставим ровно один раз и не трогаем уже заданное
    // значение: админ мог прописать своё имя заголовка руками в webapp.
    // Чем это лечится — см. nginxFrontedSockopt().
    public function ensureTrustedXff(array &$c): void
    {
        $net = $c['inbounds'][0]['streamSettings']['network'] ?? '';
        if (!in_array($net, ['ws', 'xhttp', 'grpc'], true)) {
            return;
        }
        if (!empty($c['inbounds'][0]['streamSettings']['sockopt']['trustedXForwardedFor'])) {
            return;
        }
        $c['inbounds'][0]['streamSettings']['sockopt'] = array_merge(
            $c['inbounds'][0]['streamSettings']['sockopt'] ?? [],
            $this->nginxFrontedSockopt(),
        );
    }

    // Безопасная запись xray.json для функций, которые меняют лишь метаданные
    // клиента (шаблоны подписки, HWID) и НЕ перезапускают ядро. getXray() читает
    // конфиг как ассоц-массив, из-за чего json round-trip превращает пустые/
    // числовые-ключ объекты `stats:{}` → `[]` и `policy.levels:{"0":..}` → `[..]`,
    // а xray такой конфиг ОТВЕРГАЕТ ("cannot unmarshal array into ... stats") и не
    // стартует при следующем старте контейнера. Восстанавливаем тип объекта (как
    // это делает restartXray) перед записью.
    public function saveXray(array $c): void
    {
        $c['stats'] = new stdClass();
        if (isset($c['policy']['levels']) && is_array($c['policy']['levels'])) {
            $lv = new stdClass();
            foreach ($c['policy']['levels'] as $k => $v) {
                $lv->{(string) $k} = $v;
            }
            $c['policy']['levels'] = $lv;
        }
        $this->ensureFreedomCompat($c);
        file_put_contents('/config/xray.json', json_encode($c, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
    }

    // Xray >= v26.4.15 (PR #5947, «Direct/Freedom outbound: default safe policy»)
    // вешает на freedom/direct-outbound встроенное правило, которое МОЛЧА рвёт
    // любое соединение, чей адрес назначения попадает в приватный/зарезерви-
    // рованный диапазон (0/8, 10/8, 100.64/10, 127/8, 169.254/16, 172.16/12,
    // 192.168/16, 198.18/15, CGNAT, …), и принудительно резолвит домен ДО дозвона.
    // Срабатывает, когда исходящий inbound — vless/vmess/trojan/hysteria/wireguard
    // /shadowsocks. Именно это ломает warp (socks → microsocks @ 10.10.0.13) и
    // любой внутрикластерный/LAN-адрес, идущий через "direct": поэтому warp
    // работает на v26.4.13 и отваливается начиная с v26.4.15.
    //
    // Возвращаем работоспособность warp, перекрывая встроенное правило своим
    // явным finalRules (матчится раньше default-правила; первое совпадение
    // выигрывает — см. proxy/freedom/freedom.go: matchFinalRule). Вместо «глухого»
    // allow-all делаем «закалённый» вариант, сохраняющий защиту от SSRF:
    //   1) allow 10.10.0.0/16 — внутренние docker-сети проекта (10.10.0.0/24 и
    //      10.10.1.0/24), сюда входит warp-socks @ 10.10.0.13 и прочие контейнеры;
    //   2) block — полный приватный/зарезервированный набор (как в апстрим-политике
    //      #5947: loopback, CGNAT, link-local/metadata 169.254.169.254, RFC1918,
    //      IPv6 ULA/link-local), чтобы клиент не дотянулся через "direct" до
    //      внутренностей хоста/LAN/облачного metadata.
    // Публичные адреса не матчат ни одно правило → default Allow. ВАЖНО: при
    // наличии ip-матчера в finalRules ядро форс-резолвит домен ДО дозвона (как и
    // штатная safe policy), что требует рабочего системного резолвера в контейнере
    // xr — у нас он есть. Ядра < v26.4.17 не знают поля "finalRules" и игнорируют
    // его (нестрогий JSON-загрузчик), а safe policy там либо отсутствует
    // (<= v26.4.13) — регрессий нет. Конфиги с собственными finalRules не трогаем.
    public function ensureFreedomCompat(array &$c): void
    {
        if (empty($c['outbounds']) || !is_array($c['outbounds'])) {
            return;
        }
        $finalRules = [
            ['action' => 'allow', 'ip' => ['10.10.0.0/16']],
            ['action' => 'block', 'ip' => [
                '0.0.0.0/8',
                '10.0.0.0/8',
                '100.64.0.0/10',
                '127.0.0.0/8',
                '169.254.0.0/16',
                '172.16.0.0/12',
                '192.0.0.0/24',
                '192.0.2.0/24',
                '192.88.99.0/24',
                '192.168.0.0/16',
                '198.18.0.0/15',
                '198.51.100.0/24',
                '203.0.113.0/24',
                '224.0.0.0/3',
                '::/127',
                'fc00::/7',
                'fe80::/10',
                'ff00::/8',
            ]],
        ];
        foreach ($c['outbounds'] as &$ob) {
            if (($ob['protocol'] ?? '') !== 'freedom') {
                continue;
            }
            if (!isset($ob['settings']) || !is_array($ob['settings'])) {
                $ob['settings'] = [];
            }
            if (!array_key_exists('finalRules', $ob['settings'])) {
                $ob['settings']['finalRules'] = $finalRules;
            }
        }
        unset($ob);
    }

    public function collectSession() {
        $p = $this->getXrayStats();
        $p['global'] = [
            'download' => $p['global']['download'] + $p['session']['download'],
            'upload'   => $p['global']['upload'] + $p['session']['upload'],
        ];
        $p['session'] = [
            'download' => 0,
            'upload'   => 0,
        ];
        foreach ($p['users'] as $k => $v) {
            $p['users'][$k]['global']['download']  += $v['session']['download'];
            $p['users'][$k]['session']['download']  = 0;
            $p['users'][$k]['global']['upload']    += $v['session']['upload'];
            $p['users'][$k]['session']['upload']    = 0;
        }
        $this->setXrayStats($p);
    }

