    // Ввод-«очистка» для полей relay (адреса и маппинги, включая telemt):
    // '0' или пустая строка. Telegram не даёт отправить пустое сообщение
    // реплаем, поэтому единый явный сентинел — 0.
    public function relayClearInput($text): bool
    {
        return in_array(trim((string) $text), ['', '0'], true);
    }

    // Parse a 'src:dst,src:dst' port map (real port -> relay port). Both sides
    // must be numeric; empty/blank segments are skipped. Mirrors _parse_port_map
    // in the relay's sub_proxy.py. Invalid pairs are silently dropped here (the
    // bot has no fail-fast restart loop to protect against).
    public function parseRelayPortMap($text)
    {
        $map = [];
        foreach (explode(',', (string) $text) as $pair) {
            $pair = trim($pair);
            if ($pair === '') {
                continue;
            }
            $parts = explode(':', $pair);
            if (count($parts) != 2) {
                continue;
            }
            $src = trim($parts[0]);
            $dst = trim($parts[1]);
            if (!preg_match('~^\d+$~', $src) || !preg_match('~^\d+$~', $dst)) {
                continue;
            }
            $map[$src] = $dst;
        }
        return $map;
    }

    // Swap only the endpoint address+port of the main outbound to the named
    // relay; SNI/serverName/host and DNS domain are left untouched (TLS still
    // terminates on origin via the relay's DNAT). $type is $_GET['t'] (s|si|cl),
    // $index the main outbound/proxy index already resolved in subscription().
    public function applyRelay(&$c, $type, $index, $relay)
    {
        if (empty($relay['address'])) {
            return;
        }
        $map  = $relay['portmap'] ?? [];
        $addr = $relay['address'];
        $port = function ($cur) use ($map) {
            $cur = (string) $cur;
            return isset($map[$cur]) ? (int) $map[$cur] : (int) $cur;
        };

        switch ($type) {
            case 's':
                $ob = &$c['outbounds'][$index]['settings'];
                if (isset($ob['vnext'][0])) {
                    $ob['vnext'][0]['address'] = $addr;
                    if (isset($ob['vnext'][0]['port'])) {
                        $ob['vnext'][0]['port'] = $port($ob['vnext'][0]['port']);
                    }
                } elseif (isset($ob['servers'][0])) {
                    $ob['servers'][0]['address'] = $addr;
                    if (isset($ob['servers'][0]['port'])) {
                        $ob['servers'][0]['port'] = $port($ob['servers'][0]['port']);
                    }
                }
                unset($ob);
                break;
            case 'si':
                $c['outbounds'][$index]['server'] = $addr;
                if (isset($c['outbounds'][$index]['server_port'])) {
                    $c['outbounds'][$index]['server_port'] = $port($c['outbounds'][$index]['server_port']);
                }
                break;
            case 'cl':
                $c['proxies'][$index]['server'] = $addr;
                if (isset($c['proxies'][$index]['port'])) {
                    $c['proxies'][$index]['port'] = $port($c['proxies'][$index]['port']);
                }
                break;
        }
    }

    // Swap the endpoint of the embedded wireguard/awg sub-proxy (named 'awg' in
    // the mihomo config) to the relay's separate WG/AWG endpoint. Independent of
    // applyRelay: the main proxy and the awg proxy can sit behind different
    // relays/ports. No-op unless the relay has awg_address set and an 'awg' proxy
    // exists (mihomo/'cl' configs only). Covers both plain WG and AmneziaWG —
    // they are the same wireguard proxy, differing only by amnezia-wg-option.
    public function applyAwgRelay(&$c, $relay)
    {
        if (empty($relay['awg_address']) || empty($c['proxies']) || !is_array($c['proxies'])) {
            return;
        }
        $map = $relay['awg_portmap'] ?? [];
        foreach ($c['proxies'] as $k => $p) {
            if (($p['name'] ?? '') !== 'awg' || ($p['type'] ?? '') !== 'wireguard') {
                continue;
            }
            $c['proxies'][$k]['server'] = $relay['awg_address'];
            if (isset($c['proxies'][$k]['port'])) {
                $cur = (string) $c['proxies'][$k]['port'];
                $c['proxies'][$k]['port'] = isset($map[$cur]) ? (int) $map[$cur] : (int) $cur;
            }
        }
    }

