    public function pad($text, $length, $symbol = ' ')
    {
        for ($i = 0; $i < $length; $i++) {
            $text .= $symbol;
        }
        return $text;
    }

    public function getTitleWG()
    {
        $c = $this->getPacConf();
        // Номер — из wgNum(), а не из глобального $c['wg_instance']: флаг amnezia
        // рядом читается с префиксом пер-запросного инстанса ($this->wg), и на
        // кнопках с явным инстансом заголовок расходился с содержимым меню
        // («AmneziaWG 1» над настройками нулевого и наоборот). Заодно уходит
        // «Undefined array key wg_instance» на свежей установке (pac.json = {}).
        return $this->i18n(($c[$this->getInstanceWG(1) . 'amnezia'] ?? false) ? 'amnezia' : 'wg_title') . ' ' . $this->wgNum();
    }

    // Достаёт «vX.Y.Z…» из строки вывода, помеченной printf-префиксом «<tag>:».
    // Возвращает null, если бинарь отсутствует (строка пустая) или версии нет.
    public function pickVersion(string $out, string $tag): ?string
    {
        if (preg_match('~^' . preg_quote($tag, '~') . ':(.*)$~m', $out, $m)
            && preg_match('~v?\d+(?:\.\d+)+[0-9A-Za-z.\-]*~', $m[1], $v)) {
            return $v[0];
        }
        return null;
    }

    // Версии ядра wireguard/amneziawg из wg-контейнера — информационная строка
    // под заголовком меню. Один ssh-вызов (меню и так ходит в контейнер через
    // readStatus), безопасный фолбэк: пусто, если бинари/контейнер недоступны.
    public function wgVersion(): string
    {
        $v = $this->wgVersions();
        $parts = [];
        if (!empty($v['awg'])) {
            $parts[] = "AmneziaWG: {$v['awg']}";
        }
        if (!empty($v['wg'])) {
            $parts[] = "WireGuard: {$v['wg']}";
        }
        return $parts ? htmlspecialchars(implode('  ', $parts), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') : '';
    }

    // Один ssh на инстанс за запрос: wgVersion() (шапка меню) и awgSupports3()
    // (гейт 3.0, дёргается из нескольких мест на одной отрисовке) делят результат.
    public function wgVersions(bool $force = false): array
    {
        $inst = $this->getInstanceWG();
        if (!$force && isset($this->wgVerCache[$inst])) {
            return $this->wgVerCache[$inst];
        }
        $out = (string) $this->ssh(
            'sh -c \'printf "wg:"; wg --version 2>/dev/null | head -1; printf "awg:"; awg --version 2>/dev/null | head -1\'',
            $inst
        );
        return $this->wgVerCache[$inst] = [
            'wg'  => $this->pickVersion($out, 'wg'),
            'awg' => $this->pickVersion($out, 'awg'),
        ];
    }

    // Версия amneziawg-tools («amneziawg-tools v3.0.20260730 - https://amnezia.org»).
    // ВАЖНО: определять поддержку 3.0 можно ТОЛЬКО по tools — amneziawg-go даже в
    // теге v3.0.3 печатает захардкоженное «amneziawg-go 0.0.20250522» (version.go),
    // так что его строка версии ни о чём не говорит.
    //
    // Кешируется в pac.json, потому что тот же ответ нужен путям без меню
    // (ротация из cron, выдача клиентских конфигов), где лишний ssh — это
    // задержка на каждый запрос.
    public function awgToolsVersion(bool $force = false): ?string
    {
        $prefix = $this->getInstanceWG(1);
        $c      = $this->getPacConf();
        $cache  = $c[$prefix . 'awg_tools_ver'] ?? null;
        if (!$force && is_array($cache) && !empty($cache['v']) && time() - (int) ($cache['at'] ?? 0) < 3600) {
            return $cache['v'];
        }
        $v = $this->wgVersions($force)['awg'] ?? null;
        if ($v === null) {
            // ssh лёг / бинаря нет — держимся за прошлое значение, если оно есть:
            // «версия неизвестна» и «версия старая» должны различаться.
            return is_array($cache) && !empty($cache['v']) ? $cache['v'] : null;
        }
        $c = $this->getPacConf();
        $c[$prefix . 'awg_tools_ver'] = ['v' => $v, 'at' => time()];
        $this->setPacConf($c);
        return $v;
    }

    // true — поддержка AWG 3.0 есть, false — заведомо нет, null — неизвестно
    // (контейнер недоступен и кеша нет). Три состояния, а не два: при null
    // включать 3.0 нельзя, но и срезать уже включённые поля нельзя — иначе
    // моргнувший ssh молча обнулит рабочую конфигурацию у всех клиентов.
    public function awgSupports3(): ?bool
    {
        $v = $this->awgToolsVersion();
        if ($v === null) {
            return null;
        }
        return version_compare(ltrim($v, 'vV'), '3.0', '>=');
    }

    // Версии из warp-контейнера (wp = образ wireguard + wgcf, warp-cli в образе
    // нет). Свежие wgcf (2.2.31+) не знают ни `--version`, ни `version`, поэтому
    // сначала читаем /etc/wgcf_version, записанный при сборке образа
    // (wireguard.dockerfile), и лишь потом пробуем обе CLI-формы для старых
    // образов; плюс показываем wireguard-tools, которым и поднимается
    // WARP-туннель. Маркеры разделяют секции одного ssh-вызова.
    public function warpVersion(): string
    {
        $out = (string) $this->ssh(
            'sh -c \'echo ===wgcf===; cat /etc/wgcf_version 2>/dev/null; wgcf --version 2>&1; wgcf version 2>&1; echo ===wg===; wg --version 2>/dev/null\'',
            'wp'
        );
        $section = function (string $name) use ($out): string {
            return preg_match('~===' . $name . '===(.*?)(?:===\w+===|$)~s', $out, $m) ? $m[1] : '';
        };
        $parts = [];
        // wgcf печатает «wgcf version X.Y.Z» (без v); строгий x.y.z токен, чтобы
        // не цепляться за мусор из usage/ошибок, если --version не поддержан.
        if (preg_match('~\bv?\d+\.\d+\.\d+\b~', $section('wgcf'), $m)) {
            $parts[] = 'wgcf: ' . ltrim($m[0], 'v');
        }
        if (preg_match('~v?\d+(?:\.\d+)+~', $section('wg'), $m)) {
            $parts[] = 'WireGuard: ' . $m[0];
        }
        return $parts ? htmlspecialchars(implode('  ', $parts), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') : '';
    }

    public function statusWg(int $page = 0)
    {
        // Lazy auto-rotation: silently regenerates I1-I5/S3-S4 if the configured
        // period has elapsed. Must run BEFORE loading pacconf so subsequent reads
        // see the freshly rotated keys.
        $this->maybeRotateAmnezia();
        $c       = $this->getPacConf();
        $conf    = $this->readConfig();
        $status  = $this->readStatus();
        if (empty($status)) {
            return [
                'text' => "Menu -> " . $this->getTitleWG() . "\n\nerror status",
                'data' => [[
                    [
                        'text'          => $this->i18n('back'),
                        'callback_data' => "/menu",
                    ],
                ]],
            ];
        }
        $clients = $this->getClients($page);
        $bt      = $c[$this->getInstanceWG(1) . 'blocktorrent'] ?? false;
        $ex      = $c[$this->getInstanceWG(1) . 'exchange'] ?? false;
        $dns     = $c[$this->getInstanceWG(1) . 'dns'] ?? false;
        $mtu     = $c[$this->getInstanceWG(1) . 'mtu'] ?? $this->mtu;
        $am      = $c[$this->getInstanceWG(1) . 'amnezia'] ?? false;
        $end     = $c[$this->getInstanceWG(1) . 'endpoint'] ?? false;

        if (!empty($am)) {
            $ak      = $this->amneziaKeys();
            // 1.x/2.0-поля печатаем как раньше; 3.0-блок сворачиваем в одну
            // строку-сводку (полный листинг — в подменю AWG 3.0), а секретный
            // HeaderProtectionKey всегда маскируется отпечатком.
            $base    = array_merge(self::AWG_KEYS_1, self::AWG_KEYS_2);
            $text[]  = '<code>' . self::amneziaKeysReport($ak, true, $base) . "</code>\n";
            $awg3    = self::amneziaKeysReport($ak, true, self::AWG_KEYS_3);
            if ($awg3 !== '') {
                $text[] = '<code>' . str_replace("\n", ' · ', $awg3) . "</code>\n";
                // Поля видны в меню, но в конфиг не попали — без этой пометки
                // пользователь уверен, что 3.0 работает. Причины две, и лечатся
                // они по-разному, поэтому различаем их в тексте.
                $eff = $this->amneziaKeysEffective();
                if ($eff != $ak) {
                    $why = !self::awgHeaderProtectionOk($ak)
                        ? 'header protection выключен: S1–S4 должны быть ≥ ' . self::AWG_HPK_MIN_S
                        : $this->awg3UnsupportedText();
                    $text[] = '⚠️ ' . htmlspecialchars($why, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . "\n";
                }
            }
        }
        $data   = [
            [
                [
                    'text'          => $this->i18n(!$bt ? 'on' : 'off') . " {$this->i18n('torrent')} ",
                    'callback_data' => "/switchTorrent $page",
                ],
                [
                    'text'          => $this->i18n(!$ex ? 'on' : 'off') . " {$this->i18n('exchange')} ",
                    'callback_data' => "/switchExchange $page",
                ],
                [
                    'text'          =>  $this->i18n('listSubnet'),
                    'callback_data' => "/subnet $page",
                ],
            ],
            [
                [
                    'text'          =>  $this->i18n('defaultDNS') . ': ' . ($dns ?: $this->dns),
                    'callback_data' => "/defaultDNS $page",
                ],
                [
                    'text'          =>  $this->i18n('defaultMTU') . ': ' . $mtu,
                    'callback_data' => "/defaultMTU $page",
                ],
            ],
            [
                [
                    'text'          => $this->i18n('endpoint') . ': ' . ($end ? $this->ip : $this->getDomain()),
                    'callback_data' => "/switchEndpoint $page",
                ],
            ],
            [
                [
                    'text'          =>  $this->i18n('add peer'),
                    'callback_data' => "/menu addpeer $page",
                ],
            ],
        ];
        // Relay для генерируемых конфигов (Endpoint через awg_address/awg_portmap
        // общих relay xray). Кнопка видна, когда есть кандидаты либо выбор ещё
        // хранит имя (даже устаревшее — чтобы его можно было снять руками).
        $wgRelays = array_filter($c['relays'] ?? [], fn($e) => !empty($e['awg_address']));
        $rlName   = (string) ($c[$this->getInstanceWG(1) . 'relay'] ?? '');
        if (!empty($wgRelays) || $rlName !== '') {
            $data[] = [
                [
                    'text'          => '🔗 ' . $this->i18n('relay') . ': ' . ($this->wgRelay() !== null ? $rlName : $this->i18n('direct')),
                    'callback_data' => "/wgRelayMenu $page",
                ],
            ];
        }
        $inst = $this->wgNum();
        if (!empty($am)) {
            $rot_period = (int) ($c[$this->getInstanceWG(1) . 'amnezia_rotation_period'] ?? 0);
            $rot_label  = $rot_period > 0 ? "rotate: every {$rot_period}d" : "rotate: off";
            array_unshift($data, [
                [
                    'text'          => "templates",
                    'callback_data' => "/amneziaTemplates $inst $page",
                ],
                [
                    'text'          => "set I1",
                    'callback_data' => "/setAmneziaI1 $inst $page",
                ],
            ]);
            array_unshift($data, [
                [
                    'text'          => "rotate now",
                    'callback_data' => "/rotateAmnezia $inst $page",
                ],
                [
                    'text'          => $rot_label,
                    'callback_data' => "/setAmneziaRotation $inst $page",
                ],
            ]);
            $ver  = self::amneziaProtoVer($c[$this->getInstanceWG(1) . 'amnezia_keys'] ?? []);
            $sup3 = $this->awgSupports3();
            // Кнопка подменю 3.0 бесполезна на заведомо старых tools — но если
            // 3.0-поля уже сохранены, показываем её, чтобы их можно было снять.
            if ($sup3 !== false || $ver === 3) {
                array_unshift($data, [
                    [
                        'text'          => '⚙ AWG 3.0' . ($ver === 3 ? ' ✅' : ($sup3 === true ? '' : ' ⛔')),
                        'callback_data' => "/awg3 $inst $page",
                    ],
                ]);
            }
            array_unshift($data, [
                [
                    'text'          => "reset obf-keys",
                    'callback_data' => "/resetAmnezia $inst $page",
                ],
                [
                    'text'          => 'proto: ' . $this->amneziaProtoLabel($ver) . ' ▸',
                    'callback_data' => "/amneziaProto $inst $page",
                ],
            ]);
        }
        array_unshift($data, [
            [
                'text'          => $this->i18n($am ? 'on' : 'off') . " amnezia",
                'callback_data' => "/switchAmnezia $inst $page",
            ],
        ]);
        if ($clients) {
            $data = array_merge($data, $clients);
        }
        if (!empty($conf['peers'])) {
            $all     = (int) ceil(count($conf['peers']) / $this->limit);
            $page    = min($page, $all - 1);
            $page    = $page == -2 ? $all - 1 : $page;
            $conf['peers'] = array_slice($conf['peers'], $page * $this->limit, $this->limit, true);
            // A peer is also "online" if its linked vless email is active right now.
            // Map peer address (AllowedIPs) -> vless email via the canonical
            // interface.Address <-> AllowedIPs link, then check the live online set.
            $onlineEmails = $this->onlineClients();
            $privEmail    = [];
            foreach (($this->getXray()['inbounds'][0]['settings']['clients'] ?? []) as $vl) {
                if (!empty($vl['awg']) && !empty($vl['email'])) {
                    $privEmail[$vl['awg']] = $vl['email'];
                }
            }
            $addrEmail = [];
            foreach ($this->readClients() as $cl) {
                $addr = $cl['interface']['Address'] ?? null;
                $priv = $cl['interface']['PrivateKey'] ?? null;
                if ($addr !== null && $priv !== null && isset($privEmail[$priv])) {
                    $addrEmail[$addr] = $privEmail[$priv];
                }
            }
            foreach ($conf['peers'] as $k => $v) {
                if (!empty($v['# PublicKey'])) {
                    $conf['peers'][$k]['online'] = 'off';
                } else {
                    $conf['peers'][$k]['status'] = $status ? $this->getStatusPeer($v['PublicKey'], $status['peers']) : 'error';
                    $conf['peers'][$k]['online'] = preg_match('~^(\d+ seconds|[12] minute)~', $conf['peers'][$k]['status']['latest handshake']) ? 'online' : '';
                }
            }
            foreach ($conf['peers'] as $k => $v) {
                if (empty($v['# PublicKey'])) {
                    preg_match_all('~([0-9.]+\.?)\s(\w+)~', $v['status']['transfer'], $m);
                    $tr = $m[0] ? ceil($m[1][1]) . '↓' . substr($m[2][1], 0, 1) . '/' . ceil($m[1][0]) . '↑' . substr($m[2][0], 0, 1) : '';
                } else {
                    $tr = '';
                }
                $vlessEmail = $addrEmail[$v['AllowedIPs'] ?? ''] ?? null;
                $vlessOn    = $vlessEmail !== null && isset($onlineEmails[$vlessEmail]);
                $circle     = $v['online'] == 'off'
                    ? '🚷'
                    : (($v['online'] === 'online' || $vlessOn) ? '🟢' : '🔴');
                $t = [
                    'name'    => $this->getName($v),
                    'time'    => $this->getTime(strtotime($v['## time'])),
                    'status'  => $circle,
                    'traffic' => $tr,
                ];
                $pad = [
                    'name'    => max(mb_strlen($t['name']), $pad['name'] ?? 0),
                    'time'    => max($t['time'] == '♾' ? 4 : mb_strlen($t['time']), $pad['time'] ?? 0),
                    'status'  => max(mb_strlen($t['status']), $pad['status'] ?? 0),
                    'traffic' => max(mb_strlen($t['traffic']), $pad['traffic'] ?? 0),
                ];
                $peers[] = $t;
            }
            foreach ($peers as $k => $v) {
                $text[] = implode('', [
                    $this->pad($v['name'], $pad['name'] - mb_strlen($v['name'])),
                    $this->pad(" {$v['time']}", $pad['time'] - mb_strlen($v['time'])),
                    $this->pad($v['status'], $pad['status'] - mb_strlen($v['status'])),
                    $this->pad(" {$v['traffic']}", $pad['traffic'] - mb_strlen($v['traffic'])),
                ]);
            }
        }
        $ver  = $this->wgVersion();
        $text = "Menu -> " . $this->getTitleWG() . ($ver ? "\n$ver" : '') . "\n\n<code>" . implode(PHP_EOL, $text ?: []) . '</code>';
        $data[] = [
            [
                'text'          => '📜 ' . $this->i18n('connection log'),
                'callback_data' => "/wgLog $inst",
            ],
        ];
        $data[] = [
            [
                'text'          =>  '🔄 ' . $this->i18n('refresh'),
                'callback_data' => "/menu wg $inst $page",
            ],
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu",
            ]
        ];
        return [
            'text' => $text,
            'data' => $data,
        ];
    }

