    public function getAmneziaShortLink($client)
    {
        $pac           = $this->getPacConf();
        $domain        = $pac[$this->getInstanceWG(1) . 'endpoint'] ? $this->ip : $this->getDomain();
        $dnsRaw        = $client['interface']['DNS'] ?: $pac[$this->getInstanceWG(1) . 'dns'] ?: $this->dns;
        $dns           = array_map('trim', explode(',', $dnsRaw));
        $ports         = $this->getPorts();
        $wgPort        = (int) $ports[$this->getInstanceWG()]['port'];
        // Relay инстанса: hostName/port ссылки — как Endpoint в createConfig()
        // (сам вложенный 'config' там уже подменён тем же wgRelay()).
        if (($relay = $this->wgRelay()) !== null) {
            $domain = $relay['awg_address'];
            $wgPort = (int) ($relay['awg_portmap'][$wgPort] ?? $wgPort);
        }
        $amneziaKeys   = $this->amneziaKeysEffective();
        // protocol_version остаётся "2" даже для набора 3.0: у приложения
        // AmneziaVPN есть только контейнеры amnezia-awg / amnezia-awg2 и
        // константы версий "1.5"/"2" (containerUtils.cpp, protocolConstants.h).
        // Сами 3.0-поля клиент читает из last_config безусловно, по тем же
        // именам ключей, что и в wg0.conf (configKeys.h) — отдельная версия
        // контейнера для них не нужна.
        $protoVer      = array_key_exists('I1', $amneziaKeys) ? "2" : "1";
        $containerName = $protoVer === "2" ? "amnezia-awg2" : "amnezia-awg";
        $c             = [
            "containers" => [
                [
                    "awg" => [
                        "isThirdPartyConfig" => true,
                        "last_config" => json_encode(array_merge(array_map('strval', $amneziaKeys), [
                            "protocol_version" => $protoVer,
                            "client_ip"        => $client['interface']['Address'],
                            "client_priv_key"  => $client['interface']['PrivateKey'],
                            "client_pub_key"   => "0",
                            "config"           => $this->createConfig($client),
                            "hostName"         => $domain,
                            "port"             => $wgPort,
                            "psk_key"          => $client['peers'][0]['PresharedKey'],
                            "server_pub_key"   => $client['peers'][0]['PublicKey'],
                            "allowed_ips"      => array_map('trim', explode(',', $client['peers'][0]['AllowedIPs'])),
                            "persistent_keep_alive" => (string) $this->awgKeepalive()
                        ])),
                        "port" => $wgPort,
                        "transport_proto" => "udp",
                        "protocol_version" => $protoVer
                    ],
                    "container" => $containerName
                ]
            ],
            "defaultContainer"  => $containerName,
            "description"       => $client['interface']['## name'],
            "dns1"              => $dns[0] ?? '',
            "dns2"              => $dns[1] ?? '',
            "hostName"          => $domain,
            "isThirdPartyConfig" => true
        ];
        $json = json_encode($c);
        $proc = proc_open('python amnezia.py', [0 => ['pipe', 'r'], 1 => ['pipe', 'w']], $pipes);
        fwrite($pipes[0], $json);
        fclose($pipes[0]);
        $result = trim(stream_get_contents($pipes[1]));
        fclose($pipes[1]);
        proc_close($proc);
        return $result;
    }

    // 'awg_for_vless' хранится как '<префикс инстанса>:<индекс клиента>'
    // (':N' / 'wg1_:N'). Старые бэкапы могли записать имя сервиса ('wg:N' /
    // 'wg1:N') — приводим к текущему формату, иначе toggle не снимает
    // привязку, а getAwgVless берёт clients-файл и ключи не того инстанса.
    public function normalizeAwgForVless($v)
    {
        [$container, $client] = array_pad(explode(':', (string) $v, 2), 2, '');
        $container = ['wg' => '', 'wg1' => 'wg1_'][$container] ?? $container;
        return $container . ':' . $client;
    }

    public function setAsVlessTransport($k, $page)
    {
        $c = $this->getPacConf();
        // Формат ключа единый с хранением и getAwgVless: префикс инстанса
        // (''/'wg1_'), а не имя контейнера — иначе сравнение никогда не
        // совпадает и повторное нажатие не снимает привязку.
        $key = $this->getInstanceWG(1) . ':' . $k;
        if (!empty($c['awg_for_vless']) && $this->normalizeAwgForVless($c['awg_for_vless']) === $key) {
            unset($c['awg_for_vless']);
        } else {
            $c['awg_for_vless'] = $key;
        }
        $this->setPacConf($c);
        $this->menu('wg', $page);
    }

    public function getAwgVless()
    {
        $c = $this->getPacConf();
        if (empty($c['awg_for_vless'])) {
            return false;
        }
        $v         = $this->normalizeAwgForVless($c['awg_for_vless']);
        $container = explode(':', $v)[0];
        $client    = explode(':', $v)[1];
        if ($client === '') {
            return false;
        }

        // Клиентов читаем через readClients() с временным переопределением
        // инстанса ($this->wg резолвится раньше глобального wg_instance) —
        // тот же приём, что в shutdownClient/export/syncPortClients.
        $prev = $this->wg ?? null;
        $this->wg = $container === 'wg1_' ? 1 : 0;
        $clients = $this->readClients();
        $this->wg = $prev;
        if (empty($clients[$client])) {
            return false;
        }
        return [
            // Блок 3.0 уезжает в mihomo только при включённом тумблере
            // mihomo_awg3: его понимают лишь свежие сборки, а нужные ИМЕНА
            // полей у mihomo свои (см. MIHOMO_AWG3_KEYS).
            // Набор прогоняем через amneziaKeysUsable() — тот же срез, что
            // уходит в wg0.conf: иначе подписка объявила бы клиенту header
            // protection, которого на сервере нет, и handshake молча не прошёл
            // бы. Версию tools берём из кеша: ssh на пути подписки нельзя.
            "amnezia-wg-option" => self::amneziaKeysForMihomo(
                self::amneziaKeysUsable(
                    $c["{$container}amnezia_keys"] ?? '',
                    $this->awgSupports3Cached($container)
                ),
                !empty($c['mihomo_awg3'])
            ),
            "pre-shared-key"    => $c["{$container}presharedkey"] ?? '',
            // Диапазон приводится к числу уже на месте сборки прокси
            // (keepaliveInt): ssh сюда звать нельзя — это путь подписки.
            "persistent-keepalive" => $c["{$container}amnezia_keepalive"] ?? 20,
            "server"            => explode(':', $clients[$client]['peers'][0]['Endpoint'])[0],
            "port"              => explode(':', $clients[$client]['peers'][0]['Endpoint'])[1],
            "ip"                => explode('/', $clients[$client]['interface']['Address'])[0],
            "private-key"       => $clients[$client]['interface']['PrivateKey'],
            "public-key"        => $clients[$client]['peers'][0]['PublicKey'],
            "mtu"               => $c["{$container}mtu"] ?? $this->mtu,
        ];

    }

    public function getClient($client, $page)
    {
        $clients = $this->readClients();
        if ($clients) {
            // Имя клиента — сырой ввод (renameClient/addWg) и уходит в parse_mode
            // HTML. Без экранирования имя вида «Home <PC>» даёт невалидную
            // разметку → Telegram 400 → карточка не открывается уже НИКОГДА,
            // потому что имя лежит в clients.json. $conf экранировали, имя нет.
            $name = htmlspecialchars($this->getName($clients[$client]['interface']));
            $conf = htmlspecialchars($this->createConfig($clients[$client]));
            $sl   = '';
            if ($this->getWGType() == 'awg') {
                $sl = htmlspecialchars($this->getAmneziaShortLink($clients[$client]));
            }
            return [
                'text' => "<pre>$conf</pre>\n\n<code>$sl</code>\n\n<b>$name</b> ({$this->getTitleWG()})",
                'data' => [
                    [
                        [
                            'text'          =>  $this->i18n('rename'),
                            'callback_data' => "/rename {$client}_$page",
                        ],
                        [
                            'text'          =>  $this->i18n('timer'),
                            'callback_data' => "/timer {$client}_$page",
                        ],
                    ],
                    [
                        [
                            'text'          => $this->i18n('show QR'),
                            'callback_data' => "/qr $client",
                        ],
                        [
                            'text'          => $this->i18n('download config'),
                            'callback_data' => "/download $client",
                        ],
                    ],
                    [
                        [
                            'text'          => $this->i18n($clients[$client]['# off'] ? 'off' : 'on'),
                            'callback_data' => "/switchClient {$client}_$page",
                        ],
                        [
                            'text'          => $this->i18n($clients[$client]['interface']['DNS'] ? 'delete internal dns' : 'set internal dns'),
                            'callback_data' => "/" . ($clients[$client]['interface']['DNS'] ? 'delete' : '') . "dns {$client}_$page",
                        ],
                    ],
                    [
                        [
                            'text'          => $this->i18n('AllowedIPs'),
                            'callback_data' => "/changeAllowedIps {$client}_$page",
                        ],
                    ],
                    [
                        [
                            'text'          => $this->i18n('MTU') . " " . ($clients[$client]['interface']['MTU'] ?: $this->getPacConf()[$this->getInstanceWG(1) . 'mtu'] ?: $this->mtu),
                            'callback_data' => "/changeMTU {$client}_$page",
                        ],
                    ],
                    [
                        [
                            'text'          => '📜 ' . $this->i18n('connection log'),
                            'callback_data' => "/wgClientLog {$this->wgNum()} {$client} $page",
                        ],
                    ],
                    [
                        [
                            'text'          => $this->i18n('delete'),
                            'callback_data' => "/delete {$client}_$page",
                        ],
                        [
                            'text'          => $this->i18n('back'),
                            'callback_data' => "/menu wg {$this->wgNum()} $page",
                        ],
                    ],
                ],
            ];
        }
        return [
            'text' => "no clients",
            'data' => false
        ];
    }

    public function setVlessLink($cl, $wg, $page_wg = 0)
    {
        $c = $this->getXray();
        $w = $this->readClients();
        $privatekey = $w[$wg]['interface']['PrivateKey'];
        foreach ($c['inbounds'][0]['settings']['clients'] as $i => $j) {
            if ($i == $cl) {
                $c['inbounds'][0]['settings']['clients'][$i]['awg'] = $privatekey;
            } elseif (!empty($j['awg']) && $j['awg'] == $privatekey) {
                unset($c['inbounds'][0]['settings']['clients'][$i]['awg']);
            }
        }
        $this->restartXray($c, 1);
        $this->menu('wg', $page_wg);
    }

    public function unsetVlessLink($wg, $page_wg = 0)
    {
        $c = $this->getXray();
        $w = $this->readClients();
        $privatekey = $w[$wg]['interface']['PrivateKey'];
        foreach ($c['inbounds'][0]['settings']['clients'] as $i => $j) {
            if (!empty($j['awg']) && $j['awg'] == $privatekey) {
                unset($c['inbounds'][0]['settings']['clients'][$i]['awg']);
            }
        }
        $this->restartXray($c, 1);
        $this->menu('wg', $page_wg);
    }

    public function choiceVless($i, $page_wg = 0, $page_vl = 0)
    {
        $c = $this->getXray();

        $text[] = "Menu -> " . $this->i18n('link awg');

        $data[] = [
            [
                'text'          => $this->i18n('delete'),
                'callback_data' => "/unsetVlessLink {$i}_$page_wg",
            ],
        ];

        $clients = array_filter($c['inbounds'][0]['settings']['clients'], fn($e) => empty($e['off']));
        uasort($clients, fn($a, $b) => ($a['time'] ?: PHP_INT_MAX) <=> ($b['time'] ?: PHP_INT_MAX));

        $all     = (int) ceil(count($clients) / $this->limit);
        $page_vl = min($page_vl, $all - 1);
        $page_vl = $page_vl == -2 ? $all - 1 : $page_vl;
        $clients = $page_vl != -1 ? array_slice($clients, $page_vl * $this->limit, $this->limit, true) : $clients;
        foreach ($clients as $k => $v) {
            $data[]   = [
                [
                    'text'          => "{$v['email']}",
                    'callback_data' => "/setVlessLink {$k}_{$i}_$page_wg",
                ],
            ];
        }
        if ($page_vl != -1 && $all > 1) {
            $data[] = [
                [
                    'text'          => '<<',
                    'callback_data' => "/choiceVless {$i}_{$page_wg}_" . ($page_vl - 1 >= 0 ? $page_vl - 1 : $all - 1),
                ],
                [
                    'text'          => $page_vl + 1,
                    'callback_data' => "/choiceVless {$i}_{$page_wg}_$page_vl",
                ],
                [
                    'text'          => '>>',
                    'callback_data' => "/choiceVless {$i}_{$page_wg}_" . ($page_vl < $all - 1 ? $page_vl + 1 : 0),
                ],
            ];
        }

        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu wg {$this->wgNum()} $page_wg",
            ],
        ];
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text ?? ['...']),
            $data ?: false,
        );
    }

    public function getClients(int $page, int $count = 5)
    {
        $count   = $this->limit;
        $clients = $this->readClients();
        if (!empty($clients)) {
            $all     = (int) ceil(count($clients) / $count);
            $page    = min($page, $all - 1);
            $page    = $page == -2 ? $all - 1 : $page;
            $clients = $page != -1 ? array_slice($clients, $page * $count, $count, true) : $clients;
            $c = $this->getXray();
            foreach ($clients as $k => $v) {
                $vless = false;
                foreach ($c['inbounds'][0]['settings']['clients'] as $vl) {
                    if (!empty($vl['awg']) && $vl['awg'] == $v['interface']['PrivateKey']) {
                        $vless = $vl['email'];
                        break;
                    }
                }
                $data[] = [
                    [
                        'text'          => $this->getName($v['interface']),
                        'callback_data' => "/menu client {$k}_$page",
                    ],
                    [
                        'text'          => $this->i18n('vless') . ': ' . $this->i18n($vless != false ? 'on' : 'off') . ($vless != false ? " $vless" : ''),
                        'callback_data' => "/choiceVless {$k}_{$page}_0",
                    ],
                ];
            }
            if ($page != -1 && $all > 1) {
                $inst = $this->wgNum();
                $data[] = [
                    [
                        'text'          => '<<',
                        'callback_data' => "/menu wg $inst " . ($page - 1 >= 0 ? $page - 1 : $all - 1),
                    ],
                    [
                        'text'          => $page + 1,
                        'callback_data' => "/menu wg $inst $page",
                    ],
                    [
                        'text'          => '>>',
                        'callback_data' => "/menu wg $inst " . ($page < $all - 1 ? $page + 1 : 0),
                    ]
                ];
            }
        }
        return $data;
    }

    public function sizeFormat($bytes)
    {
        if (floor($bytes / 1024 ** 2) > 0) {
            $r = round($bytes / 1024 ** 2, 2) . 'MB';
        } elseif (floor($bytes / 1024) > 0) {
            $r = round($bytes / 1024, 2) . 'KB';
        } else {
            $r = $bytes . 'B';
        }
        return $r;
    }

    public function addCommunityFilter()
    {
        $pac = $this->getPacConf();
        $l   = array_filter(array_map(fn($e) => trim($e), explode("\n", file_get_contents('https://community.antifilter.download/list/domains.lst'))));
        if (!empty($l)) {
            foreach ($l as $k => $v) {
                $pac['includelist'][$v] = true;
            }
        }
        $this->setPacConf($pac);
        $this->pacUpdate();
    }

    public function addLegizFilter()
    {
