                            [
                                // Возраст кэша статусов: видно, насколько свежи
                                // on/off в тексте меню; нажатие — живые пробы.
                                'text'          => ($age = $this->menuStatusAge()) === null ? '🔄 status: …' : "🔄 status: {$age}s ago",
                                'callback_data' => '/refreshMain',
                            ],
                        ],
                    ],
                )
            ],
            'wg'           => $type == 'wg'      ? $this->statusWg($arg)                   : false,
            'client'       => $type == 'client'  ? $this->getClient(...explode('_', $arg)) : false,
            'addpeer'      => $type == 'addpeer' ? $this->addWg(...explode('_', $arg))     : false,
            'pac'          => $type == 'pac'     ? $this->pacMenu((int) $arg)              : false,
            'adguard'      => $type == 'adguard' ? $this->adguardMenu()                    : false,
            'config'       => $type == 'config'  ? $this->configMenu()                     : false,
            'ss'           => $type == 'ss'      ? $this->menuSS()                         : false,
            'lang'         => $type == 'lang'    ? $this->menuLang()                       : false,
            'oc'           => $type == 'oc'      ? $this->ocMenu()                         : false,
            'naive'        => $type == 'naive'   ? $this->naiveMenu()                      : false,
            'hy'           => $type == 'hy'      ? $this->hysteriaMenu()                   : false,
            'tt'           => $type == 'tt'      ? $this->ttMenu()                         : false,
            'ovpn'         => $type == 'ovpn'    ? $this->ovpnMenu()                       : false,
            'l2tp'         => $type == 'l2tp'    ? $this->l2tpMenu()                       : false,
            'ikev2'        => $type == 'ikev2'   ? $this->ikev2Menu()                      : false,
            'mirror'       => $type == 'mirror'  ? $this->mirrorMenu()                     : false,
            'update'       => $type == 'update'  ? $this->updatebot()                      : false,
        ];

        $text = $menu[$type ?: 'main' ]['text'];
        $data = $menu[$type ?: 'main' ]['data'];

        if (empty($type) && $update) {
            $b = exec('git -C / rev-parse --abbrev-ref HEAD');
            array_unshift($data, [
                [
                    'text'    => 'changelog',
                    'web_app' => ['url' => "https://$domain/pac$hash?t=changelog"],
                ],
                [
                    'text'          => $this->i18n('update bot'),
                    'callback_data' => "/applyupdatebot",
                ],
            ]);
        }

        if ($return) {
            return [$text, $data];
        }

        if (!empty($this->input['callback_id'])) {
            $this->update(
                $this->input['chat'],
                $this->input['message_id'],
                $text,
                $data ?: false,
            );
            // Сообщение показывает wg-меню (или его подменю) — фиксируем его
            // инстанс в карте; любое другое меню — снимаем запись, чтобы
            // устаревшая привязка не влияла на кнопки нового содержимого.
            if (in_array($type, ['wg', 'client', 'addpeer'], true)) {
                $this->setWgMsg($this->wgNum());
            } else {
                $this->setWgMsg(null);
            }
        } else {
            $this->send(
                $this->input['chat'],
                $text,
                $this->input['message_id'],
                $data ?: false,
            );
        }
    }

    public function switchScanIp()
    {
        $c = $this->getPacConf();
        $c['autoscan'] = $c['autoscan'] ? 0 : 1;
        $this->setPacConf($c);
        $this->ipMenu();
    }

    public function switchBanIp()
    {
        $c = $this->getPacConf();
        $c['autodeny'] = $c['autodeny'] ? 0 : 1;
        $this->setPacConf($c);
        $this->ipMenu();
    }

    public function switchMonthlyStats()
    {
        $c = $this->getPacConf();
        $c['reset_monthly'] = $c['reset_monthly'] ? 0 : 1;
        $this->setPacConf($c);
        $this->xray();
    }

    // uTLS fingerprints offered in the menu. All are valid Xray uTLS ids; for
    // sing-box / clash configs the Xray-only ids (randomizednoalpn, unsafe) are
    // normalized away in subscription() because those cores don't accept them.
    public function fingerprints()
    {
        return ['chrome', 'firefox', 'safari', 'ios', 'android', 'edge', '360', 'qq', 'random', 'randomized', 'randomizednoalpn', 'unsafe'];
    }

    public function changeFingerprint($fingerprint = false)
    {
        $allowed = $this->fingerprints();
        $c       = $this->getPacConf();
        if ($fingerprint && in_array($fingerprint, $allowed, true)) {
            $c['fingerprint'] = $fingerprint;
        } else {
            // bare call (no/invalid arg): cycle to the next fingerprint in the list
            $current          = ($c['fingerprint'] ?? '') ?: 'chrome';
            $i                = array_search($current, $allowed, true);
            $c['fingerprint'] = $allowed[($i === false ? 0 : $i + 1) % count($allowed)];
        }
        $this->setPacConf($c);
        $this->fingerprintMenu();
    }

    public function fingerprintMenu()
    {
        $current = $this->getPacConf()['fingerprint'] ?: 'chrome';
        $text[]  = "Menu -> " . $this->i18n('xray') . ' -> ' . $this->i18n('fingerprint');
        $text[]  = $this->i18n('fingerprint') . ': <code>' . $current . '</code>';

        $data = [];
        $row  = [];
        foreach ($this->fingerprints() as $fp) {
            $row[] = [
                'text'          => ucfirst($fp) . ' ' . ($current === $fp ? $this->i18n('on') : $this->i18n('off')),
                'callback_data' => "/changeFingerprint $fp",
            ];
            if (count($row) === 2) {
                $data[] = $row;
                $row    = [];
            }
        }
        if ($row) {
            $data[] = $row;
        }
        $data[] = [[
            'text'          => $this->i18n('back'),
            'callback_data' => '/xray',
        ]];

        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text),
            $data,
        );
    }

    // ---- DPI masking submenu (items 1/2/4/5). Everything defaults OFF; each row
    // is an independent toggle/value so a technique can be disabled or retuned if
    // it trips DPI or breaks clients, without code changes. ----
    public function dpiMenu()
    {
        $p  = $this->getPacConf();
        $f  = $p['dpi']['fragment'] ?? [];
        $n  = $p['dpi']['noise'] ?? [];
        $r  = $p['reality'] ?? [];
        $x  = $this->getXray();
        $s  = $this->sniffingSettings($p, $x['inbounds'][0]['sniffing'] ?? null);
        $tr = $p['transport'] ?? '';
        $on = fn($v) => $this->i18n(!empty($v) ? 'on' : 'off');
        $spiderX = $this->normalizeSpiderXValue((string) ($r['spiderX'] ?? ''));
        $mldsaReady = $this->mldsaReady($p);

        $text[] = "Menu -> " . $this->i18n('xray') . ' -> ' . $this->i18n('dpi masking');
        $text[] = $this->i18n('dpi hint');

        $data = [];
        $data[] = [['text' => $this->i18n('fragment') . ': ' . $on($f['enabled'] ?? 0), 'callback_data' => '/dpiToggle fragment']];
        if (!empty($f['enabled'])) {
            $text[] = $this->dpiFieldHint('fragment');
            $data[] = [
                ['text' => 'packets: ' . (($f['packets'] ?? '') ?: '1-3'),    'callback_data' => '/dpiSet fragment_packets'],
                ['text' => 'length: ' . (($f['length'] ?? '') ?: '100-200'),  'callback_data' => '/dpiSet fragment_length'],
                ['text' => 'interval: ' . (($f['interval'] ?? '') ?: '10-20'), 'callback_data' => '/dpiSet fragment_interval'],
            ];
            // maxSplit — потолок числа фрагментов; пусто = без лимита (дефолт
            // xray), поэтому показываем «—», а не число.
            $data[] = [
                ['text' => 'maxSplit: ' . (($f['maxSplit'] ?? '') ?: '—'), 'callback_data' => '/dpiSet fragment_maxSplit'],
            ];
            // Готовые наборы спрятаны в отдельное подменю (/dpiFragPresets),
            // чтобы не загромождать основное DPI-меню семью кнопками.
            $data[] = [['text' => '📋 ' . $this->i18n('presets'), 'callback_data' => '/dpiFragPresets']];
        }
        $data[] = [['text' => $this->i18n('noise') . ': ' . $on($n['enabled'] ?? 0), 'callback_data' => '/dpiToggle noise']];
        if (!empty($n['enabled'])) {
            // noises в xray-freedom применяется ТОЛЬКО к UDP-соединениям; все
            // транспорты Vless тут (Reality/Websocket/xhttp/trojan-grpc) — TCP,
            // поэтому по туннелю шум не отправляется и DPI не маскирует. Явно
            // предупреждаем, чтобы не собрать бесполезную комбинацию (noise ON,
            // fragment OFF). $tr пуст только до выбора транспорта.
            if ($tr !== '') {
                $text[] = str_replace('%s', htmlspecialchars($tr, ENT_QUOTES), $this->i18n('noise tcp warn'));
            }
            $text[] = $this->dpiFieldHint('noise');
            // Готовые примеры значений — прямо в тексте меню, а не только во
            // всплывающей подсказке по тапу (её легко пропустить).
            $text[] = $this->noiseExamplesHint();
            // noises — массив: несколько пакетов с разными типами/задержками
            // эффективнее против анализа трафика, чем один фиксированный.
            $noises = $this->dpiNoiseList($p);
            foreach ($noises as $i => $ne) {
                $data[] = [
                    ['text' => 'type: ' . (($ne['type'] ?? '') ?: 'rand'),      'callback_data' => "/dpiSet noise{$i}_type"],
                    ['text' => 'packet: ' . (($ne['packet'] ?? '') ?: '10-20'), 'callback_data' => "/dpiSet noise{$i}_packet"],
                    ['text' => 'delay: ' . (($ne['delay'] ?? '') ?: '10-16'),   'callback_data' => "/dpiSet noise{$i}_delay"],
                    ['text' => '🗑',                                            'callback_data' => "/dpiNoiseDel {$i}"],
                ];
            }
            $data[] = [
                ['text' => '➕ noise packet',                        'callback_data' => '/dpiNoiseAdd'],
                ['text' => '📋 ' . $this->i18n('presets'),           'callback_data' => '/dpiNoisePresets'],
            ];
        }
        $text[] = "\n" . $this->i18n('sniffing');
        $data[] = [['text' => $this->i18n('sniffing') . ': ' . $on($s['enabled'] ?? 0), 'callback_data' => '/dpiToggle sniffing']];
        if (!empty($s['enabled'])) {
            $data[] = [[
                'text' => 'destOverride: ' . $this->shortListLabel($s['destOverride'] ?? []),
                'callback_data' => '/dpiSet sniffing_destOverride',
            ]];
            $data[] = [
                ['text' => 'metadataOnly: ' . $on($s['metadataOnly'] ?? 0), 'callback_data' => '/dpiToggle sniffingMetadataOnly'],
                ['text' => 'routeOnly: ' . $on($s['routeOnly'] ?? 0),       'callback_data' => '/dpiToggle sniffingRouteOnly'],
            ];
            $data[] = [
                ['text' => 'ipsExcluded: ' . $this->shortListLabel($s['ipsExcluded'] ?? []),         'callback_data' => '/dpiSet sniffing_ipsExcluded'],
                ['text' => 'domainsExcluded: ' . $this->shortListLabel($s['domainsExcluded'] ?? []), 'callback_data' => '/dpiSet sniffing_domainsExcluded'],
            ];
        }
        if ($tr === 'Reality') {
            $data[] = [
                ['text' => $this->i18n('mldsa') . ': ' . $on($mldsaReady), 'callback_data' => '/dpiToggle mldsa'],
                ['text' => '🎲 ' . $this->i18n('autogen'),                 'callback_data' => '/dpiGenMldsa'],
                ['text' => $this->i18n('clear'),                           'callback_data' => '/dpiDefault r_mldsa65'],
            ];
            $text[] = 'mldsa65 Seed: ' . $this->shortSecretLabel($r['mldsa65Seed'] ?? '');
            $text[] = 'mldsa65 Verify: ' . $this->shortSecretLabel($r['mldsa65Verify'] ?? '');
            $text[] = 'spiderX: <code>' . htmlspecialchars($spiderX ?: '/', ENT_QUOTES) . '</code>';
            // Полные значения не влезают в текст меню (Verify ~2.6k символов) —
            // отдаём отдельным сообщением в <code>, чтобы копировались тапом.
            $data[] = [['text' => '📋 mldsa65 Seed/Verify', 'callback_data' => '/dpiShowMldsa']];
            $data[] = [
                ['text' => 'maxTimeDiff: ' . (int) ($r['maxTimeDiff'] ?? 0), 'callback_data' => '/dpiSet r_maxTimeDiff'],
                ['text' => 'xver: ' . (int) ($r['xver'] ?? 0),               'callback_data' => '/dpiSet r_xver'],
            ];
            $data[] = [
                ['text' => 'minClientVer: ' . (($r['minClientVer'] ?? '') ?: '—'), 'callback_data' => '/dpiSet r_minClientVer'],
                ['text' => 'maxClientVer: ' . (($r['maxClientVer'] ?? '') ?: '—'), 'callback_data' => '/dpiSet r_maxClientVer'],
            ];
            $data[] = [
                ['text' => 'spiderX: ' . ($spiderX ?: '—'),              'callback_data' => '/dpiSet r_spiderX'],
                ['text' => '🎲 ' . $this->i18n('autogen'),               'callback_data' => '/dpiGenSpiderX'],
                ['text' => $this->i18n('default'),                       'callback_data' => '/dpiDefault r_spiderX'],
            ];
        }
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => '/xray']];

        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data);
    }

    // Проверенные наборы фрагментации (packets · length · interval · maxSplit).
    // Все — для скрытия SNI, кроме 'stream' (режет первые TCP-записи, когда
    // tlshello не помогает). Значения подобраны так, чтобы граница между
    // кусками попадала внутрь зоны SNI (~100–300 б), а maxSplit ограничивал
    // число пакетов. Единый источник для кнопок меню и подсказки.
    public function fragmentPresets(): array
    {
        $ru = $this->language === 'ru';
        return [
            'sni' => [
                'label'    => $ru ? '🎯 Скрытие SNI (реком.)' : '🎯 SNI hide (rec.)',
                'packets'  => 'tlshello', 'length' => '10-50', 'interval' => '10-20', 'maxSplit' => '4-8',
            ],
            'universal' => [
                'label'    => $ru ? '🌊 Универсальный' : '🌊 Universal',
                'packets'  => 'tlshello', 'length' => '100-200', 'interval' => '10-20', 'maxSplit' => '',
            ],
            'gentle' => [
                'label'    => $ru ? '🍃 Мягкий' : '🍃 Gentle',
                'packets'  => 'tlshello', 'length' => '40-80', 'interval' => '10-20', 'maxSplit' => '2-3',
            ],
            'fast' => [
                'label'    => $ru ? '⚡ Быстрый' : '⚡ Fast (low latency)',
                'packets'  => 'tlshello', 'length' => '40-100', 'interval' => '1-3', 'maxSplit' => '3-5',
            ],
            'aggressive' => [
                'label'    => $ru ? '🛡 Агрессивный (ПК)' : '🛡 Aggressive (PC)',
                'packets'  => 'tlshello', 'length' => '6-16', 'interval' => '5-10', 'maxSplit' => '10-20',
            ],
            'mobile' => [
                'label'    => $ru ? '📱 Мобильный (экономный)' : '📱 Mobile (battery)',
                'packets'  => 'tlshello', 'length' => '40-80', 'interval' => '20-40', 'maxSplit' => '2-3',
            ],
            'reality' => [
                'label'    => $ru ? '🔮 Reality-оптим.' : '🔮 Reality-tuned',
                'packets'  => 'tlshello', 'length' => '20-40', 'interval' => '10-20', 'maxSplit' => '5-8',
            ],
            'tspu' => [
                'label'    => $ru ? '🧱 Против ТСПУ/РКН' : '🧱 Anti-TSPU',
                'packets'  => 'tlshello', 'length' => '2-8', 'interval' => '3-8', 'maxSplit' => '15-30',
            ],
            'stream' => [
                'label'    => $ru ? '🧬 Весь поток (1-5)' : '🧬 Whole stream (1-5)',
                'packets'  => '1-5', 'length' => '40-80', 'interval' => '10-20', 'maxSplit' => '',
