                    ['type' => 'rand', 'packet' => '300-600', 'delay' => '20-40'],
                    ['type' => 'rand', 'packet' => '600-900', 'delay' => '30-60'],
                ],
            ],
            'dns' => [
                'label' => $ru ? '🌐 Под DNS' : '🌐 DNS-like',
