            ],
            'quic' => [
                'label' => $ru ? '⚡ Под QUIC' : '⚡ QUIC-like',
                'list'  => [['type' => 'rand', 'packet' => '1200-1252', 'delay' => '10-20']],
            ],
            'wireguard' => [
                'label' => $ru ? '🔒 Под WireGuard' : '🔒 WireGuard-like',
                'list'  => [['type' => 'rand', 'packet' => '148', 'delay' => '5-10']],
