    // Текстовая расшифровка noise-шаблонов: имя → последовательность пакетов.
    public function noisePresetsHint(): string
    {
        $ru = $this->language === 'ru';
        $lines = [$ru
            ? "Шаблоны UDP-шума (последовательность type·packet·delay) — тап применяет:"
            : "UDP noise presets (sequence type·packet·delay) — a tap applies:"];
        foreach ($this->noisePresets() as $ps) {
            $parts = [];
            foreach ($ps['list'] as $pk) {
                $pkt = mb_strlen($pk['packet']) > 14 ? mb_substr($pk['packet'], 0, 12) . '…' : $pk['packet'];
                $parts[] = "<code>{$pk['type']}·{$pkt}·{$pk['delay']}</code>";
            }
            $lines[] = "• {$ps['label']}: " . implode(' + ', $parts);
        }
        return implode("\n", $lines);
    }

    // Подменю noise-шаблонов: легенда + кнопки (по 2 в ряд) + назад.
    public function dpiNoisePresetsMenu(): void
    {
        $text[] = 'Menu -> ' . $this->i18n('xray') . ' -> ' . $this->i18n('dpi masking') . ' -> ' . $this->i18n('noise') . ' ' . $this->i18n('presets');
        $text[] = $this->noisePresetsHint();

        $data = [];
        $row = [];
        foreach ($this->noisePresets() as $key => $ps) {
            $row[] = ['text' => $ps['label'], 'callback_data' => "/dpiNoisePreset $key"];
            if (count($row) === 2) {
                $data[] = $row;
                $row = [];
            }
        }
        if ($row) {
            $data[] = $row;
        }
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => '/dpiMenu']];

        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data);
    }

    // Применить noise-шаблон: заменяет список пакетов и включает noise.
    // Клиентская настройка (freedom-outbound в подписке) — рестарт xray не нужен.
    public function dpiNoisePreset($key): void
    {
        $presets = $this->noisePresets();
        if (!isset($presets[$key])) {
            $this->answer($this->input['callback_id'], 'unknown preset', true);
            return;
        }
        $ps = $presets[$key];
        $p = $this->getPacConf();
        $p['dpi']['noise']['enabled'] = 1;
        $p['dpi']['noise']['list']    = $ps['list'];
        // Legacy одиночный noise больше не источник истины — убираем, как в dpiNoiseAdd.
        unset($p['dpi']['noise']['type'], $p['dpi']['noise']['packet'], $p['dpi']['noise']['delay']);
        $this->setPacConf($p);
        $this->answer($this->input['callback_id'], $ps['label']);
        $this->dpiMenu();
    }

    // Push the configurable Reality extras (mldsa seed + hardening params) onto the
    // running inbound and restart, so toggles/edits take effect immediately.
    public function syncRealityLive(array $p): void
    {
        $x = $this->getXray();
        if (!empty($x['inbounds'][0]['streamSettings']['realitySettings'])) {
            $this->applyRealityServerExtras($x['inbounds'][0]['streamSettings']['realitySettings'], $p);
            $this->restartXray($x);
        }
    }

    public function defaultSniffingSettings(): array
    {
        return [
            'enabled'         => true,
            'destOverride'    => ['http', 'tls', 'quic'],
            'metadataOnly'    => false,
            'routeOnly'       => false,
            'ipsExcluded'     => [],
            'domainsExcluded' => [],
        ];
    }

    public function sniffingSettings(array $p, ?array $fallback = null): array
    {
        $raw = is_array($p['sniffing'] ?? null) ? $p['sniffing'] : ($fallback ?: []);
        $d = $this->defaultSniffingSettings();
        $dest = $this->parseSniffingDest($raw['destOverride'] ?? $d['destOverride']);

        return [
            'enabled'         => (bool) ($raw['enabled'] ?? $d['enabled']),
            'destOverride'    => $dest ?: $d['destOverride'],
            'metadataOnly'    => (bool) ($raw['metadataOnly'] ?? false),
            'routeOnly'       => (bool) ($raw['routeOnly'] ?? false),
            'ipsExcluded'     => $this->parseListValue($raw['ipsExcluded'] ?? []),
            'domainsExcluded' => $this->parseListValue($raw['domainsExcluded'] ?? []),
        ];
    }

    public function sniffingConfig(array $p): array
    {
        $s = $this->sniffingSettings($p);
        if (empty($s['enabled'])) {
            return ['enabled' => false];
        }

        $out = [
            'enabled'      => true,
            'destOverride' => $s['destOverride'],
        ];
        if (!empty($s['metadataOnly'])) {
            $out['metadataOnly'] = true;
        }
        if (!empty($s['routeOnly'])) {
            $out['routeOnly'] = true;
        }
        if (!empty($s['ipsExcluded'])) {
            $out['ipsExcluded'] = $s['ipsExcluded'];
        }
        if (!empty($s['domainsExcluded'])) {
            $out['domainsExcluded'] = $s['domainsExcluded'];
        }
        return $out;
    }

    public function parseSniffingDest($value): array
    {
        $items = is_array($value) ? $value : preg_split('~[\s,;]+~', strtolower((string) $value));
        // FakeDNS needs a matching dns/fakeDns config block; the bot does not
        // manage that yet, so keep it out of generated configs.
        $allowed = ['http', 'tls', 'quic'];
        $out = [];
        foreach ($items ?: [] as $v) {
            $v = strtolower(trim((string) $v));
            if (in_array($v, $allowed, true) && !in_array($v, $out, true)) {
                $out[] = $v;
            }
        }
        return $out;
    }

    public function parseListValue($value): array
    {
        $items = is_array($value) ? $value : preg_split('~[\s,;]+~', (string) $value);
        $out = [];
        foreach ($items ?: [] as $v) {
            $v = trim((string) $v);
            if ($v !== '' && !$this->isDefaultValue($v) && !in_array($v, $out, true)) {
                $out[] = $v;
            }
        }
        return $out;
    }

    public function shortListLabel(array $items): string
    {
        if (empty($items)) {
            return '—';
        }
        $label = implode(',', $items);
        return strlen($label) > 28 ? count($items) . ' items' : $label;
    }

    public function applySniffingToXray(array &$c, array $p): void
    {
        if (!is_array($p['sniffing'] ?? null)) {
            return;
        }

        $sniffing = $this->sniffingConfig($p);
        foreach ($c['inbounds'] as &$inbound) {
            // Only the client-facing proxy inbound (the one with clients). Leave the
            // internal api/wg-in inbounds alone — overwriting wg-in's own sniffing
            // (e.g. disabling it) would silently break WG-over-xray domain routing.
            if (empty($inbound['settings']['clients'])) {
                continue;
            }
            $inbound['sniffing'] = $sniffing;
        }
        unset($inbound);
    }

    public function syncSniffingLive(array $p): void
    {
        $x = $this->getXray();
        $this->applySniffingToXray($x, $p);
        $this->restartXray($x);
    }

    public function isDefaultValue(string $val): bool
    {
        return in_array(strtolower(trim($val)), ['', '0', 'default', 'off', 'none', 'null', '-'], true);
    }

    public function normalizeSpiderXValue(string $val): string
    {
        $val = trim($val);
        if ($this->isDefaultValue($val)) {
            return '';
        }
        return str_starts_with($val, '/') ? $val : '/' . $val;
    }

    public function rawUrlBase64DecodedLength(string $value): int
    {
        $value = trim($value);
        if ($value === '' || preg_match('~^[A-Za-z0-9_-]+$~', $value) !== 1) {
            return -1;
        }
        $mod = strlen($value) % 4;
        if ($mod === 1) {
            return -1;
        }
        if ($mod > 0) {
            $value .= str_repeat('=', 4 - $mod);
        }
        $decoded = base64_decode(strtr($value, '-_', '+/'), true);
        return $decoded === false ? -1 : strlen($decoded);
    }

    public function isRawUrlBase64DecodedLength(string $value, int $bytes): bool
    {
        return $this->rawUrlBase64DecodedLength($value) === $bytes;
    }

    public function mldsaKeysValid(array $p): bool
    {
        return $this->isRawUrlBase64DecodedLength((string) ($p['reality']['mldsa65Seed'] ?? ''), 32)
            && $this->isRawUrlBase64DecodedLength((string) ($p['reality']['mldsa65Verify'] ?? ''), 1952);
    }

    public function mldsaReady(array $p): bool
    {
        return !empty($p['reality']['mldsa'])
            && $this->mldsaKeysValid($p);
    }

    public function shortSecretLabel($value): string
    {
        $value = (string) $value;
        if ($value === '') {
            return '—';
        }
        $len = strlen($value);
        if ($len <= 24) {
            return $value;
        }
        return substr($value, 0, 8) . '...' . substr($value, -8) . " ($len)";
    }

    public function dpiToggle($what)
    {
        $p = $this->getPacConf();
        switch ($what) {
            case 'fragment':
                $p['dpi']['fragment']['enabled'] = empty($p['dpi']['fragment']['enabled']) ? 1 : 0;
                $this->setPacConf($p);
                break;
            case 'noise':
                $p['dpi']['noise']['enabled'] = empty($p['dpi']['noise']['enabled']) ? 1 : 0;
                // При включении с пустым списком засеваем один дефолтный пакет,
                // чтобы в меню сразу была видна редактируемая строка noise.
                if (!empty($p['dpi']['noise']['enabled']) && !$this->dpiNoiseList($p)) {
                    $p['dpi']['noise']['list'] = [['type' => 'rand', 'packet' => '10-20', 'delay' => '10-16']];
                }
                $this->setPacConf($p);
                break;
            case 'sniffing':
                $x = $this->getXray();
                $p['sniffing'] = $this->sniffingSettings($p, $x['inbounds'][0]['sniffing'] ?? null);
                $p['sniffing']['enabled'] = empty($p['sniffing']['enabled']);
                $this->setPacConf($p);
                $this->syncSniffingLive($p);
                break;
            case 'sniffingMetadataOnly':
                $x = $this->getXray();
                $p['sniffing'] = $this->sniffingSettings($p, $x['inbounds'][0]['sniffing'] ?? null);
                $p['sniffing']['metadataOnly'] = empty($p['sniffing']['metadataOnly']);
                $this->setPacConf($p);
                $this->syncSniffingLive($p);
                break;
            case 'sniffingRouteOnly':
                $x = $this->getXray();
                $p['sniffing'] = $this->sniffingSettings($p, $x['inbounds'][0]['sniffing'] ?? null);
                $p['sniffing']['routeOnly'] = empty($p['sniffing']['routeOnly']);
                $this->setPacConf($p);
                $this->syncSniffingLive($p);
                break;
            case 'mldsa':
                if ($this->mldsaReady($p)) {
                    $p['reality']['mldsa'] = 0;
                } else {
                    if (!$this->mldsaKeysValid($p)) {
                        $mk = $this->genMldsaKeys();
                        if (empty($mk['seed']) || empty($mk['verify'])) {
                            return $this->answer($this->input['callback_id'], 'mldsa keygen failed (xray too old?)', true);
                        }
                        $p['reality']['mldsa65Seed']   = $mk['seed'];
                        $p['reality']['mldsa65Verify'] = $mk['verify'];
                    }
                    $p['reality']['mldsa'] = 1;
                }
                $this->setPacConf($p);
                $this->syncRealityLive($p);
                break;
        }
        $this->dpiMenu();
    }

    public function dpiSet($field)
    {
        if (in_array($field, ['r_mldsa65Seed', 'r_mldsa65Verify'], true)) {
            return $this->answer($this->input['callback_id'], 'ML-DSA-65 uses autogen only', true);
        }

        $prompt = "@{$this->input['username']} " . $this->i18n('enter value');
        if ($hint = $this->dpiFieldHint($field)) {
            $prompt .= "\n\n" . $hint;
        }

        $r = $this->send(
            $this->input['chat'],
            $prompt,
            $this->input['message_id'],
            reply: $this->i18n('enter value'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'saveDpi',
            'args'           => [$field],
        ]);
    }

    // Готовые значения packet для каждого типа noise. Один источник и для
    // подсказки по тапу (dpiFieldHint('noise_packet')), и для показа прямо в
    // меню — чтобы примеры были видны, а не спрятаны за нажатием.
    public function noiseExamplesHint(): string
    {
        return $this->language === 'ru'
            ? "Готовые значения packet по типам (можно копировать):\n"
                . "• <code>rand</code> — длина в байтах: <code>50</code>, <code>100</code>, <code>10-20</code>, <code>50-150</code>, <code>200-400</code>\n"
                . "• <code>str</code> — текст как есть: <code>hello</code>, <code>ping</code>, <code>keepalive</code>\n"
                . "• <code>hex</code> — чётное число hex-цифр, без пробелов/<code>0x</code>:\n"
                . "   <code>deadbeef</code>, <code>48656c6c6f</code> (=Hello), <code>000102030405</code>, <code>cafebabe</code>\n"
                . "• <code>base64</code> — корректная base64:\n"
                . "   <code>SGVsbG8=</code> (=Hello), <code>dGVzdA==</code> (=test), <code>AAECAwQF</code>,\n"
                . "   <code>7nQBAAABAAAAAAAABnQtcmluZwZtc2VkZ2UDbmV0AAABAAE=</code> (DNS-запрос)\n"
                . "⚠️ Для str/hex/base64 поле обязательно — пустой пакет пропускается."
            : "Ready-to-paste packet values per type (copyable):\n"
                . "• <code>rand</code> — length in bytes: <code>50</code>, <code>100</code>, <code>10-20</code>, <code>50-150</code>, <code>200-400</code>\n"
                . "• <code>str</code> — plain text as-is: <code>hello</code>, <code>ping</code>, <code>keepalive</code>\n"
                . "• <code>hex</code> — even count of hex digits, no spaces/<code>0x</code>:\n"
                . "   <code>deadbeef</code>, <code>48656c6c6f</code> (=Hello), <code>000102030405</code>, <code>cafebabe</code>\n"
                . "• <code>base64</code> — valid base64:\n"
                . "   <code>SGVsbG8=</code> (=Hello), <code>dGVzdA==</code> (=test), <code>AAECAwQF</code>,\n"
                . "   <code>7nQBAAABAAAAAAAABnQtcmluZwZtc2VkZ2UDbmV0AAABAAE=</code> (DNS query)\n"
                . "⚠️ For str/hex/base64 this is required — an empty packet is skipped.";
    }

    public function dpiFieldHint(string $field): string
    {
        $ru = $this->language === 'ru';
        // Индексированные noise-поля (noise0_type…) делят подсказку с базовым
        // noise_type/packet/delay — снимаем индекс перед match.
        $field = preg_replace('~^noise\d+_(type|packet|delay)$~', 'noise_$1', $field);
        return match ($field) {
            'fragment' => $ru
                ? "TCP/TLS-фрагментация: режущий трафик рвётся на куски, чтобы DPI не собрал SNI. "
                    . "Готовые наборы (packets · length · interval · maxSplit):\n"
                    . "• универсальный: <code>tlshello</code> · <code>100-200</code> · <code>10-20</code> · <code>—</code>\n"
                    . "• мягкий: <code>1-3</code> · <code>40-80</code> · <code>1-3</code> · <code>3-5</code>\n"
                    . "• агрессивный (ПК): <code>1-1</code> · <code>1-4</code> · <code>0</code> · <code>10-20</code>"
                : "TCP/TLS fragment: outgoing bytes are sliced so DPI can't reassemble the SNI. "
                    . "Ready sets (packets · length · interval · maxSplit):\n"
                    . "• general: <code>tlshello</code> · <code>100-200</code> · <code>10-20</code> · <code>—</code>\n"
                    . "• gentle: <code>1-3</code> · <code>40-80</code> · <code>1-3</code> · <code>3-5</code>\n"
                    . "• aggressive (PC): <code>1-1</code> · <code>1-4</code> · <code>0</code> · <code>10-20</code>",
            'fragment_packets' => $ru
                ? "Что резать:\n"
                    . "• <code>tlshello</code> — только TLS ClientHello (прячет SNI)\n"
                    . "• <code>1-3</code> — 1..3-ю TCP-запись клиента\n"
                    . "• <code>1-1</code> / <code>1-2</code> — конкретные записи\n"
                    . "Пусто/0/default/off = <code>1-3</code>."
                : "What to slice:\n"
                    . "• <code>tlshello</code> — only the TLS ClientHello (hides SNI)\n"
                    . "• <code>1-3</code> — the client's 1st..3rd TCP write\n"
                    . "• <code>1-1</code> / <code>1-2</code> — specific writes\n"
                    . "Empty/0/default/off = <code>1-3</code>.",
            'fragment_length' => $ru
                ? "Размер кусков в байтах, число или диапазон. Примеры: <code>1-4</code>, <code>10-20</code>, <code>40-80</code>, <code>100-200</code>. "
                    . "⚠️ Для <code>tlshello</code> минимум 6; не ставь 0."
                : "Chunk size in bytes, a number or a range. Examples: <code>1-4</code>, <code>10-20</code>, <code>40-80</code>, <code>100-200</code>. "
                    . "⚠️ For <code>tlshello</code> minimum is 6; do not use 0.",
            'fragment_interval' => $ru
                ? "Задержка между кусками в мс, число или диапазон. Примеры: <code>0</code> (без пауз), <code>1-3</code>, <code>10-20</code>, <code>20-50</code>. "
                    . "<code>0</code>/default = <code>10-20</code>."
                : "Delay between chunks in ms, a number or a range. Examples: <code>0</code> (no pause), <code>1-3</code>, <code>10-20</code>, <code>20-50</code>. "
                    . "<code>0</code>/default = <code>10-20</code>.",
            'fragment_maxSplit' => $ru
                ? "Потолок числа фрагментов: достигнув его, остаток данных досылается одним куском. "
                    . "Полезно с маленьким <code>length</code>, чтобы ClientHello не распался на десятки записей.\n"
                    . "Число или диапазон: <code>2-3</code> (минимум кусков), <code>3-5</code> (сбалансированно), <code>10-20</code> (много мелких).\n"
                    . "Пусто/0/default = без лимита (режет, пока хватает данных)."
                : "Cap on the number of fragments: once reached, the rest is sent as one chunk. "
                    . "Useful with a small <code>length</code> so the ClientHello isn't split into dozens of records.\n"
                    . "A number or range: <code>2-3</code> (fewest chunks), <code>3-5</code> (balanced), <code>10-20</code> (many small).\n"
                    . "Empty/0/default = no cap (slice while data remains).",
            'noise' => $ru
                ? "UDP-шум: несколько пакетов шлются подряд перед реальным трафиком. "
                    . "Поля: type = <code>rand</code>/<code>str</code>/<code>hex</code>/<code>base64</code>; "
                    . "packet — значение для типа; delay — задержка после пакета в мс.\n"
                    . "Пример хорошей последовательности: пакет1 <code>rand</code>·<code>50-150</code>·<code>10-16</code>, "
                    . "пакет2 <code>rand</code>·<code>200-400</code>·<code>20-50</code>."
                : "UDP noise: several packets are sent in sequence before real traffic. "
                    . "Fields: type = <code>rand</code>/<code>str</code>/<code>hex</code>/<code>base64</code>; "
                    . "packet is the value for that type; delay is the wait after the packet in ms.\n"
                    . "A good sequence example: packet1 <code>rand</code>·<code>50-150</code>·<code>10-16</code>, "
                    . "packet2 <code>rand</code>·<code>200-400</code>·<code>20-50</code>.",
            'noise_type' => $ru
                ? "Тип содержимого шумового пакета:\n"
                    . "• <code>rand</code> — случайные байты (packet = длина/диапазон)\n"
                    . "• <code>str</code> — обычный текст как есть (packet = сама строка)\n"
                    . "• <code>hex</code> — байты в hex (packet = hex без пробелов)\n"
                    . "• <code>base64</code> — байты в base64 (packet = base64-строка)\n"
                    . "Обычно достаточно <code>rand</code>."
                : "Noise packet content type:\n"
                    . "• <code>rand</code> — random bytes (packet = length/range)\n"
                    . "• <code>str</code> — plain text as-is (packet = the string)\n"
                    . "• <code>hex</code> — bytes in hex (packet = hex, no spaces)\n"
                    . "• <code>base64</code> — bytes in base64 (packet = base64 string)\n"
                    . "<code>rand</code> is usually enough.",
            'noise_packet' => $this->noiseExamplesHint(),
            'noise_delay' => $ru
                ? "Задержка после этого пакета в миллисекундах, число или диапазон. "
                    . "Примеры: <code>0</code> (без задержки), <code>5</code>, <code>10-16</code>, <code>20-50</code>, <code>100-200</code>."
                : "Delay after this packet in milliseconds, a number or a range. "
                    . "Examples: <code>0</code> (no delay), <code>5</code>, <code>10-16</code>, <code>20-50</code>, <code>100-200</code>.",
            'r_maxTimeDiff' => $ru
                ? "⚠️ Допуск расхождения часов клиент↔сервер в мс. <code>0</code> = проверка выключена (по умолч.). Только целое ≥ 0 — отрицательное значение не даст xray запуститься. Пример: <code>60000</code> (±60 с)."
                : "⚠️ Allowed client↔server clock skew in ms. <code>0</code> = check disabled (default). Integer ≥ 0 only — a negative value stops xray from starting. Example: <code>60000</code> (±60 s).",
            'r_xver' => $ru
                ? "⚠️ Версия PROXY-протокола к dest: <code>0</code>, <code>1</code> или <code>2</code>. <code>0</code> = выкл (по умолч.). Только ≥ 0. Меняй только если знаешь, зачем — иначе ломает Reality."
                : "⚠️ PROXY-protocol version to dest: <code>0</code>, <code>1</code> or <code>2</code>. <code>0</code> = off (default). Integer ≥ 0 only. Change only if you know why — otherwise it breaks Reality.",
            'r_minClientVer', 'r_maxClientVer' => $ru
                ? "Мин./макс. версия xray-клиента, напр. <code>1.8.0</code>. ⚠️ Не-xray клиенты (sing-box/mihomo) могут быть отклонены. Пусто/0/default = без проверки (по умолч.)."
                : "Min/max xray client version, e.g. <code>1.8.0</code>. ⚠️ Non-xray clients (sing-box/mihomo) may be rejected. Empty/0/default = no check (default).",
            default => '',
        };
    }

    // 3x-ui style: "/" + random.Seq(15), i.e. alphanumeric only.
    public function genSpiderX(): string
    {
        $chars = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
        $out = '';
        for ($i = 0; $i < 15; $i++) {
            $out .= $chars[random_int(0, strlen($chars) - 1)];
        }
        return '/' . $out;
    }

    // Добавить пакет UDP-noise. Пишем список в новом формате ['noise']['list'];
    // при первом добавлении мигрируем старый одиночный noise через dpiNoiseList.
    // Клиентская настройка (freedom-outbound в подписке) — рестарт xray не нужен.
    public function dpiNoiseAdd()
    {
        $p = $this->getPacConf();
        $list = $this->dpiNoiseList($p);
        $list[] = ['type' => 'rand', 'packet' => '50-150', 'delay' => '10-16'];
        $p['dpi']['noise']['list'] = array_values($list);
        // Legacy-поля больше не источник истины — убираем, чтобы не дублировать.
        unset($p['dpi']['noise']['type'], $p['dpi']['noise']['packet'], $p['dpi']['noise']['delay']);
        $this->setPacConf($p);
        $this->dpiMenu();
    }

    public function dpiNoiseDel($i)
    {
        $p = $this->getPacConf();
        $list = $this->dpiNoiseList($p);
        if (isset($list[$i])) {
            array_splice($list, $i, 1);
        }
        $p['dpi']['noise']['list'] = array_values($list);
        unset($p['dpi']['noise']['type'], $p['dpi']['noise']['packet'], $p['dpi']['noise']['delay']);
        $this->setPacConf($p);
        $this->dpiMenu();
    }

    // Auto-generate spiderX. Client-side only (link &spx / config), so no restart;
    // new links pick it up.
    public function dpiGenSpiderX()
    {
        $p = $this->getPacConf();
        $p['reality']['spiderX'] = $this->genSpiderX();
        $this->setPacConf($p);
        $this->dpiMenu();
    }

    public function dpiGenMldsa()
    {
        $mk = $this->genMldsaKeys();
        if (empty($mk['seed']) || empty($mk['verify'])) {
            return $this->answer($this->input['callback_id'], 'mldsa keygen failed (xray too old?)', true);
        }

        $p = $this->getPacConf();
        $p['reality']['mldsa']         = 1;
        $p['reality']['mldsa65Seed']   = $mk['seed'];
        $p['reality']['mldsa65Verify'] = $mk['verify'];
        $this->setPacConf($p);
        $this->syncRealityLive($p);
        $this->dpiMenu();
    }

    // Полные mldsa65-ключи отдельным сообщением: в тексте dpiMenu они урезаны
    // (shortSecretLabel), а из <code> копируются тапом целиком.
    public function dpiShowMldsa()
    {
        $p      = $this->getPacConf();
        $seed   = (string) ($p['reality']['mldsa65Seed'] ?? '');
        $verify = (string) ($p['reality']['mldsa65Verify'] ?? '');
        if ($seed === '' && $verify === '') {
            return $this->answer($this->input['callback_id'], 'mldsa65 keys are empty — use autogen', true);
        }
        $t   = [];
        $t[] = 'mldsa65 Seed:';
        $t[] = '<code>' . htmlspecialchars($seed ?: '—', ENT_QUOTES) . '</code>';
        $t[] = 'mldsa65 Verify:';
        $t[] = '<code>' . htmlspecialchars($verify ?: '—', ENT_QUOTES) . '</code>';
        $this->send($this->input['from'], implode("\n", $t));
    }

    public function dpiDefault($field)
    {
        $p = $this->getPacConf();
        $liveReality = false;
        $liveSniffing = false;
        switch ($field) {
            case 'r_spiderX':
                $p['reality']['spiderX'] = '';
                break;
            case 'r_mldsa65':
                $p['reality']['mldsa'] = 0;
                $p['reality']['mldsa65Seed'] = '';
                $p['reality']['mldsa65Verify'] = '';
                $liveReality = true;
                break;
            case 'r_minClientVer':
                $p['reality']['minClientVer'] = '';
                $liveReality = true;
                break;
            case 'r_maxClientVer':
                $p['reality']['maxClientVer'] = '';
                $liveReality = true;
                break;
            case 'sniffing_destOverride':
                $p['sniffing'] = $this->sniffingSettings($p);
                $p['sniffing']['destOverride'] = $this->defaultSniffingSettings()['destOverride'];
                $liveSniffing = true;
                break;
            case 'sniffing_ipsExcluded':
                $p['sniffing'] = $this->sniffingSettings($p);
                $p['sniffing']['ipsExcluded'] = [];
                $liveSniffing = true;
                break;
            case 'sniffing_domainsExcluded':
                $p['sniffing'] = $this->sniffingSettings($p);
                $p['sniffing']['domainsExcluded'] = [];
                $liveSniffing = true;
                break;
        }
        $this->setPacConf($p);
        if ($liveReality) {
            $this->syncRealityLive($p);
        }
        if ($liveSniffing) {
            $this->syncSniffingLive($p);
        }
        $this->dpiMenu();
    }

    public function saveDpi($val, $field)
    {
        $val = trim((string) $val);
        $p   = $this->getPacConf();
        $liveReality = false;
        $liveSniffing = false;
        // Индексированный noise-пакет (noise{i}_type|packet|delay): пишем в список,
        // мигрировав старый одиночный noise. switch ниже — по литеральному $field,
        // поэтому динамический ключ разбираем отдельным if с ранним выходом.
        if (preg_match('~^noise(\d+)_(type|packet|delay)$~', $field, $nm)) {
            $list = $this->dpiNoiseList($p);
            $idx  = (int) $nm[1];
            if (isset($list[$idx])) {
                $list[$idx][$nm[2]] = $this->isDefaultValue($val) ? '' : $val;
                $p['dpi']['noise']['list'] = array_values($list);
                unset($p['dpi']['noise']['type'], $p['dpi']['noise']['packet'], $p['dpi']['noise']['delay']);
                $this->setPacConf($p);
            }
            return $this->dpiMenu();
        }
        switch ($field) {
            case 'fragment_packets':  $p['dpi']['fragment']['packets']  = $this->isDefaultValue($val) ? '' : $val; break;
            case 'fragment_length':   $p['dpi']['fragment']['length']   = $this->isDefaultValue($val) ? '' : $val; break;
            case 'fragment_interval': $p['dpi']['fragment']['interval'] = $this->isDefaultValue($val) ? '' : $val; break;
            // maxSplit опционален: пусто/0/default → снимаем ограничение, чтобы
            // applyDpiFragment не писал поле и поведение осталось дефолтным.
            case 'fragment_maxSplit': $p['dpi']['fragment']['maxSplit'] = $this->isDefaultValue($val) ? '' : $val; break;
            // xray REALITY maxTimeDiff/xver are uint64 — a negative value would make
            // xray fail to parse the config (and not start), so clamp to >= 0.
            case 'r_maxTimeDiff':     $p['reality']['maxTimeDiff']  = max(0, (int) $val); $liveReality = true; break;
            case 'r_xver':            $p['reality']['xver']         = max(0, (int) $val); $liveReality = true; break;
            case 'r_minClientVer':    $p['reality']['minClientVer'] = $this->isDefaultValue($val) ? '' : $val; $liveReality = true; break;
            case 'r_maxClientVer':    $p['reality']['maxClientVer'] = $this->isDefaultValue($val) ? '' : $val; $liveReality = true; break;
            case 'r_spiderX':         $p['reality']['spiderX']      = $this->normalizeSpiderXValue($val); break;
            case 'sniffing_destOverride':
                $p['sniffing'] = $this->sniffingSettings($p);
                $dest = $this->parseSniffingDest($val);
                $p['sniffing']['destOverride'] = $dest ?: $this->defaultSniffingSettings()['destOverride'];
                $liveSniffing = true;
                break;
            case 'sniffing_ipsExcluded':
                $p['sniffing'] = $this->sniffingSettings($p);
                $p['sniffing']['ipsExcluded'] = $this->parseListValue($val);
                $liveSniffing = true;
                break;
            case 'sniffing_domainsExcluded':
                $p['sniffing'] = $this->sniffingSettings($p);
                $p['sniffing']['domainsExcluded'] = $this->parseListValue($val);
                $liveSniffing = true;
                break;
        }
        $this->setPacConf($p);
        if ($liveReality) {
            $this->syncRealityLive($p);
        }
        if ($liveSniffing) {
            $this->syncSniffingLive($p);
        }
        $this->dpiMenu();
    }

    public function switchIpLimit($limit)
    {
        $limit = explode(':', $limit);
        $c = $this->getPacConf();
        if ((int) $limit[0] <= 0) {
            unset($c['ip_limit']);
            unset($c['ip_count']);
        } else {
            $c['ip_limit'] = (int) $limit[0];
            $c['ip_count'] = (int) $limit[1] ?: 1;
        }
        $this->setPacConf($c);
        $this->xray();
    }

    public function hwidLimit()
    {
        $pac     = $this->getPacConf();
        $enabled = !empty($pac['hwid_limit_enabled']);
        $count   = max(1, (int) ($pac['hwid_device_count'] ?: 1));

        $text[] = 'Settings -> ' . $this->i18n('hwid limit');
        $text[] = $this->i18n('hwid notice');
        $text[] = $this->i18n('hwid limit') . ': ' . ($enabled ? $count : $this->i18n('off'));

        $data[] = [
            [
                'text'          => $this->i18n($enabled ? 'on' : 'off'),
                'callback_data' => '/toggleHwidLimit',
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('set hwid devices count') . ': ' . $count,
                'callback_data' => '/setHwidDevices',
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => '/xray',
            ],
        ];

        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text ?: ['...']),
            $data ?: false,
        );
    }

    public function toggleHwidLimit($context = null)
    {
        $pac = $this->getPacConf();
        $pac['hwid_limit_enabled'] = $pac['hwid_limit_enabled'] ? 0 : 1;
        if (!empty($pac['hwid_limit_enabled']) && empty($pac['hwid_device_count'])) {
            $pac['hwid_device_count'] = 1;
        }
        $this->setPacConf($pac);
        $this->answer($this->input['callback_id'], $this->i18n('hwid notice'), true);
        if ($context === 'xray') {
            $this->xray();
        } else {
            $this->hwidLimit();
        }
    }

    public function setHwidDevices($context = null)
    {
        $r = $this->send(
            $this->input['chat'],
            "@{$this->input['username']} enter hwid devices count",
            $this->input['message_id'],
            reply: 'enter hwid devices count',
        );
        $this->stashReply($r, [
            'start_message' => $this->input['message_id'],
            'callback'      => 'saveHwidDevices',
            'args'          => [$context],
        ]);
    }

    public function saveHwidDevices($count, $context = null)
    {
        $count = (int) $count;
        if ($count <= 0) {
            $count = 1;
        }
        $pac = $this->getPacConf();
        $pac['hwid_device_count'] = $count;
        $this->setPacConf($pac);
        $this->send($this->input['chat'], $this->i18n('hwid notice'), $this->input['message_id']);
        if ($context === 'xray') {
            $this->xray();
        } else {
            $this->hwidLimit();
        }
    }

    public function getHwidStorage()
    {
        if (!file_exists($this->hwid)) {
            return [];
        }
        $data = json_decode(file_get_contents($this->hwid), true);
        return is_array($data) ? $data : [];
    }

    public function setHwidStorage(array $storage)
    {
        file_put_contents($this->hwid, json_encode($storage, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
    }

    public function getHwidDevicesByUser($uid)
    {
        $storage = $this->getHwidStorage();
        return $storage[$uid] ?? [];
    }

    public function setHwidDevice($uid, $hwid, array $info)
    {
        $storage = $this->getHwidStorage();
        $storage[$uid][$hwid] = $info;
        $this->setHwidStorage($storage);
    }

    public function deleteHwidDevice($uid, $hwid)
    {
        $storage = $this->getHwidStorage();
        if (isset($storage[$uid][$hwid])) {
            unset($storage[$uid][$hwid]);
            if (empty($storage[$uid])) {
                unset($storage[$uid]);
            }
            $this->setHwidStorage($storage);
        }
    }

    public function deleteHwidUser($uid)
    {
        $storage = $this->getHwidStorage();
        if (isset($storage[$uid])) {
            unset($storage[$uid]);
            $this->setHwidStorage($storage);
        }
    }

    protected function getHwidTokenScope($index)
    {
        return ($this->input['chat'] ?? 'global') . ':' . $index;
    }

    protected function rememberHwidToken($scope, $hwid)
    {
        // Токен резолвится СЛЕДУЮЩИМ запросом (кнопка удаления) — запись
        // обязана пережить текущий: сессия закрыта с диспатча, пишем через
        // sessionApply.
        $token = '';
        $this->sessionApply(function () use ($scope, $hwid, &$token) {
            if (!isset($_SESSION['hwidTokens'])) {
                $_SESSION['hwidTokens'] = [];
            }
            if (!isset($_SESSION['hwidTokens'][$scope])) {
                $_SESSION['hwidTokens'][$scope] = [];
            }
            do {
                try {
                    $token = bin2hex(random_bytes(5));
                } catch (\Throwable $e) {
                    $token = substr(hash('sha256', $hwid . microtime(true)), 0, 10);
                }
            } while (isset($_SESSION['hwidTokens'][$scope][$token]));

            $_SESSION['hwidTokens'][$scope][$token] = $hwid;
        });

        return $token;
    }

    protected function resolveHwidToken($scope, $token)
    {
        if (isset($_SESSION['hwidTokens'][$scope][$token])) {
            $hwid = $_SESSION['hwidTokens'][$scope][$token];
            // Одноразовость токена должна пережить запрос — unset через хелпер.
            $this->sessionApply(function () use ($scope, $token) {
                unset($_SESSION['hwidTokens'][$scope][$token]);
            });
            return $hwid;
        }

        $decoded = base64_decode($token, true);

        return $decoded !== false ? $decoded : '';
    }

    public function processHwidRequest(array $client)
    {
        $pac = $this->getPacConf();
        // Informational HWID headers (Remnawave/Hiddify convention): let clients
        // display device-limit status instead of just getting a 429.
        if (empty($pac['hwid_limit_enabled']) || !empty($client['hwid_disabled'])) {
            header('x-hwid-active: false');
            header('x-hwid-not-supported: false');
            header('x-hwid-max-devices-reached: false');
            header('x-hwid-limit: false');
            return true;
        }

        $limit = (int) ($client['hwid_limit'] ?: ($pac['hwid_device_count'] ?: 0));
        if ($limit <= 0) {
            header('x-hwid-active: true');
            header('x-hwid-not-supported: false');
            header('x-hwid-max-devices-reached: false');
            header('x-hwid-limit: false');
            return true;
        }

        $devices   = $this->getHwidDevicesByUser($client['id']);
        $hwid      = trim($_SERVER['HTTP_X_HWID'] ?? '');
        $isBrowser = $this->isBrowserRequest();

        $hwidNotSupported = !$isBrowser && $hwid === '';
        $hwidMaxReached   = count($devices) >= $limit;
        header('x-hwid-active: true');
        header('x-hwid-not-supported: ' . ($hwidNotSupported ? 'true' : 'false'));
        header('x-hwid-max-devices-reached: ' . ($hwidMaxReached ? 'true' : 'false'));
        header('x-hwid-limit: ' . ($hwidMaxReached ? 'true' : 'false'));

        if ($hwid === '') {
            if ($isBrowser) {
                return true;
            }

            $message = 'HWID device limit exceeded';
            header('announce: base64:' . base64_encode($message));
            header('X-HWID-Status: ' . $message);
            header('HTTP/1.1 429 Too Many Requests', true, 429);

            return false;
        }

        $isNew = !isset($devices[$hwid]);

        if ($isNew && count($devices) >= $limit) {
            $message = 'HWID device limit exceeded';
            header('announce: base64:' . base64_encode($message));
            header('X-HWID-Status: ' . $message);
            header('HTTP/1.1 429 Too Many Requests', true, 429);
            return false;
        }

        $this->setHwidDevice($client['id'], $hwid, [
            'time'         => time(),
            'user_agent'   => $_SERVER['HTTP_USER_AGENT'] ?? '',
            'device_os'    => $_SERVER['HTTP_X_DEVICE_OS'] ?? '',
            'os_version'   => $_SERVER['HTTP_X_VER_OS'] ?? '',
            'device_model' => $_SERVER['HTTP_X_DEVICE_MODEL'] ?? '',
        ]);

        return true;
    }

    protected function isBrowserRequest()
    {
        $userAgent = $_SERVER['HTTP_USER_AGENT'] ?? '';
        $accept    = $_SERVER['HTTP_ACCEPT'] ?? '';

        if ($userAgent === '' && $accept === '') {
            return false;
        }

        $browserPatterns = [
            'Mozilla/',
            'Chrome/',
            'Safari/',
            'Firefox/',
            'Edge/',
            'Edg/',
            'MSIE ',
            'Trident/',
            'Opera/',
            'OPR/',
        ];

        foreach ($browserPatterns as $pattern) {
            if (stripos($userAgent, $pattern) !== false) {
                return true;
            }
        }

        if (stripos($accept, 'text/html') !== false) {
            return true;
        }

        return false;
    }

