    public function ocUser($i)
    {
        $clients = $this->getClientsOc();
        if (!isset($clients[$i])) {
            $this->menu('oc');
            return;
        }

        $users  = $this->syncOcUsers($clients);
        $ocserv = file_get_contents('/config/ocserv.conf');
        $cs     = $this->ocCamouflageSecretForConf($ocserv);
        $url    = htmlspecialchars($this->ocConnectionUrl($cs), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $user   = htmlspecialchars($clients[$i], ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $pass   = htmlspecialchars($users[$clients[$i]] ?? '', ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $online = !empty($this->getOcOnlineUsers([$clients[$i]])[$clients[$i]]);

        $text[] = "Menu -> OpenConnect -> $user";
        $text[] = $this->i18n('server') . ": <code>$url</code>";
        $text[] = $this->i18n('username') . ": <code>$user</code>";
        $text[] = $this->i18n('password') . ": <span class='tg-spoiler'>$pass</span>";
        $text[] = $this->i18n('status') . ': ' . ($online ? '🟢 ' . $this->i18n('online') : '🔴 ' . $this->i18n('offline'));
        $text[] = $this->i18n('camouflage') . ': ' . $this->i18n($cs === '' ? 'off' : 'on');

        $data[] = [
            [
                'text'          => $this->i18n('change password'),
                'callback_data' => "/changeOcPass $i",
            ],
            [
                'text'          => $this->i18n('generate password'),
                'callback_data' => "/genOcPass $i",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('delete'),
                'callback_data' => "/deloc $i",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu oc",
            ],
        ];

        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text),
            $data,
        );
    }

    public function changeOcExpose()
    {
        $c = file_get_contents('/config/ocserv.conf');
        preg_match('~^expose-iroutes = ([^\n]+)~sm', $c, $m);
        $t = preg_replace('~^expose-iroutes[^\n]+~sm', "expose-iroutes = " . ($m[1] == 'true' ? 'false' : 'true'), $c);
        $this->restartOcserv($t);
        $this->menu('oc');
    }

    public function deloc($i)
    {
        $clients = $this->getClientsOc();
        foreach ($clients as $k => $v) {
            if ($i == $k) {
                $this->ssh("ocpasswd -c /etc/ocserv/ocserv.passwd -d " . escapeshellarg($v), 'oc');
                $users = $this->syncOcUsers($clients);
                unset($users[$v]);
                $this->persistOcUsers($users);
                break;
            }
        }
        $this->menu('oc');
    }

    public function delxr($i)
    {
        $r  = $this->getXray();
        $st = $this->getXrayStats();
        foreach ($r['inbounds'][0]['settings']['clients'] as $k => $v) {
            if ($i == $k) {
                $this->deleteHwidUser($r['inbounds'][0]['settings']['clients'][$k]['id']);
                unset($r['inbounds'][0]['settings']['clients'][$k]);
                unset($st['users'][$k]);
                $this->setXrayStats($st);
                $this->restartXray($r);
                $this->adguardXrayClients();
                break;
            }
        }
        $this->xray();
    }

    public function getClientsOc()
    {
        $users = array_filter(explode("\n", file_get_contents('/config/ocserv.passwd')), fn ($e) => !empty($e));
        return array_map(fn($e) => explode(':', $e)[0], $users);
    }

    public function addocus($user)
    {
        $user = $this->normalizeOcUsername($user);
        if ($user === false) {
            $this->send($this->input['chat'], 'OpenConnect username: use 1-64 chars: A-Z a-z 0-9 . _ -');
            $this->menu('oc');
            return;
        }

        $clients = $this->getClientsOc();
        if (in_array($user, $clients, true)) {
            $this->ocUser(array_search($user, $clients, true));
            return;
        }

        $this->setOcUserPassword($user, $this->genOcPassword());
        $clients = $this->getClientsOc();
        $i = array_search($user, $clients, true);
        if ($i === false) {
            $this->menu('oc');
            return;
        }

        $this->ocUser($i);
    }

    public function addxrus($users)
    {
        $c     = $this->getXray();
        $p     = $this->getPacConf();
        $users = array_map(fn ($e) => trim($e), explode(',', $users));
        $users = array_map(fn ($e) => explode(':', $e), $users);
        foreach ($c['inbounds'][0]['settings']['clients'] as $k => $v) {
            $uuids[]  = $v['id'];
            $emails[] = $v['email'];
        }
        foreach ($users as $user) {
            $uuid = $user[1] ?: trim($this->ssh('xray uuid', 'xr'));
            if (in_array($uuid, $uuids ?: []) || in_array($user[0], $emails ?: [])) {
                $this->send($this->input['chat'], "user {$user[0]} already exists");
                return $this->xray();
            }
            // subtoken addresses the subscription independently of the id (which
            // is the VLESS credential), so a leaked/shared sub URL never exposes
            // the credential and can be rotated without regenerating the id.
            $stok = bin2hex(random_bytes(16));
            $c['inbounds'][0]['settings']['clients'][] = match($p['transport']) {
                'Reality'     => ['id' => $uuid, 'flow' => 'xtls-rprx-vision', 'email' => $user[0], 'subtoken' => $stok],
                'trojan-grpc' => ['id' => $uuid, 'password' => bin2hex(random_bytes(16)), 'email' => $user[0], 'subtoken' => $stok],
                default       => ['id' => $uuid, 'email' => $user[0], 'subtoken' => $stok],
            };
        }
        $this->restartXray($c);
        $this->adguardXrayClients();
        if (count($users) == 1) {
            $this->userXr(count($c['inbounds'][0]['settings']['clients']) - 1);
        } else {
            $this->xray();
        }
    }

    public function setTimerXr($time, $i)
    {
        $c = $this->getXray();
        if (empty($time)) {
            unset($c['inbounds'][0]['settings']['clients'][$i]['time']);
        } else {
            $time = strtotime($time);
            if ($time === false) {
                $this->send($this->input['chat'], 'wrong format');
                return;
            }
            $c['inbounds'][0]['settings']['clients'][$i]['time'] = $time;
        }
        $this->restartXray($c, 1);
        if (!empty($c['inbounds'][0]['settings']['clients'][$i]['off'])) {
            $this->switchXr($i, 0, 1);
        } else {
            $this->userXr($i);
        }
    }

    public function switchXr($i, $nm = 0, $time = false)
    {
        $c = $this->getXray();
        if (empty($time)) {
            unset($c['inbounds'][0]['settings']['clients'][$i]['time']);
        }
        if (empty($c['inbounds'][0]['settings']['clients'][$i]['off'])) {
            $c['inbounds'][0]['settings']['clients'][$i]['off'] = $c['inbounds'][0]['settings']['clients'][$i]['id'];
            $c['inbounds'][0]['settings']['clients'][$i]['id']  = trim($this->ssh('xray uuid', 'xr'));
            if (isset($c['inbounds'][0]['settings']['clients'][$i]['password'])) {
                $c['inbounds'][0]['settings']['clients'][$i]['off_pwd']  = $c['inbounds'][0]['settings']['clients'][$i]['password'];
                $c['inbounds'][0]['settings']['clients'][$i]['password'] = trim($this->ssh('xray uuid', 'xr'));
            }
        } else {
            $c['inbounds'][0]['settings']['clients'][$i]['id'] = $c['inbounds'][0]['settings']['clients'][$i]['off'];
            if (isset($c['inbounds'][0]['settings']['clients'][$i]['password'])) {
                $c['inbounds'][0]['settings']['clients'][$i]['password'] = $c['inbounds'][0]['settings']['clients'][$i]['off_pwd']
                    ?: $c['inbounds'][0]['settings']['clients'][$i]['off'];
                unset($c['inbounds'][0]['settings']['clients'][$i]['off_pwd']);
            }
            unset($c['inbounds'][0]['settings']['clients'][$i]['off']);
        }
        // A manual enable/disable overrides any traffic-quota ban: drop the marker
        // so a later stats reset (reenableTrafficClients) can't silently flip this
        // client back, and userXr doesn't show a stale ⛔ on an enabled client.
        unset($c['inbounds'][0]['settings']['clients'][$i]['traffic_off']);
        $this->restartXray($c);
        if (empty($nm)) {
            $this->userXr($i);
        }
    }

    public function changeXrPwd($i)
    {
        $r = $this->send(
            $this->input['chat'],
            "@{$this->input['username']} enter password (or leave empty to auto-generate)",
