        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'setXrPwd',
            'args'           => [$i],
        ]);
    }

    public function setXrPwd($pwd, $i)
    {
        $c        = $this->getXray();
        $password = trim($pwd) ?: bin2hex(random_bytes(16));
        $c['inbounds'][0]['settings']['clients'][$i]['password'] = $password;
        $this->restartXray($c);
        $this->userXr($i);
    }

    // Generate a fresh Reality keypair (matched private/public) + shortId.
    // Same commands/parsing as the initial setup in changeTransport(); the pair
    // comes from a single `xray x25519` call so private and public always match.
    public function genRealityKeys(): array
    {
        $shortId = trim($this->ssh('openssl rand -hex 8', 'xr'));
        $keys    = $this->ssh('xray x25519', 'xr');
        preg_match('~^PrivateKey:\s([^\s]+)~m', $keys, $m);
        $private = trim($m[1] ?? '');
        preg_match('~^Password(?:\s*\(PublicKey\))?:\s([^\s]+)~m', $keys, $m);
        $public  = trim($m[1] ?? '');
        return ['private' => $private, 'public' => $public, 'shortId' => $shortId];
    }

    // Generate a post-quantum ML-DSA-65 keypair for Reality (item 2). `xray
    // mldsa65` prints two lines: `Seed: ...` (server, realitySettings.mldsa65Seed)
    // and `Verify: ...` (client link param `pqv` / config mldsa65Verify).
    public function genMldsaKeys(): array
    {
        $keys = $this->ssh('xray mldsa65', 'xr');
        preg_match('~^Seed:\s*([^\s]+)~mi', $keys, $m);
        $seed = trim($m[1] ?? '');
        preg_match('~^Verify:\s*([^\s]+)~mi', $keys, $m);
        $verify = trim($m[1] ?? '');
        if (!$this->isRawUrlBase64DecodedLength($seed, 32) || !$this->isRawUrlBase64DecodedLength($verify, 1952)) {
            return ['seed' => '', 'verify' => ''];
        }
        return ['seed' => $seed, 'verify' => $verify];
    }

    // Apply the configurable Reality server-side extras to a realitySettings block:
    // item 4 hardening params (maxTimeDiff/minClientVer/maxClientVer/xver, default
    // to current values so nothing changes until tuned) and item 2 mldsa65Seed
    // (added only when mldsa is enabled and a seed exists, unset otherwise).
    // Centralized so changeTransport()/regenRealityXr()/regenAllXr() stay in sync.
    public function applyRealityServerExtras(array &$rs, array $p): void
    {
        $rs['maxTimeDiff']  = max(0, (int) ($p['reality']['maxTimeDiff'] ?? 0));
        // Since Xray-core v26.7.11 (PR #6181) an empty "minClientVer" no longer means
        // "no restriction": the server now defaults it to 26.3.27, which rejects the
        // many clients built on older cores. Emit "0.0.0" when the user set nothing so
        // the pre-v26.7.11 "accept any client" behaviour is preserved; a real value
        // typed via the hardening menu is still honoured verbatim.
        $rs['minClientVer'] = ((string) ($p['reality']['minClientVer'] ?? '')) ?: '0.0.0';
        $rs['maxClientVer'] = (string) ($p['reality']['maxClientVer'] ?? '');
        $rs['xver']         = max(0, (int) ($p['reality']['xver'] ?? 0));
        if ($this->mldsaReady($p)) {
            $rs['mldsa65Seed'] = $p['reality']['mldsa65Seed'];
        } else {
            unset($rs['mldsa65Seed']);
        }
    }

    // Rotate the shared Reality parameters: pbk (keypair) + sid (shortId).
    // Updates pac.json (pbk/privateKey/shortId) and xray.json in lock-step so the
    // server private key matches the public key embedded in every client link.
    // Invalidates all existing links — every client must re-import.
    public function regenRealityXr()
    {
        $x = $this->getXray();
        $p = $this->getPacConf();
        if (empty($x['inbounds'][0]['streamSettings']['realitySettings'])) {
            return $this->answer($this->input['callback_id'], 'reality only', true);
        }
        $k = $this->genRealityKeys();
        if (empty($k['private']) || empty($k['public']) || empty($k['shortId'])) {
            return $this->answer($this->input['callback_id'], 'keygen failed', true);
        }
        $p['xray']                  = $k['public'];
        $p['reality']['privateKey'] = $k['private'];
        $p['reality']['shortId']    = $k['shortId'];
        $x['inbounds'][0]['streamSettings']['realitySettings']['privateKey'] = $k['private'];
        $x['inbounds'][0]['streamSettings']['realitySettings']['shortIds']   = [$k['shortId']];
        if (!empty($p['reality']['mldsa'])) {
            $mk = $this->genMldsaKeys();
            if (!empty($mk['seed']) && !empty($mk['verify'])) {
                $p['reality']['mldsa65Seed']   = $mk['seed'];
                $p['reality']['mldsa65Verify'] = $mk['verify'];
            }
        }
        // Refresh spiderX alongside the keys (only if already in use), so a rotation
        // gives a fresh crawl path too. Client-side, no live effect.
        if (!empty($p['reality']['spiderX'])) {
            $p['reality']['spiderX'] = $this->genSpiderX();
        }
        $this->applyRealityServerExtras($x['inbounds'][0]['streamSettings']['realitySettings'], $p);
        $this->setPacConf($p);
        $this->restartXray($x);
        $this->xray();
    }

    // Rotate a single client's UUID (clientID). For an enabled client this is the
    // live credential; for a disabled one the real id lives in 'off' (the active
    // 'id' is a throwaway), so rotate 'off' too. Invalidates only this client.
    public function regenIdXr($i)
    {
        $x = $this->getXray();
        if (!isset($x['inbounds'][0]['settings']['clients'][$i])) {
            return $this->xray();
        }
        if (!empty($x['inbounds'][0]['settings']['clients'][$i]['off'])) {
            $x['inbounds'][0]['settings']['clients'][$i]['off'] = $this->guidv4();
        }
        $x['inbounds'][0]['settings']['clients'][$i]['id'] = $this->guidv4();
        $this->restartXray($x);
        $this->userXr($i);
    }

    // Full rotation: shared Reality pbk+sid (if Reality) AND every client's UUID.
    // One restart, all configs written consistently. Invalidates every link.
    public function regenAllXr()
    {
        $x = $this->getXray();
        $p = $this->getPacConf();
        if (!empty($x['inbounds'][0]['streamSettings']['realitySettings'])) {
            $k = $this->genRealityKeys();
            if (empty($k['private']) || empty($k['public']) || empty($k['shortId'])) {
                return $this->answer($this->input['callback_id'], 'keygen failed', true);
            }
            $p['xray']                  = $k['public'];
            $p['reality']['privateKey'] = $k['private'];
            $p['reality']['shortId']    = $k['shortId'];
            $x['inbounds'][0]['streamSettings']['realitySettings']['privateKey'] = $k['private'];
            $x['inbounds'][0]['streamSettings']['realitySettings']['shortIds']   = [$k['shortId']];
            if (!empty($p['reality']['mldsa'])) {
                $mk = $this->genMldsaKeys();
                if (!empty($mk['seed']) && !empty($mk['verify'])) {
                    $p['reality']['mldsa65Seed']   = $mk['seed'];
                    $p['reality']['mldsa65Verify'] = $mk['verify'];
                }
            }
            if (!empty($p['reality']['spiderX'])) {
                $p['reality']['spiderX'] = $this->genSpiderX();
            }
            $this->applyRealityServerExtras($x['inbounds'][0]['streamSettings']['realitySettings'], $p);
        }
        foreach ($x['inbounds'][0]['settings']['clients'] as $key => $v) {
            if (!empty($v['off'])) {
                $x['inbounds'][0]['settings']['clients'][$key]['off'] = $this->guidv4();
            }
            $x['inbounds'][0]['settings']['clients'][$key]['id'] = $this->guidv4();
        }
        $this->setPacConf($p);
        $this->restartXray($x);
        $this->xray();
    }

    public function renXrUs($name, $i)
    {
        $c = $this->getXray();
        $c['inbounds'][0]['settings']['clients'][$i]['email'] = $name;
        $this->restartXray($c);
        $this->adguardXrayClients();
        $this->userXr($i);
    }

    public function getXrayStats()
    {
        return json_decode(file_get_contents('/config/xray.stats'), true) ?: [];
    }

    public function setXrayStats($x)
    {
        file_put_contents('/config/xray.stats', json_encode($x));
    }

    public function resetXrUser($i)
    {
        $c = $this->getXrayStats();
        unset($c['users'][$i]);
        // Persist the zeroed usage before restartXray (its collectSession()
        // re-reads the stats file, so an unsaved unset would be discarded).
        $this->setXrayStats($c);
        // Zeroing this user's usage starts a new quota period — lift its ban.
        $this->restartXray($this->reenableTrafficClients($this->getXray(), $i));
        $this->userXr($i);
    }

    public function resetXrStats($nomenu = false)
    {
        // Zeroing usage starts a new quota period, so lift any traffic-quota bans.
        $this->restartXray($this->reenableTrafficClients($this->getXray()));
        $this->setXrayStats([]);
        if (empty($nomenu)) {
            $this->xray();
        }
    }

    public function listXr($i)
    {
        $c = $this->getPacConf();
        $c['xtlslist'] = $i;
        $this->setPacConf($c);
        $this->xray();
    }

