    public function addWarpPlus($key)
    {
        $c    = $this->getPacConf();
        $chat = $this->input['chat'];
        $log  = '';

        $step = function($label, $cmd, $container) use ($chat, &$log) {
            $log .= "$label...";
            $this->sendDraft($chat, 1, $log);
            $out = trim($this->ssh($cmd, $container));
            $log .= $out ? "\n$out\n" : " ok\n";
            $this->sendDraft($chat, 1, $log);
            return empty($out); // true = success (no output = exit 0)
        };

        if (!$step('stopping warp', 'wg-quick down /etc/warp/wgcf-profile.conf 2>/dev/null || true', 'wp')) {
            $this->send($chat, $log);
            return;
        }

        // Удаляем старые профиль и аккаунт
        if (!$step('removing old profile', 'rm -f /etc/warp/wgcf-profile.conf /etc/warp/wgcf-account.toml', 'wp')) {
            $this->send($chat, $log);
            return;
        }

        // Регистрируем новый аккаунт. wgcf >= 2.2.31 печатает таблицу аккаунта
        // в stdout, а $step трактует ЛЮБОЙ stdout как провал (флоу обрывался
        // сразу после register, уже удалив старый аккаунт) — stdout глушим,
        // stderr показываем только при ненулевом коде выхода.
        if (!$step('[warp] Registering WARP account...', 'cd /etc/warp && err=$(wgcf register --accept-tos 2>&1 >/dev/null) || printf "%s\n" "${err:-register failed}"', 'wp')) {
            $this->send($chat, $log);
            return;
        }

        if (!empty($key)) {
            $key = trim($key);
            // WARP keys are alphanumeric + dashes only; reject anything else so the
            // value can't break out of the sed/shell command below (it is interpolated raw).
            if (!preg_match('~^[A-Za-z0-9-]+$~', $key)) {
                $this->send($chat, $log . "invalid license key format\n");
                return;
            }
            $c['warp'] = $key;
            // Заменяем ключ в wgcf-account.toml
            if (!$step('setting license key', "sed -i 's/^license_key.*/license_key = \"$key\"/' /etc/warp/wgcf-account.toml", 'wp')) {
                $this->send($chat, $log);
                return;
            }
            // Обновляем аккаунт с ключом (stdout глушим — как у register)
            if (!$step('applying license key', 'cd /etc/warp && err=$(wgcf update 2>&1 >/dev/null) || printf "%s\n" "${err:-update failed}"', 'wp')) {
                $this->send($chat, $log);
                return;
            }
        } else {
            unset($c['warp']);
        }
        $this->setPacConf($c);

        if (!$step('generating profile', 'cd /etc/warp && err=$(wgcf generate 2>&1 >/dev/null) || printf "%s\n" "${err:-generate failed}"', 'wp')) {
            $this->send($chat, $log);
            return;
        }
        // Фиксапы профиля — общий с start_wp.sh скрипт (warp_fixup.sh), а не
        // локальные sed'ы: раньше они разошлись — тут не вырезался DNS (wg-quick
        // падал на resolvconf с alpine edge), а delete-sed'ы сносили
        // однострочные Address/AllowedIPs новых wgcf (>= 2.2.31) целиком,
        // вместе с v4-частью.
        if (!$step('fixing up profile', 'sh /warp_fixup.sh', 'wp')) {
            $this->send($chat, $log);
            return;
        }

        // Без bash-измов: root-шелл в контейнере — busybox ash, ${PIPESTATUS[0]}
        // там «bad substitution», команда падала, даже не дойдя до wg-quick up.
        $started = $step('starting warp', 'out=$(wg-quick up /etc/warp/wgcf-profile.conf 2>&1); ec=$?; [ "$ec" -ne 0 ] && printf "%s\n" "$out" | grep -v "skip sysctl"; exit $ec', 'wp');

        if (!$started) {
            $this->send($chat, $log);
            return;
        }

        sleep(1);
        // sendMessageDraft closes only when sendMessage is called — send a dummy and delete it
        $r = $this->send($chat, '.');
        if (!empty($r['result']['message_id'])) {
            $this->delete($chat, $r['result']['message_id']);
        }

        $this->warp();
    }

    public function warpStatus()
    {
        $st = $this->ssh('curl -m 1 -x socks5://wp:1080 https://cloudflare.com/cdn-cgi/trace', 'xr');
        preg_match('~warp=(\w+)~', $st, $m);
        return trim($m[1]) ?: 'off';
    }

    public function analyzeXray()
    {
        // iplimit.php запущен в фоне (`php iplimit.php &`): если этот while(true)
        // упадёт с Throwable, процесс тихо умрёт и IP-limit защита отключится
        // навсегда без следов до перезапуска контейнера. Поэтому и внешний
        // (setup: fopen/fseek), и внутренний (per-line обработка) циклы изолируем
        // try/catch — транзиентная ошибка не должна ронять демон.
        while (true) {
            try {
                if (!empty($this->getPacConf()['ip_limit'])) {
                    $this->pool = [];
                    $log = '/logs/xray';
                    $r   = fopen($log, 'r');
                    if ($r === false) {
                        sleep(10);
                        continue;
                    }
                    fseek($r, 0, SEEK_END);
                    while (true) {
                        $pac = $this->getPacConf();
                        if (empty($pac['ip_limit'])) {
                            break;
                        }
                        try {
                            $currentPosition = ftell($r);
                            clearstatcache();
                            $fileSize = filesize($log);
                            if ($fileSize > $currentPosition) {
                                fseek($r, $currentPosition); // сброс флага feof
                                while (!feof($r)) {
                                    $line = fgets($r);
                                    if ($line !== false) {
                                        $this->frequencyAnalyze($line, $pac);
                                    }
                                }
                            }
                        } catch (\Throwable $e) {
                            error_log('analyzeXray: ' . $e->getMessage());
                        }
                        sleep(1);
                    }
                    fclose($r);
                }
            } catch (\Throwable $e) {
                error_log('analyzeXray(setup): ' . $e->getMessage());
            }
            sleep(10);
        }
    }

    public function frequencyAnalyze($line, $pac)
    {
        if (!empty($this->pool)) {
            foreach ($this->pool as $i => $j) {
                if (!empty($j['ips'])) {
                    foreach ($j['ips'] as $k => $v) {
                        if ($v + $pac['ip_limit'] < time()) {
                            unset($this->pool[$i]['ips'][$k]);
                        }
                    }
                }
            }
        }
        if (empty(preg_match('~(?<date>.+)\sfrom\s(?<ip>\d+\.\d+\.\d+\.\d+)(?=.+email:\s(?<email>.+))~', $line, $m))) {
            return;
        }
        if (!empty($m['ip']) && !empty($m['email'])) {
            $ip = ip2long($m['ip']);
            if (!empty($this->pool[$m['email']]['ip']) && $this->pool[$m['email']]['ip'] != $ip) {
                $this->pool[$m['email']]['ips'][$ip] = time();
            }
            if (!empty($this->pool[$m['email']]['ips']) && count($this->pool[$m['email']]['ips']) > ($pac['ip_count'] ?: 1)) {
                $xr = $this->getXray();
                foreach ($xr['inbounds'][0]['settings']['clients'] as $k => $v) {
                    if (empty($v['off']) && $v['email'] == $m['email']) {
                        require __DIR__ . '/config.php';
                        foreach ($c['admin'] as $admin) {
                            $this->send($admin, "vless: {$m['email']} limit ip " . count($this->pool[$m['email']]['ips']) . ' > ' . ($pac['ip_count'] ?: 1), button: [[
                                [
                                    'text'          => $this->i18n(!empty($v['off']) ? 'off' : 'on'),
                                    'callback_data' => "/switchXr $k",
                                ],
                            ]]);
                        }
                        unset($this->pool[$m['email']]);
                        break;
                    }
                }
            }
            $this->pool[$m['email']]['ip'] = $ip;
        }
    }

    public function offWarp()
    {
        $p    = $this->getPacConf();
        if (!empty($this->selfupdate)) {
            if (!empty($p['warpoff'])) {
                $this->ssh('warp-cli --accept-tos registration delete 2>&1', 'wp');
                $this->ssh('pkill warp-svc', 'wp');
            }
        } elseif (!empty($p['warpoff'])) {
            $this->ssh('warp-svc > /dev/null 2>&1 &', 'wp');
            sleep(3);
            if (empty($this->ssh('[ -f "/var/lib/cloudflare-warp/conf.json" ] && echo 1', 'wp'))) {
                $this->send($this->input['chat'], 'Registration: ' . $this->ssh('warp-cli --accept-tos registration new 2>&1', 'wp'));
                if (!empty($p['warp'])) {
                    $this->send($this->input['chat'], 'License: ' . $this->ssh("warp-cli --accept-tos registration license {$p['warp']} 2>&1", 'wp'));
                }
            }
            $this->send($this->input['chat'], 'Proxy mode: ' . $this->ssh('warp-cli --accept-tos mode proxy 2>&1', 'wp'));
            $this->send($this->input['chat'], 'Connect: ' . $this->ssh('warp-cli --accept-tos connect 2>&1', 'wp'));
            unset($p['warpoff']);
        } else {
            $this->send($this->input['chat'], 'Registration delete: ' . $this->ssh('warp-cli --accept-tos registration delete 2>&1', 'wp'));
            $this->ssh('pkill warp-svc', 'wp');
            $p['warpoff'] = 1;
        }
        $this->setPacConf($p);
        if (empty($this->selfupdate)) {
            $this->warp();
        }
    }

    public function warp()
    {
        $p      = $this->getPacConf();
        $c      = file_get_contents('/etc/warp/wgcf-profile.conf');
        $a      = file_get_contents('/etc/warp/wgcf-account.toml');
        $text[] = "Menu -> " . $this->i18n('warp');
        if ($ver = $this->warpVersion()) {
            $text[] = $ver;
        }
        // wgcf печатает trace в stdout, а лог-строки ("Using config file") в
        // stderr — ssh() читает только stdout, поэтому трейс чистый. Если WARP
        // не поднят, trace пуст: показываем явный "off", чтобы строка статуса
        // не выглядела пустой/сломанной.
        $trace  = trim((string) $this->ssh('wgcf trace', 'wp'));
        $text[] = "status: " . ($trace !== '' ? "<pre>$trace</pre>" : '<code>off</code>');
        $text[] = "key: <code>{$p['warp']}</code>";
        $text[] = "<pre>$a</pre>";
        $text[] = "<pre>$c</pre>";
        $data[] = [
            [
                'text'          => $this->i18n('set key'),
                'callback_data' => "/warpPlus",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu",
            ],
        ];
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text ?: ['...']),
            $data ?: false,
        );
    }

    public function choiceTemplate($arg)
    {
        $arg = explode('_', $arg);
        $c   = $this->getXray();
        if (!empty($arg[2])) {
            $c['inbounds'][0]['settings']['clients'][$arg[1]]["{$arg[0]}template"] = $arg[2];
        } else {
            unset($c['inbounds'][0]['settings']['clients'][$arg[1]]["{$arg[0]}template"]);
        }
        $this->saveXray($c);
        $this->userXr($arg[1]);
    }

