        ]);
    }

    public function saveTrafficXr($gb, $i)
    {
        $x  = $this->getXray();
        if (!isset($x['inbounds'][0]['settings']['clients'][$i])) {
            $this->xray();
            return;
        }
        // Accept a decimal number of GiB (matches getBytes display); 0/empty clears.
        $gb = (float) str_replace(',', '.', trim((string) $gb));
        $needsRestart = false;
        if ($gb > 0) {
            $limit = (int) round($gb * 1024 ** 3);
            $x['inbounds'][0]['settings']['clients'][$i]['traffic'] = $limit;
            // Raising the limit above current usage lifts this client's quota ban.
            if (!empty($x['inbounds'][0]['settings']['clients'][$i]['traffic_off'])
                && $this->xrUserTraffic($this->getXrayStats(), $i) < $limit) {
                $x = $this->reenableTrafficClients($x, $i);
                $needsRestart = true;
            }
        } else {
            unset($x['inbounds'][0]['settings']['clients'][$i]['traffic']);
            // Clearing the limit also lifts a prior quota ban; restoring the id
            // needs a live restart for xray to accept connections again.
            if (!empty($x['inbounds'][0]['settings']['clients'][$i]['traffic_off'])) {
                $x = $this->reenableTrafficClients($x, $i);
                $needsRestart = true;
            }
        }
        // Persist via restartXray so the stats:{} object is normalized (raw
        // json_encode turns {} into [] and xray rejects it). norestart unless we
        // re-enabled a client — the limit value itself is bot-side only.
        $this->restartXray($x, !$needsRestart);
        $this->userXr($i);
    }

    public function hwidUserDel($i, $page, $hwid)
    {
        $xray = $this->getXray();
        $uid    = $xray['inbounds'][0]['settings']['clients'][$i]['id'];
        $scope  = $this->getHwidTokenScope($i);
        $decoded = $this->resolveHwidToken($scope, $hwid);
        if ($decoded !== '') {
            $this->deleteHwidDevice($uid, $decoded);
        }
        $this->hwidUser($i, $page);
    }

    public function getDomain($cdn = false)
    {
        $c = $this->getPacConf();
        if ($cdn && $c['linkdomain']) {
            return $c['linkdomain'];
        }
        return $c['domain'] ?: $this->ip;
    }

    public function sub()
    {
        // No token backfill here: this is a public GET endpoint, so we avoid
        // writing xray.json on the hot path (concurrent requests). sidOf() falls
        // back to the uuid when a subtoken is absent; cron/userXr backfill tokens.
        $xr     = $this->getXray();
        $pac    = $this->getPacConf();
        $st     = $this->getXrayStats();
        $domain = ($_GET['cdn'] ?? '') ?: (($_SERVER['SERVER_NAME'] ?? '') ?: $this->getDomain($pac['transport'] != 'Reality'));
        $scheme = empty($this->nginxGetTypeCert()) ? 'http' : 'https';
        $hash   = $this->getHashBot();
        $this->subRateLimit($_GET['id'] ?? '');
        // Resolve by subtoken (preferred) or, for pre-subtoken links, the id.
        $k      = $this->findClientBySid($xr, $_GET['id'] ?? '', !empty($pac['subtoken_strict']));
        $client = $k === null ? null : $xr['inbounds'][0]['settings']['clients'][$k];
        // Missing/disabled id: clean 404 instead of rendering the page with
        // undefined fields (which would warn and break the body).
        if ($client === null || !empty($client['off'])) {
            $this->subNotFound();
        }
        if (!$this->processHwidRequest($client)) {
            exit;
        }
        $email  = $client['email'];
        $expire = $client['time'] ?? '';
        $stok   = $this->sidOf($client); // subscription locator (not the credential)
        $suburl   = "<a href='$scheme://{$domain}/pac$hash/sub?id={$stok}'>subscription</a>";
        $download = $this->getBytes(($st['users'][$k]['global']['download'] ?? 0) + ($st['users'][$k]['session']['download'] ?? 0));
        $upload   = $this->getBytes(($st['users'][$k]['global']['upload'] ?? 0) + ($st['users'][$k]['session']['upload'] ?? 0));
        $singbox  = "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
            'h' => $hash,
            't' => 'si',
            's' => $stok,
        ]));
        $xray = "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
            'h' => $hash,
            't' => 's',
            's' => $stok,
        ]));
        $clash = "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
            'h' => $hash,
            't' => 'cl',
            's' => $stok,
        ]));
        $vless   = $this->linkXray($k);
        $windows = "$scheme://{$domain}/pac$hash?t=si&r=w&s=$stok";
        $_GET['s'] = $stok;
        foreach ([
          'xray'    => 's',
          'singbox' => 'si',
          'clash'   => 'cl'
        ] as $k     => $v) {
            $_GET['t'] = $v;
            $configs[$k] = $this->subscription(1);
        }
        require __DIR__ . '/subscription.php';
    }

    // Client-side Reality settings block for xray (case 's') configs. Base
    // fields use ~placeholders~ filled by replaceTags(); spiderX (item 4) and
    // mldsa65Verify (item 2) are appended only when configured, so a config with
    // nothing tuned is byte-identical to before.
    public function realityClientSettings($fingerprint, array $pac): array
    {
        $rs = [
            "serverName"  => '~server_name~',
            "fingerprint" => $fingerprint,
            "publicKey"   => '~public_key~',
            "shortId"     => '~short_id~',
        ];
        $spx = $this->normalizeSpiderXValue((string) ($pac['reality']['spiderX'] ?? ''));
        if ($spx !== '' && $spx !== '/') {
            $rs['spiderX'] = $spx;
        }
        if ($this->mldsaReady($pac)) {
            $rs['mldsa65Verify'] = $pac['reality']['mldsa65Verify'];
        }
        return $rs;
    }

    // sockopt для inbound'ов, которые слушают ЗА nginx (xhttp, trojan-grpc,
    // websocket). Без него xray видит источником каждого соединения сам nginx
    // (10.10.0.2), а не клиента, потому что TLS терминирует nginx и никакого
    // PROXY-протокола до xray не доходит (он есть только у Reality). Ломается
    // сразу три вещи: `from <ip>` в /logs/xray у всех клиентов одинаковый →
    // журнал подключений (recordConnLog) бесполезен, ip_limit никогда не
    // срабатывает (у email всегда ровно один IP), а сам xray на КАЖДЫЙ запрос
    // пишет warning «received "X-Forwarded-For" … but "sockopt.
    // trustedXForwardedFor" is not configured» — в packet-up это до 30 строк в
    // секунду на клиента, лог пухнет на ровном месте.
    //
    // Значение — список ИМЁН заголовков (не адресов!): xray доверяет XFF, если
    // в запросе присутствует любой из них (common/protocol/http/headers.go,
    // ApplyTrustedXForwardedFor + headers_test.go). X-Real-IP ставит сам nginx
    // через proxy_set_header/grpc_set_header, т.е. клиент его подделать не
    // может — заголовок клиента при этом ЗАМЕЩАЕТСЯ, а не дополняется. Сам IP
    // берётся из ПЕРВОГО элемента X-Forwarded-For, поэтому в nginx он выставлен
    // в $remote_addr, а не в $proxy_add_x_forwarded_for (см. локацию /ws).
    public function nginxFrontedSockopt(): array
    {
        return ['trustedXForwardedFor' => ['X-Real-IP']];
    }

    // Единый источник правды для клиентской части XHTTP (xray-core).
    //
    // Xray собирает xhttpSettings так (infra/conf/transport_method.go, Build()):
    // если задан "extra", он парсится КАК ЦЕЛЫЙ SplitHTTPConfig и заменяет собой
    // внешний объект — из внешнего переносятся только host/path/mode. Поэтому все
    // остальные поля обязаны лежать внутри "extra", а не рядом с ним.
    //
    // Тот же самый набор уходит в vless://…&extra=<urlencoded json> — раньше в
    // ссылке лежал захардкоженный процент-энкоженный блоб, и любая правка JSON-
    // конфига молча расходилась со ссылкой. Теперь оба берут массив отсюда.
    //
    // Значения: xray-дефолты (scMaxEachPostBytes 1000000, scMinPostsIntervalMs 30,
    // xPaddingBytes 100-1000) плюс xmux с maxConcurrency 16-32. maxConnections
    // держим на 0: при обоих ненулевых Build() падает с "maxConnections cannot be
    // specified together with maxConcurrency".
    public function xhttpClientExtra(): array
    {
        return [
            "xmux" => [
                "cMaxReuseTimes"   => 0,
                "maxConcurrency"   => "16-32",
                "maxConnections"   => 0,
                "hKeepAlivePeriod" => 0,
                "hMaxRequestTimes" => "600-900",
                "hMaxReusableSecs" => "1800-3000",
            ],
            "noGRPCHeader"         => false,
            "xPaddingBytes"        => "100-1000",
            "scMaxEachPostBytes"   => 1000000,
            "scMinPostsIntervalMs" => 30,
            // Серверная опция (периодический keep-alive в stream-up); на клиенте
            // инертна, но оставлена — xray её принимает, а конфиг и ссылка должны
            // совпадать байт-в-байт с тем, что уже роздано пользователям.
            "scStreamUpServerSecs" => "20-80",
        ];
    }

    // Item 1: inject a freedom outbound carrying TLS fragment and/or UDP noise and
    // route the main proxy outbound through it via sockopt.dialerProxy (xray only).
    // No-op unless at least one is enabled, so default configs are unchanged.
    public function applyDpiFragment(array &$c, $index, array $pac): void
    {
        $frag  = !empty($pac['dpi']['fragment']['enabled']);
        $noise = !empty($pac['dpi']['noise']['enabled']);
        if (!$frag && !$noise) {
            return;
        }
        $settings = ['domainStrategy' => 'AsIs'];
        if ($frag) {
            $f = $pac['dpi']['fragment'];
            $settings['fragment'] = [
                'packets'  => ($f['packets']  ?? '') ?: '1-3',
                'length'   => ($f['length']   ?? '') ?: '100-200',
                'interval' => ($f['interval'] ?? '') ?: '10-20',
            ];
            // maxSplit пишем ТОЛЬКО когда задан: пустое поле = дефолт xray (без
            // лимита числа фрагментов), поэтому не добавляем его в конфиг.
            // xray принимает и число, и диапазон-строку ("3-5") как Int32Range.
            if (($f['maxSplit'] ?? '') !== '') {
                $settings['fragment']['maxSplit'] = $f['maxSplit'];
            }
        }
        if ($noise) {
            // Xray читает noises как МАССИВ — шлём все заданные пакеты подряд.
            // Пустой список при включённом noise = один дефолтный rand-пакет
            // (прежнее поведение). Для str/hex/base64 packet обязателен —
            // запись без него пропускаем, чтобы xray не упал на парсинге.
            $noises = [];
            foreach ($this->dpiNoiseList($pac) as $n) {
                $type   = ($n['type']   ?? '') ?: 'rand';
                $packet = (string) ($n['packet'] ?? '');
                if ($type !== 'rand' && $packet === '') {
                    continue;
                }
                $noises[] = [
                    'type'   => $type,
                    'packet' => $packet !== '' ? $packet : '10-20',
                    'delay'  => ($n['delay'] ?? '') ?: '10-16',
                ];
            }
            if (!$noises) {
                $noises[] = ['type' => 'rand', 'packet' => '10-20', 'delay' => '10-16'];
            }
            $settings['noises'] = $noises;
        }
        $c['outbounds'][] = [
            'tag'      => 'dpi-fragment',
            'protocol' => 'freedom',
            'settings' => $settings,
        ];
        if (isset($c['outbounds'][$index])) {
            $c['outbounds'][$index]['streamSettings']['sockopt']['dialerProxy'] = 'dpi-fragment';
        }
    }

    // UDP-noise как список пакетов. Новый формат — $pac['dpi']['noise']['list'];
    // старый одиночный noise (type/packet/delay прямо в ['noise']) мигрируем в
    // list[0] на лету, чтобы существующие конфиги не потеряли настройку.
    public function dpiNoiseList(array $pac): array
    {
        $n = $pac['dpi']['noise'] ?? [];
        if (isset($n['list']) && is_array($n['list'])) {
            return array_values($n['list']);
        }
        if (($n['type'] ?? '') !== '' || ($n['packet'] ?? '') !== '' || ($n['delay'] ?? '') !== '') {
            return [[
                'type'   => $n['type']   ?? '',
                'packet' => $n['packet'] ?? '',
                'delay'  => $n['delay']  ?? '',
            ]];
        }
        return [];
    }

    public function applyClientSniffing(array &$c, array $pac): void
    {
        if (!is_array($pac['sniffing'] ?? null)) {
            return;
        }
        $sniffing = $this->sniffingConfig($pac);
        if (empty($c['inbounds']) || !is_array($c['inbounds'])) {
            return;
        }
        foreach ($c['inbounds'] as &$inbound) {
            if (isset($inbound['sniffing'])) {
                $inbound['sniffing'] = $sniffing;
            }
        }
        unset($inbound);
    }

    // Коды one-tap deep-link'ов импорта, приходящие в query-параметре 'r'
    // (ссылки строятся в relaySub() и в карточке клиента). Список намеренно
    // плоский, без привязки к 't': целевой URL редиректа строится независимо от
    // формата подписки, поэтому пары вроде t=si&r=c исторически валидны и
    // остаются рабочими в старых сообщениях чата.
    protected function deepLinkCodes(): array
    {
        return ['v', 'st', 'si', 'h', 'k', 'w', 'c', 'rh'];
    }

    public function subscription($return = false)
    {
        switch ($_GET['t'] ?? '') {
            case 's':
                $type = 'v2ray';
                break;
            case 'si':
                $type = 'sing';
                break;
            case 'cl':
                $type = 'clash';
                break;
            default:
                // Unknown/missing format: bail cleanly instead of running on with an
                // undefined $type (which would warn and emit a broken body).
                if (!empty($return)) {
                    return '';
                }
                $this->subNotFound('Unknown subscription format.');
        }
        // Периодическая выборка rule-set'а ядром: mihomo тянет rule-providers
        // (clashRules(), t=cl), sing-box — SRS (createRuleSet(), t=si). Такие URL
        // строятся ТОЛЬКО base64-токеном в пути, поэтому наличие 'r' в токене —
        // надёжный признак, не пересекающийся с именами deep-link'ов импорта.
        $ruleSetReq = in_array($type, ['clash', 'sing'], true)
            && (string) ($this->subToken['r'] ?? '') !== '';
        $pac    = $this->getPacConf();
        $domain = ($_GET['cdn'] ?? '') ?: (($_SERVER['SERVER_NAME'] ?? '') ?: $this->getDomain($pac['transport'] != 'Reality'));
        $xr     = $this->getXray();
        $scheme = empty($this->nginxGetTypeCert()) ? 'http' : 'https';
        $hash   = $this->getHashBot();

        // Resolve by subtoken (preferred) or id (pre-subtoken links).
        $sid    = $_GET['s'] ?? '';
        // Лимитируем только реальные HTTP-запросы: внутренние вызовы
        // (subscription(true) из кода бота) не должны крутить счётчик.
        // Обновления rule-set'ов идут в отдельном ведре: несколько списков с
        // коротким interval иначе выедали бы общий бюджет, и 429 прилетал бы
        // самой подписке.
        if (empty($return)) {
            $this->subRateLimit($sid, $ruleSetReq ? 'rs' : '');
        }
        $k      = $this->findClientBySid($xr, $sid, !empty($pac['subtoken_strict']));
        $client = $k === null ? null : $xr['inbounds'][0]['settings']['clients'][$k];
        if ($client === null || !empty($client['off'])) {
            if (!empty($return)) {
                return '';
            }
            $this->subNotFound();
        }
        $template = base64_decode($client["{$type}template"] ?? '');
        $uid      = $client['id'];               // credential (embedded in config)
        $email    = $client['email'];
        $stok     = $this->sidOf($client);       // subscription locator only

        // HWID неприменим к выборке rule-set'а: это запрос ядра за списком правил,
        // а не устройство пользователя, и заголовок X-HWID оно не шлёт — иначе
        // лимитер отдавал бы 429 и правила молча оставались пустыми. Утечки нет:
        // rule-set содержит только домены/адреса правил, без credential'ов.
        if (!$return && !$ruleSetReq && !$this->processHwidRequest($client)) {
            exit;
        }

        // Deep-link импорта — только если 'r' пришёл не из токена (иначе это
        // выборка rule-set'а) и совпадает с известным кодом клиента. Без первого
        // условия rule-set с именем 'c'/'si'/… перехватывался бы этим свитчом и
        // вместо списка правил уходил редирект в клиент.
        $isDeepLink = !$ruleSetReq
            && in_array((string) ($_GET['r'] ?? ''), $this->deepLinkCodes(), true);

        if ($isDeepLink) {
            // Relay variant: the import-remote-profile deep links must point at
            // the relay-flavoured content URL (token carries 'relay' => <name>),
            // otherwise the imported subscription would update straight from the
            // origin instead of the relay.
            $relayKey = (!empty($_GET['relay']) && !empty($pac['relays'][$_GET['relay']]))
                ? ['relay' => $_GET['relay']]
                : [];
            $si = "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
                'h' => $hash,
                't' => 'si',
                's' => $stok,
            ] + $relayKey));
            $v2 = "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
                'h' => $hash,
                't' => 's',
                's' => $stok,
            ] + $relayKey));
            $cl = "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
                'h' => $hash,
                't' => 'cl',
                's' => $stok,
            ] + $relayKey));
            switch ($_GET['r']) {
                case 'si':
                    header("Location: sing-box://import-remote-profile/?url=$si");
                    exit;
                case 'st':
                    header("Location: streisand://import/$v2");
                    exit;
                case 'v':
                    header("Location: v2rayng://install-config?url=$v2");
                    exit;
                case 'k':
                    header("Location: karing://install-config?url=$si");
                    exit;
                case 'h':
                    header("Location: hiddify://install-config/?url=$si");
                    exit;
                case 'c':
                    header("Location: clash://install-config/?url=$cl&overwrite=no&name=$email");
                    exit;
                case 'rh':
                    header("Location: rabbithole://add/$cl");
                    exit;
                case 'w':
                    $link = htmlspecialchars($si, ENT_XML1, 'UTF-8');
                    $n    = "singbox_$uid.zip";
                    copy('/singbox/singbox.zip', $n);
                    $zip = new ZipArchive();
                    $zip->open($n, ZipArchive::CREATE);
                    $zip->addFromString('winsw3.xml', preg_replace('#~url~#', $link, file_get_contents('/singbox/winsw3.xml')));
                    $zip->close();
                    header('Content-Disposition: attachment; filename="singbox.zip"');
                    echo file_get_contents($n);
                    unlink($n);
                    exit;
            }
        }
        switch (true) {
            case !empty($template) && $template == 'origin':
            case empty($template) && empty($pac["default{$type}template"]):
            case empty($template) && empty($pac["{$type}templates"][base64_decode($pac["default{$type}template"])]):
            case !empty($template) && empty($pac["{$type}templates"][$template]):
                $c = json_decode(file_get_contents("/config/{$type}.json"), true);
                break;
            case !empty($template):
                $c = $pac["{$type}templates"][$template];
                break;

            default:
                $c = $pac["{$type}templates"][base64_decode($pac["default{$type}template"])];
                break;
        }

        $outbound = $pac['outbound'] ?: 'proxy';
        // Prefix the outbound/proxy name with server-country flag(s) so the client
        // shows e.g. "🇫🇷 proxy" next to the node. A relay subscription hops
        // relay → origin, so it gets two flags — the relay endpoint's first, then
        // the origin (destination) server's ("🇫🇷🇩🇪 proxy"); a plain subscription
        // gets just the origin's. The tag is substituted consistently everywhere
        // (proxy-groups, routing), so internal references stay intact — only the
        // visible name changes.
        $relayCfg = (!empty($_GET['relay']) && !empty($pac['relays'][$_GET['relay']]))
            ? $pac['relays'][$_GET['relay']]
            : null;
        $flagHosts = $relayCfg
            ? [($relayCfg['address'] ?: ($relayCfg['awg_address'] ?? '')), $this->ip]
            : [$this->ip];
        $outbound = $this->flagName($outbound, $flagHosts);
        $c = json_decode($this->replaceTags(json_encode($c), [
            '~outbound~' => $outbound,
        ]), true);
        // Clash/mihomo keeps the node in proxies[] (keyed by name); xray/sing-box
        // use outbounds[] (keyed by tag). Search the array that matches the format:
        // searching outbounds first would, for a clash template that also carries an
        // outbounds block, pick an outbounds index and then mis-index into proxies[].
        // The ?? [] also avoids a warning when the template lacks the other key.
        $index = null;
        if (($_GET['t'] ?? '') === 'cl') {
            foreach ($c['proxies'] ?? [] as $k => $v) {
                if (($v['name'] ?? '') == $outbound) {
                    $index = $k;
                    break;
                }
            }
        } else {
            foreach ($c['outbounds'] ?? [] as $k => $v) {
                if (($v['tag'] ?? '') == $outbound) {
                    $index = $k;
                    break;
                }
            }
        }
        // No matching node (e.g. a custom template that hard-codes the tag instead
        // of using the ~outbound~ placeholder, so the flag-prefixed name no longer
        // matches): bail with a clean 404 rather than indexing $c[...][null] and
        // silently serving a config with the real endpoint/uid never injected.
        if ($index === null) {
            if (!empty($return)) {
                return '';
            }
            $this->subNotFound('Subscription template has no matching outbound.');
        }

        $fingerprint = $pac['fingerprint'] ?: 'chrome';
        // randomizednoalpn and unsafe are Xray-only uTLS ids: sing-box errors on an
        // unknown fingerprint and mihomo silently drops uTLS, so map them to a
        // supported value for the sing-box (si) and clash (cl) configs.
        if (in_array($_GET['t'], ['si', 'cl'], true)) {
            $fingerprint = ['randomizednoalpn' => 'randomized', 'unsafe' => 'chrome'][$fingerprint] ?? $fingerprint;
        }

        switch ($_GET['t']) {
            case 's':
                $c['outbounds'][$index]['settings']['vnext'][0]['address']  = '~domain~';
                $c['outbounds'][$index]['settings']['vnext'][0]['users'][0] = [
                    'id'         => '~uid~',
                    'encryption' => 'none',
                ];
                switch ($pac['transport']) {
                    case 'Reality':
                        $c['outbounds'][$index]['settings']['vnext'][0]['users'][0]["flow"] = "xtls-rprx-vision";
                        $c['outbounds'][$index]['streamSettings']                           = [
                            "network"         => "tcp",
                            "security"        => "reality",
                            "realitySettings" => $this->realityClientSettings($fingerprint, $pac),
                        ];
                        $c['outbounds'][$index]['mux'] = [
                            "enabled"     => false,
                            "concurrency" => -1
                        ];
                        break;
                    case 'xhttp':
                        $c['outbounds'][$index]['streamSettings'] = [
                            "network"  => "xhttp",
                            "security" => "tls",

                            // mode пинуем на packet-up, а не auto: при TLS+h2 auto
                            // выбрал бы stream-up, а он за nginx требует grpc_pass
                            // (см. XHTTP: Beyond REALITY). Локация /ws у нас на
                            // proxy_pass и обслуживает ещё и websocket, поэтому
                            // единственный совместимый режим — packet-up.
                            // Сервер слушает mode=auto и принимает его.
                            "xhttpSettings" => [
                                "host"  => "~domain~",
                                "mode"  => "packet-up",
                                "path"  => "/ws$hash",
                                "extra" => $this->xhttpClientExtra(),
                            ],

                            "tlsSettings" => [
                                "allowInsecure" => false,
                                "alpn"          => ["h2", "http/1.1"],
                                "fingerprint"   => $fingerprint,
                                "serverName"    => "~domain~",
                                "show"          => false
                            ]
                        ];
                        unset($c['outbounds'][$index]['mux']);
                        break;
                    case 'trojan-grpc':
                        $c['outbounds'][$index] = [
                            'tag'      => $outbound,
                            'protocol' => 'trojan',
                            'settings' => [
                                'servers' => [
                                    [
                                        'address'  => '~domain~',
                                        'port'     => 443,
                                        'password' => '~uid~',
                                    ]
                                ]
                            ],
                            'streamSettings' => [
                                'network'      => 'grpc',
                                'security'     => 'tls',
                                'grpcSettings' => [
                                    'serviceName' => "grpc$hash",
                                ],
                                'tlsSettings'  => [
                                    'allowInsecure' => false,
                                    'alpn'          => ['h2'],
                                    'fingerprint'   => $fingerprint,
                                    'serverName'    => '~domain~',
                                    'show'          => false
                                ]
                            ]
                        ];
                        break;

                    default:
                        $c['outbounds'][$index]['streamSettings'] = [
                            "network"    => "ws",
                            "security"   => "tls",
                            "wsSettings" => [
                                "path" => "/ws$hash?ed=2560"
                            ],
                            "tlsSettings" => [
                                "allowInsecure" => false,
                                "serverName"    => '~domain~',
                                "fingerprint"   => $fingerprint
                            ]
                        ];
                        unset($c['outbounds'][$index]['mux']);
                        break;
                }
                // Item 1: TLS fragment / UDP noise via freedom dialerProxy (xray only).
                $this->applyDpiFragment($c, $index, $pac);
                $this->applyClientSniffing($c, $pac);

                break;
            case 'si':
                $c['outbounds'][$index]['uuid'] = '~uid~';
                switch ($pac['transport']) {
                    case 'Reality':
                        unset($c['outbounds'][$index]["transport"]);
                        $c['outbounds'][$index]['flow']                         = 'xtls-rprx-vision';
                        $c['outbounds'][$index]['tls']['reality']['public_key'] = '~public_key~';
                        $c['outbounds'][$index]['tls']['server_name']           = '~server_name~';
                        $c['outbounds'][$index]['tls']['reality']['short_id']   = '~short_id~';
                        break;
                    case 'xhttp':
                        unset($c['outbounds'][$index]['flow']);
                        unset($c['outbounds'][$index]['tls']['reality']);

                        // ВАЖНО: XHTTP нет в апстримном sing-box — option/
                        // v2ray_transport.go знает только http/ws/quic/grpc/
                        // httpupgrade и на чужом type падает с "unknown transport
                        // type". Транспорт есть только в сборках-форках
                        // (sing-box-extended и производные), и снейк-кейс ниже —
                        // именно их диалект. Пользователя предупреждаем в меню
                        // xray ('xhttp singbox warn').
                        //
                        // x_padding_bytes обязателен: валидатор форка смотрит на
                        // сырое поле, а не на нормализованное, и при отсутствии
                        // ключа падает с "x_padding_bytes cannot be disabled" —
                        // без него КАЖДЫЙ сгенерированный конфиг отвергался.
                        // Остальные значения выровнены с xhttpClientExtra(),
                        // чтобы один и тот же сервер вёл себя одинаково во всех
                        // клиентах; c_max_reuse_times "0-1" ломал переиспользование
                        // соединений почти на каждом втором (0 = без лимита).
                        // max_connections держим на "0": при обоих ненулевых форк
                        // отвечает "max_connections cannot be specified together
                        // with max_concurrency".
                        $c['outbounds'][$index]["transport"] = [
                            "type" => "xhttp",
                            "host" => "~domain~",
                            "mode" => "packet-up",
                            "path" => "/ws$hash",
                            // Диапазоны шлём строками, как уже работающие
                            // max_concurrency/max_connections: у форка это
                            // Range-тип, строковая форма разбирается заведомо.
                            "x_padding_bytes"          => "100-1000",
                            "sc_max_each_post_bytes"   => "1000000",
                            "sc_min_posts_interval_ms" => "30",
                            "xmux" => [
                                "max_concurrency"   => "16-32",
                                "max_connections"   => "0",
                                "c_max_reuse_times" => "0",
                                "h_max_request_times" => "600-900",
                                "h_max_reusable_secs" => "1800-3000",
                                "h_keep_alive_period" => 60
                            ]
                        ];

                        $c['outbounds'][$index]['tls'] = [
                            "enabled"     => true,
                            "insecure"    => false,
                            "server_name" => "~domain~",
                            "alpn"        => ["h2"],
                            "utls"        => [
                                "enabled"     => true,
                                "fingerprint" => $fingerprint,
                            ],
                        ];
                        break;
                    case 'trojan-grpc':
                        $c['outbounds'][$index]['type']     = 'trojan';
                        $c['outbounds'][$index]['password'] = '~uid~';
                        unset($c['outbounds'][$index]['uuid']);
                        unset($c['outbounds'][$index]['flow']);
                        unset($c['outbounds'][$index]['packet_encoding']);
                        unset($c['outbounds'][$index]['tls']['reality']);

                        $c['outbounds'][$index]['transport'] = [
                            'type'         => 'grpc',
                            'service_name' => "grpc$hash",
                        ];
                        $c['outbounds'][$index]['tls'] = [
                            'enabled'     => true,
                            'insecure'    => false,
                            'server_name' => '~domain~',
                            'alpn'        => ['h2'],
                            'utls'        => [
                                'enabled'     => true,
                                'fingerprint' => $fingerprint,
                            ],
                        ];
                        break;

                    default:
                        unset($c['outbounds'][$index]['tls']['reality']);
                        unset($c['outbounds'][$index]['flow']);
                        $c['outbounds'][$index]["transport"] = [
                            "type" => "ws",
                            "path" => "/ws$hash"
                        ];
                        $c['outbounds'][$index]['tls']['server_name'] = '~domain~';
                        break;
                }
                break;
            case 'cl':
                $c['proxies'][$index]['server'] = '~domain~';
                $c['proxies'][$index]['uuid']   = '~uid~';
                switch (true) {
                    case $pac['transport'] == 'Reality':
                        unset($c['proxies'][$index]["ws-opts"]);
                        unset($c['proxies'][$index]["skip-cert-verify"]);
                        $c['proxies'][$index]["network"]      = "tcp";
                        $c['proxies'][$index]['flow']         = 'xtls-rprx-vision';
                        $c['proxies'][$index]['servername']  = '~server_name~';
                        $c['proxies'][$index]['reality-opts'] = [
                            'public-key' => '~public_key~',
                            'short-id'   => '~short_id~',
                        ];
                        break;
                    case $pac['transport'] == 'xhttp':
                        unset($c['proxies'][$index]['ws-opts']);
                        unset($c['proxies'][$index]['flow']);
                        unset($c['proxies'][$index]['reality-opts']);

                        $c['proxies'][$index]['network']            = 'xhttp';
                        $c['proxies'][$index]['client-fingerprint'] = $fingerprint;
                        $c['proxies'][$index]['tls']                = true;
                        $c['proxies'][$index]['alpn']               = ['h2'];
                        $c['proxies'][$index]['servername']         = '~domain~';
                        $c['proxies'][$index]['skip-cert-verify']   = false;

                        // Имена ключей — kebab-диалект mihomo (adapter/outbound/
                        // vless.go, XHTTPOptions/XHTTPReuseSettings); xmux там
                        // называется reuse-settings.
                        // Значения выровнены с xhttpClientExtra(): было
                        // max-concurrency 8-16 и h-max-request-times 100-200,
                        // т.е. вдвое меньше параллелизма и переоткрытие соединения
                        // каждые 100-200 POST'ов (в packet-up один POST = один
                        // запрос, это секунды). Дефолт xray — 600-900.
                        $c['proxies'][$index]['xhttp-opts'] = [
                            'host'                     => '~domain~',
                            'path'                     => "/ws$hash",
                            'mode'                     => 'packet-up',
                            'no-grpc-header'           => false,
                            'x-padding-bytes'          => '100-1000',
                            'sc-max-each-post-bytes'   => 1000000,
                            'sc-min-posts-interval-ms' => 30,
                            'reuse-settings'           => [
                                'max-connections'   => '0',
                                'max-concurrency'   => '16-32',
                                'c-max-reuse-times' => '0',
                                'h-max-request-times' => '600-900',
                                'h-max-reusable-secs' => '1800-3000',
                            ],
                        ];
                        break;
                    case $pac['transport'] == 'trojan-grpc':
                        unset($c['proxies'][$index]['ws-opts']);
                        unset($c['proxies'][$index]['flow']);
                        unset($c['proxies'][$index]['reality-opts']);
                        unset($c['proxies'][$index]['xhttp-opts']);
                        unset($c['proxies'][$index]['uuid']);

                        $c['proxies'][$index]['type']             = 'trojan';
                        $c['proxies'][$index]['password']         = '~uid~';
                        $c['proxies'][$index]['network']          = 'grpc';
                        $c['proxies'][$index]['tls']              = true;
                        $c['proxies'][$index]['alpn']             = ['h2'];
                        $c['proxies'][$index]['skip-cert-verify'] = false;
                        // Clash.Meta trojan читает SNI из поля `sni`, а НЕ `servername`
                        // (последнее — только для vless/vmess и trojan'ом игнорируется).
                        unset($c['proxies'][$index]['servername']);
                        $c['proxies'][$index]['sni']              = '~domain~';
                        $c['proxies'][$index]['grpc-opts']        = [
                            'grpc-service-name' => "grpc$hash",
                        ];
                        break;

                    default:
                        unset($c['proxies'][$index]['flow']);
                        unset($c['proxies'][$index]['reality-opts']);
                        $c['proxies'][$index]["network"]          = "ws";
                        $c['proxies'][$index]["ws-opts"]['path']  = "/ws$hash";
                        $c['proxies'][$index]["skip-cert-verify"] = false;
                        $c['proxies'][$index]['servername']       = '~domain~';
                        break;
                }


                    if (!empty($client['awg']) && !empty($awg = $this->getAwgClient($client['awg']))) {
                        $awgproxy = [
                            "name"        => 'awg',
                            "type"        => 'wireguard',
                            "server"      => $awg['server'],
                            "port"        => $awg['port'],
                            "ip"          => $awg['ip'],
                            "private-key" => $awg['private-key'],
                            "public-key"  => $awg['public-key'],
                            "allowed-ips" => [
                                "0.0.0.0/0",
                            ],
                            "mtu"                  => $awg['mtu'],
                            // Целое число: диапазон 3.0 mihomo здесь не примет.
                            "persistent-keepalive" => self::keepaliveInt($awg['persistent-keepalive'] ?? 20),
                            "udp"                  => true,
                        ];
                        if (!empty($awg['pre-shared-key'])) {
                            $awgproxy['pre-shared-key'] = $awg['pre-shared-key'];
                        }
                        if (!empty($awg['amnezia-wg-option'])) {
                            $awgproxy['amnezia-wg-option'] = $awg['amnezia-wg-option'];
                        }
                        $c['proxies'][] = $awgproxy;
                        $c['proxy-groups'][0]['proxies'][] = 'awg';
                    }

                $tunpackage = array_filter($pac['tunpackage'] ?? []);
                $tunprocess = array_filter($pac['tunprocess'] ?? []);
                if (!empty($tunpackage) || !empty($tunprocess)) {
                    if (!empty($tunpackage)) {
                        if (!empty($pac['tunpackagemode'])) {
                            $c['tun']['exclude-package'] = array_keys($tunpackage);
                        } else {
                            $c['tun']['include-package'] = array_keys($tunpackage);
                        }
                    }
                    if (!empty($tunprocess)) {
                        if (!empty($pac['tunprocessmode'])) {
                            $c['tun']['exclude-process'] = array_keys($tunprocess);
                        } else {
                            $c['tun']['include-process'] = array_keys($tunprocess);
                        }
                    }
                }
                break;
        }
        // Cloudflare WARP profile of this server, exposed as template tags so a
        // (per-user) template can embed a wireguard-WARP proxy with the dynamic
        // server secrets. Empty array when warp isn't set up — the tags then
        // resolve to empty strings / defaults.
        $warp = $this->getWarpProfile() ?: [];
        $c = json_decode($this->replaceTags(json_encode($c), [
            '"~pac~"'        => json_encode(array_keys(array_filter($pac['includelist'] ?: []))),
            '"~block~"'      => json_encode(array_keys(array_filter($pac['blocklist'] ?: []))),
            '"~warp~"'       => json_encode(array_keys(array_filter($pac['warplist'] ?: []))),
            '"~process~"'    => json_encode(array_keys(array_filter($pac['processlist'] ?: []))),
            '"~package~"'    => json_encode(array_keys(array_filter($pac['packagelist'] ?: []))),
            '"~subnet~"'     => json_encode(array_keys(array_filter($pac['subnetlist'] ?: []))),
            '"~warp_port~"'      => (int) ($warp['port'] ?? 2408),
            '"~warp_mtu~"'       => (int) ($warp['mtu'] ?? 1280),
            '~warp_server~'      => $warp['server'] ?? '',
            '~warp_ip~'          => $warp['ip'] ?? '',
            '~warp_private_key~' => $warp['private-key'] ?? '',
            '~warp_public_key~'  => $warp['public-key'] ?? '',
            '~dns~'          => "https://$domain/dns-query$hash/$uid",
            '~dnspath~'      => "/dns-query$hash/$uid",
            '~uid~'          => ($pac['transport'] == 'trojan-grpc' ? ($client['password'] ?? $uid) : $uid),
            '~domain~'       => $domain,
            '~directdomain~' => $pac['domain'],
            '~cdndomain~'    => $pac['linkdomain'],
            '~short_id~'     => $xr['inbounds'][0]['streamSettings']['realitySettings']['shortIds'][0],
            '~email~'        => $email,
            '~public_key~'   => $pac['xray'],
            '~server_name~'  => $xr['inbounds'][0]['streamSettings']['realitySettings']['serverNames'][0],
            '~fingerprint~'  => $fingerprint,
            '~ip~'           => $this->ip,
            '~outbound~'     => $outbound,
        ]), true);

        switch ($_GET['t']) {
            case 's':
                if (!empty($c['routing']['rules'])) {
                    $ips = $domains = $other = [];
                    // Раскладывает запись в ip[]/domain[] по её типу, а не по тому,
                    // из какого поля она пришла: шаблон может держать geoip: в ip[],
                    // а домен — по ошибке там же. geosite:/geoip: НЕ вырезаем —
                    // клиент тоже xray, штатная geodata у него есть.
                    $sort = function ($j, $tag) use (&$ips, &$domains) {
                        $cl = $this->classifyRouteEntry($j);
                        // ext:/extip: — серверные .dat, на клиенте файла нет.
                        // Пустые/битые записи не отдаём клиенту по той же причине,
                        // что и серверу: пустой токен в domain[] матчит всё.
                        if (in_array($cl['kind'], ['ext', 'extip'], true) || !$this->routeEntryUsable($cl)) {
                            return;
                        }
                        if ($cl['kind'] == 'ip') {
                            $ips[$tag][] = $cl['value'];
                        } elseif ($cl['kind'] == 'geoip') {
                            $ips[$tag][] = "geoip:{$cl['value']}";
                        } else {
                            $domains[$tag][] = $this->xrayDomainToken($cl);
                        }
                    };
                    foreach ($c['routing']['rules'] as $k => $v) {
                        $matched = false;
                        if (array_key_exists('domain', $v) && !empty($v['domain'])) {
                            foreach ($v['domain'] as $j) {
                                $sort($j, $v['outboundTag']);
                            }
                            $matched = true;
                        }
                        if (array_key_exists('ip', $v) && !empty($v['ip'])) {
                            foreach ($v['ip'] as $j) {
                                $sort($j, $v['outboundTag']);
                            }
                            $matched = true;
                        }
                        // Правила без domain/ip (port/protocol/inboundTag и т.п.)
                        // сохраняем как есть, иначе они молча пропадали.
                        if (!$matched) {
                            $other[] = $v;
                        }
                    }
                    $c['routing']['rules'] = [];

                    if (!empty($domains)) {
                        foreach ($domains as $k => $v) {
                            $c['routing']['rules'][] = [
                                "type"        => "field",
                                "outboundTag" => $k,
                                "domain"      => $v
                            ];
                        }
                    }
                    if (!empty($ips)) {
                        foreach ($ips as $k => $v) {
                            $c['routing']['rules'][] = [
                                "type"        => "field",
                                "outboundTag" => $k,
                                "ip"          => $v
                            ];
                        }
                    }
                    foreach ($other as $v) {
                        $c['routing']['rules'][] = $v;
                    }
                }
                break;
            case 'si':
                $c['route'] = $this->addRuleSet($c['route']);
                $c['route'] = $this->createRuleSet($c['route'], $stok, $domain);
                // Защита: убрать из dns/route правил ссылки на rule_set, которые
                // не были определены в route.rule_set (напр. запись есть в
                // dns-шаблоне, но отсутствует в rulessetlist) — иначе клиент
                // падает с "rule-set not found" и весь конфиг не импортируется.
                $c = $this->pruneRuleSetRefs($c);
                if (!empty($c['route']['rules'])) {
                    foreach ($c['route']['rules'] as $k => $v) {
                        if (count($v) == 1 && array_key_exists('outbound', $v)) {
                            unset($c['route']['rules'][$k]);
                        }
                    }
                    $c['route']['rules'] = array_values($c['route']['rules']);
                }
                if (empty($c['route'])) {
                    unset($c['route']);
                }
                break;
            case 'cl':
                $c = $this->addClashRuleSet($c);
                if (!empty($c['rules'])) {
                    $c = $this->clashRules($c, $stok, $domain);
                    if (count($c['rules']) == 1) {
                        unset($c['rules']);
                    }
                }
                break;
        }
        // Relay variant: swap only the endpoint address+port to the chosen relay
        // (selected by name via $_GET['relay']); everything else stays as-is.
        if (!empty($_GET['relay']) && !empty($pac['relays'][$_GET['relay']]) && isset($index)) {
            $this->applyRelay($c, $_GET['t'], $index, $pac['relays'][$_GET['relay']]);
            // Mihomo-конфиг может нести встроенный wireguard/awg-прокси; его
            // эндпоинт подменяем на отдельный WG/AWG-relay (если задан), чтобы
            // основной прокси и awg ходили через разные relay/порты.
            if ($_GET['t'] == 'cl') {
                $this->applyAwgRelay($c, $pac['relays'][$_GET['relay']]);
            }
        }
        if (!empty($return)) {
            if ($_GET['t'] == 'cl') {
                return yaml_emit($c);
            }
            return json_encode($c);
        }

        // The body carries client secrets (UUID/password, reality keys) — keep it
        // out of any cache/index (defense-in-depth).
        $this->subSecurityHeaders();
        if ($_GET['t'] == 'cl') {
            header('Content-type: text/yaml');
            echo yaml_emit($c);
            return;
        }

        header('Content-type: application/json');
        echo json_encode($c);
    }

    // Response headers for any subscription body (contains client secrets): no
    // caching, no indexing, no MIME sniffing. Mirrors the relay repo's nginx.
    public function subSecurityHeaders()
    {
        header('Cache-Control: no-store, no-cache, must-revalidate');
        header('Pragma: no-cache');
        header('X-Content-Type-Options: nosniff');
        header('X-Robots-Tag: noindex, nofollow');
        header('Referrer-Policy: no-referrer');
        // Pin TLS so a client that once reached the sub over HTTPS never silently
        // falls back to plaintext http (where the config would be sniffable). Only
        // meaningful when a cert is configured (nginx serves 443); browsers ignore
        // it over plain http anyway.
        if (!empty($this->nginxGetTypeCert())) {
            header('Strict-Transport-Security: max-age=31536000; includeSubDomains');
        }
    }

    // Rate-limit подписочных эндпоинтов: файловый счётчик окно+лимит на пару
    // (sid, IP). Тормозит перебор sid и выкачивание подписок ботами; легитимный
    // клиент обновляется раз в часы — дефолт 30 req / 5 мин не заденет даже
    // ручные переимпорты. Настройка: pac.sub_rate_max (0 = выкл — но только для
    // ведра подписки, ведро 'rs' обнуляется своим pac.sub_rate_max_rs) /
    // pac.sub_rate_window (сек). Вызывается ДО резолва sid — невалидные sid
    // тоже считаются (анти-brute-force).
    // $scope разводит счётчики по независимым вёдрам (напр. 'rs' — периодические
    // выборки rule-set'ов), чтобы фоновый трафик не расходовал бюджет подписки.
    // У ведра 'rs' свой дефолт: ядро тянет КАЖДЫЙ список отдельным запросом с
    // interval из шаблона (30s), т.е. 6 списков дают ~60 запросов за 5-минутное
    // окно. Лимит подписки (30) резал бы их половину, и правила молча оставались
    // бы пустыми — трафик уходил бы в direct мимо block/warp. Запас x4 покрывает
    // переподключения ядра и добавленные списки. Настройка: pac.sub_rate_max_rs
    // (0 = выкл; sub_rate_max=0 это ведро НЕ выключает — ключи независимы).
    public function subRateLimit($sid, $scope = '')
    {
        $pac    = $this->getPacConf();
        $max    = $scope === 'rs'
            ? (int) ($pac['sub_rate_max_rs'] ?? 240)
            : (int) ($pac['sub_rate_max'] ?? 30);
        $window = (int) ($pac['sub_rate_window'] ?? 300);
        if ($max <= 0 || $window <= 0) {
            return;
        }
        // За nginx REMOTE_ADDR — адрес прокси; XFF ставит наш же nginx.
        // Спуфабельность XFF здесь не критична: ключ содержит и sid, так что
        // лимит на конкретную подписку обойти сменой заголовка нельзя.
        $ip  = trim(explode(',', (string) ($_SERVER['HTTP_X_FORWARDED_FOR'] ?? ''))[0]) ?: (string) ($_SERVER['REMOTE_ADDR'] ?? '');
        $key = substr(hash('sha256', "$sid|$ip|$scope"), 0, 16);
        $f   = '/logs/sub_ratelimit.json';
        $h   = @fopen($f, 'c+');
        if ($h === false) {
            return; // лимитер вспомогательный: не роняем выдачу подписки
        }
        $over = false;
        if (flock($h, LOCK_EX)) {
            $data = json_decode((string) stream_get_contents($h), true) ?: [];
            $now  = time();
            foreach ($data as $k => $v) {
                if (!is_array($v) || ($v[1] ?? 0) + $window < $now) {
                    unset($data[$k]);
                }
            }
            $data[$key] = [($data[$key][0] ?? 0) + 1, $data[$key][1] ?? $now];
            $over = $data[$key][0] > $max;
            ftruncate($h, 0);
            rewind($h);
            fwrite($h, json_encode($data));
            flock($h, LOCK_UN);
        }
        fclose($h);
        if ($over) {
            $this->subSecurityHeaders();
            http_response_code(429);
            header('Retry-After: ' . $window);
            header('Content-Type: text/plain; charset=utf-8');
            echo 'Too Many Requests';
            exit;
        }
    }

    // A missing/disabled/expired subscription must not look like a server crash:
    // return a clean 404 with a short description so the client shows "not found"
    // instead of treating a 500 as a transient error and hammering retries.
    public function subNotFound($reason = 'Subscription not found or disabled.')
    {
        $this->subSecurityHeaders();
        http_response_code(404);
        header('Content-Type: text/html; charset=utf-8');
        $reason = htmlspecialchars($reason, ENT_QUOTES, 'UTF-8');
        echo "<!doctype html><meta charset=\"utf-8\"><title>404 Not Found</title>"
            . "<h1>404 Not Found</h1><p>$reason</p>";
        exit;
    }

    public function getAwgClient($pk)
    {
        $c   = $this->getPacConf();
        $wg  = json_decode(file_get_contents($this->clients), true) ?: [];
        $wg1 = json_decode(file_get_contents($this->clients1), true) ?: [];
        foreach ($wg as $k => $v) {
            if ($v['interface']['PrivateKey'] == $pk) {
                $container = '';
                $cl = $v;
                break;
            }
        }
        foreach ($wg1 as $k => $v) {
            if ($v['interface']['PrivateKey'] == $pk) {
                $container = 'wg1_';
                $cl = $v;
                break;
            }
        }

        if (empty($cl)) {
            return false;
        }

        return [
            // Блок 3.0 уезжает в mihomo только при включённом тумблере
            // mihomo_awg3: его понимают лишь свежие сборки, а нужные ИМЕНА
            // полей у mihomo свои (см. MIHOMO_AWG3_KEYS).
            // Набор прогоняем через amneziaKeysUsable() — тот же срез, что
            // уходит в wg0.conf: иначе подписка объявила бы клиенту header
            // protection, которого на сервере нет, и handshake молча не прошёл
            // бы. Версию tools берём из кеша: ssh на пути подписки нельзя.
            "amnezia-wg-option" => self::amneziaKeysForMihomo(
                self::amneziaKeysUsable(
                    $c["{$container}amnezia_keys"] ?? '',
                    $this->awgSupports3Cached($container)
                ),
                !empty($c['mihomo_awg3'])
            ),
            "pre-shared-key"    => $c["{$container}presharedkey"] ?? '',
            // Диапазон приводится к числу уже на месте сборки прокси
            // (keepaliveInt): ssh сюда звать нельзя — это путь подписки.
            "persistent-keepalive" => $c["{$container}amnezia_keepalive"] ?? 20,
            "server"            => explode(':', $cl['peers'][0]['Endpoint'])[0],
            "port"              => explode(':', $cl['peers'][0]['Endpoint'])[1],
            "ip"                => explode('/', $cl['interface']['Address'])[0],
            "private-key"       => $cl['interface']['PrivateKey'],
            "public-key"        => $cl['peers'][0]['PublicKey'],
            "mtu"               => $c["{$container}mtu"] ?? $this->mtu,
        ];
    }

    public function addClashRuleSet($c)
    {
        $p = $this->getPacConf();
        if (!empty($p['rulessetlist']) && $c['add-rule-providers']) {
            foreach ($p['rulessetlist'] as $k => $v) {
                if (!empty($v)) {
                    [$type, $behavior, $time, $url] = explode(':', $k, 4);
                    if (preg_match('~\.(mrs|yaml|yml)$~', $url, $m)) {
                        $c['rule-providers'][$url] = [
                            'type'     => 'http',
                            'url'      => $url,
                            'interval' => (int) $time,
                            'behavior' => $behavior,
                            'format'   => $m[1],
                        ];
                        switch ($type) {
                            case 'reject':
                            case 'REJECT':
                                array_unshift($c['rules'], [
                                    'RULE-SET', $url, strtoupper($type)
                                ]);
                                break;

                            default:
                                array_splice($c['rules'], count($c['rules']) - 1, 0, [[
                                    'RULE-SET', $url, strtoupper($type)
                                ]]);
                                break;
                        }
                    }
                }
            }
        }
        unset($c['add-rule-providers']);
        if (empty($c['rule-providers'])) {
            unset($c['rule-providers']);
        }
        return $c;
    }

    public function clashRules($c, $uid, $domain)
    {
        $scheme = empty($this->nginxGetTypeCert()) ? 'http' : 'https';
        $hash   = $this->getHashBot();
        foreach ($c['rules'] as $v) {
            if (array_key_exists('list', $v)) {
                if ($v['type'] == 'RULE-SET') {
                    if (!empty($_GET['r']) && $v['name'] == $_GET['r']) {
                        header("Content-Disposition: attachment; filename={$v['name']}.yaml");
                        header('Content-Type: text/yaml');
                        switch ($v['name']) {
                            case 'process':
                            case 'package':
                                echo yaml_emit(['payload' => array_map(fn($e) => "PROCESS-NAME,$e", $v['list'])]);
                                break;

                            default:
                                echo yaml_emit(['payload' => array_values(array_filter(array_map(function($e) {
                                    $cl = $this->classifyRouteEntry($e);
                                    if (!$this->routeEntryUsable($cl)) {
                                        return null; // пустое значение / битый IP
                                    }
                                    switch ($cl['kind']) {
                                        case 'ext':   // xray-only .dat — mihomo не понимает
                                        case 'extip':
                                        case 'geosite': // встроенные категории xray —
                                        case 'geoip':   // у mihomo своя geodata, токен чужой
                                            return null;
                                        case 'ip':
                                            $v = $this->ipWithCidr($cl['value']);
                                            // mihomo/Clash: IPv6 требует правило IP-CIDR6.
                                            return (str_contains($v, ':') ? 'IP-CIDR6,' : 'IP-CIDR,') . $v;
                                        case 'regexp':
                                            return "DOMAIN-REGEX,{$cl['value']}";
                                        case 'keyword':
                                            return "DOMAIN-KEYWORD,{$cl['value']}";
                                        case 'full':
                                            return "DOMAIN,{$cl['value']}";
                                        default: // domain, suffix
                                            return "DOMAIN-SUFFIX,{$cl['value']}";
                                    }
                                }, $v['list']), fn($r) => $r !== null))]);
                                break;

                        }
                        exit;
                    }
                    $c['rule-providers'][$v['name']] = [
                        'type'     => 'http',
                        'url'      => "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
                            'h' => $hash,
                            't' => 'cl',
                            's' => $uid,
                            'r' => $v['name'],
                        ])),
                        'interval' => $v['interval'],
                        'behavior' => $v['behavior'],
                        'format'   => 'yaml',
                    ];
                    $tmp[] = "{$v['type']}, {$v['name']}, {$v['action']}";
                } else {
                    if (!empty($v['list'])) {
                        foreach ($v['list'] as $j) {
                            $tmp[] = "{$v['type']}, $j, {$v['action']}";
                        }
                    }
                }
            } else {
                $tmp[] = implode(', ', $v);
            }
        }
        $c['rules'] = $tmp;
        return $c;
    }

    /**
     * Parse the server's Cloudflare WARP wgcf profile (/etc/warp/wgcf-profile.conf,
     * IPv6 already stripped by start_wp.sh) into the fields a mihomo wireguard
     * proxy needs. Returns false when the profile is missing/unreadable so callers
     * can fall back gracefully.
     */
    public function getWarpProfile()
    {
        // Cache per request: this runs on every config download (all types), and
        // when the profile is absent the ssh fallback below would otherwise fire
        // each time. null = not loaded yet; false/array = resolved result.
        if ($this->warpprofile !== null) {
            return $this->warpprofile;
        }
        $conf = @file_get_contents('/etc/warp/wgcf-profile.conf');
        if (empty($conf)) {
            // /etc/warp is mounted into this container, but fall back to the wp
            // container over ssh just in case the volume isn't present.
            $conf = $this->ssh('cat /etc/warp/wgcf-profile.conf 2>/dev/null', 'wp');
        }
        if (empty($conf) || !str_contains($conf, '[Peer]')) {
            return $this->warpprofile = false;
        }
        $val = function ($key) use ($conf) {
            return preg_match('~^\s*' . $key . '\s*=\s*(.+?)\s*$~mi', $conf, $m) ? trim($m[1]) : null;
        };
        $endpoint   = $val('Endpoint');
        $privateKey = $val('PrivateKey');
        $publicKey  = $val('PublicKey');
        $address    = $val('Address');
        if (empty($endpoint) || empty($privateKey) || empty($publicKey) || empty($address)) {
            return $this->warpprofile = false;
        }
        // endpoint is host:port, but tolerate an IPv6 literal like [2606:..]:2408
        if (preg_match('~^\[(.+)\]:(\d+)$~', $endpoint, $em)) {
            $server = $em[1];
            $port   = (int) $em[2];
        } else {
            $pos    = strrpos($endpoint, ':');
            $server = substr($endpoint, 0, $pos);
            $port   = (int) substr($endpoint, $pos + 1);
        }
        return $this->warpprofile = [
            'server'      => $server,
            'port'        => $port,
            'ip'          => explode('/', $address)[0],
            'private-key' => $privateKey,
            'public-key'  => $publicKey,
            'mtu'         => (int) ($val('MTU') ?: 1280),
        ];
    }

    public function replaceTags($subject, $tags)
    {
        $keys = [];
        $vals = [];
        foreach ($tags as $k => $v) {
            $keys[] = $k;
            // Ключи вида "~pac~" (вместе с кавычками) заменяют JSON-значение
            // целиком — их подставляем как есть. Голые ~outbound~/~domain~ стоят
            // ВНУТРИ строкового литерала уже сериализованного JSON, поэтому
            // значение надо экранировать по правилам JSON: одна кавычка в имени
            // аутбаунда (setMainOutbound принимает любой текст из Telegram) рвала
            // документ, json_decode возвращал null, и подписки у ВСЕХ клиентов
            // молча отдавали пустое тело с HTTP 200.
            $raw    = strlen($k) > 1 && '"' === $k[0] && '"' === $k[strlen($k) - 1];
            $vals[] = $raw
                ? $v
                // substr, а не trim: значение может само оканчиваться на \" —
                // trim('"') съел бы и экранированную кавычку.
                : substr(json_encode((string) $v, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), 1, -1);
        }
        return str_replace($keys, $vals, $subject);
    }

    public function addRuleSet($route)
    {
        if (!empty($route['rules'])) {
            foreach ($route['rules'] as $k => $v) {
                if (!empty($v['addruleset'])) {
                    $ob      = ($v['outbound'] ?? '') ?: 'block';
                    $t[$ob]  = $k;
                    // Имя основного аутбаунда несёт флаг-префикс страны
                    // ("🇫🇷 proxy" через flagName/~outbound~), а ключ rulessetlist
                    // использует логическое имя ("proxy"). Регистрируем и его,
                    // иначе isset($t[$type]) не срабатывает и proxy:-теги теряются.
                    $base = preg_replace('~^[\x{1F1E6}-\x{1F1FF}]+\s+~u', '', $ob);
                    if ($base !== '' && $base !== $ob) {
                        $t[$base] = $k;
                    }
                }
            }
            $p = $this->getPacConf();
            if (!empty($p['rulessetlist'])) {
                foreach ($p['rulessetlist'] as $k => $v) {
                    if (!empty($v)) {
                        // Ключ rulessetlist для sing-box (.srs): type:time:url — без behavior
                        // (behavior есть только у Clash/mihomo .mrs/.yaml в addClashRuleSet).
                        [$type, $time, $url] = explode(':', $k, 3);
                        if (isset($t[$type]) && preg_match('~\.srs$~', $url) && !empty($route['rules'][$t[$type]])) {
                            $route['rule_set'][] = [
                                "tag"             => $k,
                                "type"            => "remote",
                                "format"          => "binary",
                                "url"             => $url,
                                "download_detour" => "direct",
                                "update_interval" => $time
                            ];
                            $route['rules'][$t[$type]]['rule_set'][] = $k;
                        }
                    }
                }
            }
            foreach ($route['rules'] as $k => $v) {
                unset($route['rules'][$k]['addruleset']);
            }
        }
        return $route;
    }

    // Удаляет из dns.rules/route.rules ссылки на rule_set, для которых нет
    // определения в route.rule_set. sing-box отвергает конфиг целиком при
    // ссылке на несуществующий rule-set ("rule-set not found"); лучше тихо
    // пропустить незарегистрированный набор, чем сломать импорт.
    public function pruneRuleSetRefs($c)
    {
        $defined = array_flip(array_column($c['route']['rule_set'] ?? [], 'tag'));
        foreach (['dns', 'route'] as $sec) {
            if (empty($c[$sec]['rules'])) {
                continue;
            }
            foreach ($c[$sec]['rules'] as $k => $v) {
                if (!array_key_exists('rule_set', $v)) {
                    continue;
                }
                $kept = array_values(array_filter(
                    (array) $v['rule_set'],
                    fn($tag) => isset($defined[$tag])
                ));
                if (empty($kept)) {
                    // Все ссылки висячие — правило было rule_set-селектором;
                    // удаляем целиком, иначе останется условие-без-условия,
                    // матчащее весь трафик.
                    unset($c[$sec]['rules'][$k]);
                } else {
                    $c[$sec]['rules'][$k]['rule_set'] = $kept;
                }
            }
            $c[$sec]['rules'] = array_values($c[$sec]['rules']);
        }
        return $c;
    }

    public function cleanEmptyKeys(array $arr)
    {
        foreach ($arr as $k => $v) {
            if (empty($v)) {
                unset($arr[$k]);
            } elseif (is_array($v)) {
                $arr[$k] = $this->cleanEmptyKeys($v);
                if (empty($arr[$k])) {
                    unset($arr[$k]);
                }
            }
        }
        return $arr;
    }

    public function createSrs(string $name, array $rules)
    {
        $rules = $this->cleanEmptyKeys($rules);
        header("Content-Disposition: attachment; filename=$name.srs");
        header('Content-Type: application/binary');
        $f = "/tmp/$name" . time() . rand(1, 100);
        foreach ($rules as $k => $v) {
            if (array_key_exists('domain_suffix', $v)) {
                // Раскладываем записи по полям sing-box rule-set с учётом префиксов
                // маршрутизации. Порядок ключей задаёт форму итогового правила.
                $buckets = [
                    'domain_regex'   => [],
                    'domain_keyword' => [],
                    'domain'         => [], // exact-match (full:)
                    'domain_suffix'  => [],
                    'ip_cidr'        => [],
                ];
                foreach ($v['domain_suffix'] as $j) {
                    $cl = $this->classifyRouteEntry($j);
                    if (!$this->routeEntryUsable($cl)) {
                        continue; // пустое значение / битый IP
                    }
                    switch ($cl['kind']) {
                        case 'ext':   // xray-only .dat — sing-box не понимает, пропускаем
                        case 'extip':
                        case 'geosite': // встроенные категории xray: в sing-box их роль
                        case 'geoip':   // играют rule-set'ы, голый токен невалиден
                            continue 2;
                        case 'ip':
                            $buckets['ip_cidr'][] = $this->ipWithCidr($cl['value']);
                            break;
                        case 'regexp':
                            $buckets['domain_regex'][] = $cl['value'];
                            break;
                        case 'keyword':
                            $buckets['domain_keyword'][] = $cl['value'];
                            break;
                        case 'full':
                            $buckets['domain'][] = $cl['value'];
                            break;
                        default: // domain, suffix
                            $buckets['domain_suffix'][] = $cl['value'];
                            break;
                    }
                }
                unset($rules[$k]['domain_suffix']);
                foreach ($buckets as $field => $vals) {
                    if (!empty($vals)) {
                        $rules[$k][$field] = $vals;
                    }
                }
            }
            // Нормализуем ip_cidr: ~subnet~ шаблон кладёт записи напрямую в это
            // поле (минуя domain_suffix-бакетизацию выше). sing-box принимает и
            // голый IP (неявно /32 или /128), но приводим к явной маске ради
            // паритета с xray/mihomo. Идемпотентно: запись с /prefix не трогаем.
            if (!empty($rules[$k]['ip_cidr'])) {
                $rules[$k]['ip_cidr'] = array_map(
                    fn($ip) => $this->ipWithCidr($ip),
                    $rules[$k]['ip_cidr'],
                );
            }
        }
        file_put_contents($f, json_encode([
            'version' => 1,
            'rules'   => $rules ?: [],
        ]));
        exec("sing-box rule-set compile $f");
        echo file_get_contents("$f.srs");
        unlink($f);
        unlink("$f.srs");
        exit;
    }

    public function createRuleSet($route, $uid, $domain)
    {
        $scheme = empty($this->nginxGetTypeCert()) ? 'http' : 'https';
        $hash   = $this->getHashBot();

        foreach ($route['rules'] as $k => $v) {
            if (!empty($v['createruleset'])) {
                foreach ($v['createruleset'] as $r) {
                    if (!empty($_GET['r']) && $r['name'] == $_GET['r']) {
                        $this->createSrs($r['name'], $r['rules']);
                    }
                    $ruleset[] = [
                        "tag"             => $r['name'],
                        "url"             => "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
                            'h' => $hash,
                            't' => 'si',
                            's' => $uid,
                            'r' => $r['name'],
                        ])),
                        "update_interval" => $r['interval'],
                        "type"            => "remote",
                        "format"          => "binary",
                        "download_detour" => "direct",
                    ];
                    $route['rules'][$k]['rule_set'][] = $r['name'];
                }
                unset($route['rules'][$k]['createruleset']);
                if (empty($route['rules'][$k]['rule_set'])) {
                    unset($route['rules'][$k]);
                }
            }
        }
        if (!empty($route['rules'])) {
            $route['rules']    = array_values($route['rules']);
        }
        $route['rule_set'] = array_merge($route['rule_set'] ?: [], $ruleset ?: []);
        if (empty($route['rule_set'])) {
            unset($route['rule_set']);
        }
        return $route;
    }

    public function getXray()
    {
        return json_decode(file_get_contents('/config/xray.json'), true);
    }

    /** Валидный хостнейм — единственное, что можно пускать в nginx-конфиг. */
    public function isHostname($d): bool
    {
        return (bool) preg_match('~^[a-zA-Z0-9]([a-zA-Z0-9.-]*[a-zA-Z0-9])?$~', (string) $d);
    }

    public function setUpstreamDomain($domain)
    {
        // $domain правится из Telegram (reality.domain/serverNames) и попадает в
        // replacement preg_replace, где «$1»/«\1» — обратные ссылки, а затем в
        // конфиг nginx. Битый конфиг `nginx -s reload` не применит, поэтому
        // поломка всплыла бы только при следующем рестарте контейнера — 443 не
        // поднимется и весь внешний доступ ляжет.
        if (!$this->isHostname($domain)) {
            return;
        }
        $nginx = file_get_contents('/config/upstream.conf');
        $t = preg_replace('~#domain.+#domain~s', "#domain\n$domain reality;\n#domain", $nginx);
        file_put_contents('/config/upstream.conf', $t);
        $this->ssh("nginx -s reload 2>&1", 'up');
    }

    public function setUpstreamDomainOcserv($domain)
    {
        // Пустая строка — штатный «сброс» (см. вызов при удалении домена),
        // остальное обязано быть хостнеймом: см. комментарий в setUpstreamDomain.
        if ('' !== (string) $domain && !$this->isHostname($domain)) {
            return;
        }
        $sub   = $this->getHashSubdomain('oc');
        $nginx = file_get_contents('/config/upstream.conf');
        $t     = preg_replace('~#ocserv.+#ocserv~s', $domain ? "#ocserv\n" . ($sub ? '' : '#' ) . "$sub.$domain ocserv;\n#ocserv" : "#ocserv\n#$sub.\$domain ocserv;\n#ocserv", $nginx);
        file_put_contents('/config/upstream.conf', $t);
        $this->ssh("nginx -s reload 2>&1", 'up');
    }

    public function setUpstreamDomainNaive($domain)
    {
        // См. setUpstreamDomainOcserv: пустая строка допустима, мусор — нет.
        if ('' !== (string) $domain && !$this->isHostname($domain)) {
            return;
        }
        $sub   = $this->getHashSubdomain('np');
        $nginx = file_get_contents('/config/upstream.conf');
        $t = preg_replace('~#naive.+#naive~s', $domain ? "#naive\n" . ($sub ? '' : '#' ) . "$sub.$domain naive;\n#naive" : "#naive\n#$sub.\$domain naive;\n#naive", $nginx);
        file_put_contents('/config/upstream.conf', $t);
        $this->ssh("nginx -s reload 2>&1", 'up');
    }

    public function getHashBot($notset = false)
    {
        $p = $this->getPacConf();
        if (!empty($p['hashbot'])) {
            return $p['hashbot'];
        }
        $p['hashbot'] = substr(hash('sha256', $this->key), 0, 8);
        if (empty($notset)) {
            $this->setPacConf($p);
        }
        return $p['hashbot'];
    }

    public function cloakNginx()
    {
        $conf     = $this->getPacConf();
        $template = file_get_contents('/config/nginx_default.conf');
        // $template = preg_replace('~server_name ip~', "server_name {$this->ip}", $template);
        // Алиасы принимаем тем же server-блоком: серт после «renew SSL» их
        // покрывает, upstream шлёт их сюда через `default other`.
        $aliasNames = '';
        foreach ($conf['domain_aliases'] ?? [] as $a) {
            $aliasNames .= " *.$a $a";
        }
        $template = preg_replace('~server_name domain~', "server_name " . ($conf['domain'] ? " *.{$conf['domain']} {$conf['domain']}$aliasNames" : '_'), $template);
        if ($conf['domain'] && $conf['letsencrypt']) {
            $template = preg_replace('/#~([^\n]+)?/', "#~{$conf['letsencrypt']}", $template);
            preg_match_all('~#-domain.+?#-domain~s', $template, $m);
            foreach ($m[0] as $v) {
                $template = preg_replace('~#-domain.+?#-domain~s', $this->uncomment($v, 'domain'), $template, 1);
            }
        }
        $h = $this->getHashBot();
        $s = empty($conf['adgbrowser']) ? '' : '#';
        $r = <<<CONF
        location /adguard/ {
                access_log /logs/nginx_adguard_access;
                if (\$cookie_c != "$h") {
                    $s rewrite .* /webapp redirect;
                }
                proxy_pass http://ad/;
                proxy_redirect / /adguard/;
                proxy_cookie_path / /adguard/;
            }
            location
        CONF;
        $template = preg_replace('~(location /adguard.+?})\s*location~s', $r, $template);
        $template = preg_replace('~(/webapp|/pac|/adguard|/ws|/grpc|/v2ray|location /dns-query)~', '${1}' . $h, $template);
        file_put_contents('/config/nginx.conf', $template);
        $x = $this->getXray();
        if (!empty($x['inbounds'][0]['streamSettings']['wsSettings']['path'])) {
            $x['inbounds'][0]['streamSettings']['wsSettings']['path'] = "/ws$h";
            $this->restartXray($x);
        }
        if (!empty($x['inbounds'][0]['streamSettings']['xhttpSettings']['path'])) {
            $x['inbounds'][0]['streamSettings']['xhttpSettings']['path'] = "/ws$h";
            $this->restartXray($x);
        }
        if (!empty($x['inbounds'][0]['streamSettings']['grpcSettings']['serviceName'])) {
            $x['inbounds'][0]['streamSettings']['grpcSettings']['serviceName'] = "grpc$h";
            $this->restartXray($x);
        }

        return $this->ssh('nginx -s reload', 'ng');
    }

    public function getHashSubdomain($subdomain)
    {
        $p = $this->getPacConf();
        if (isset($p["{$subdomain}_domain"])) {
            return $p["{$subdomain}_domain"];
        }
        $p["{$subdomain}_domain"] = substr(hash('sha256', "$subdomain{$this->key}"), 0, 8);
        $this->setPacConf($p);
        return $p["{$subdomain}_domain"];
    }

