    public function setFakeDomain($domain, $self = false)
    {
        $c = $this->getXray();
        $p = $this->getPacConf();
        $c['inbounds'][0]['streamSettings']['realitySettings']['serverNames'][0] = $domain;
        $c['inbounds'][0]['streamSettings']['realitySettings']['dest'] = $self ? "10.10.1.2:443" : "$domain:443";
        $p['reality']['domain'] = $domain;
        $p['reality']['destination'] = $self ? "10.10.1.2:443" : "$domain:443";
        $this->setPacConf($p);
        $this->restartXray($c);
        $this->setUpstreamDomain($domain);
        $this->xray();
    }

    public function selfFakeDomain()
    {
        $c = $this->getPacConf();
        if (!empty($c['domain'])) {
            $this->setFakeDomain($c['domain'], 1);
        } else{
            $this->answer($this->input['callback_id'], 'empty domain', true);
        }
    }

    public function changeTransport($transport)
    {
        $p = $this->getPacConf();
        $x = $this->getXray();
        $h = $this->getHashBot();

        $p['reality']['domain']      = $p['reality']['domain'] ?: 'yandex.ru';
        $p['reality']['destination'] = $p['reality']['destination'] ?: $p['reality']['domain'] . ':443';
        $p['transport'] = $transport;

        $p['reality']['domain']      = $x['inbounds'][0]['streamSettings']['realitySettings']['serverNames'][0] ?? $p['reality']['domain'];
        $p['reality']['destination'] = $x['inbounds'][0]['streamSettings']['realitySettings']['dest'] ?? $p['reality']['destination'];
        $p['reality']['shortId']     = $x['inbounds'][0]['streamSettings']['realitySettings']['shortIds'][0] ?? $p['reality']['shortId'];

        if (empty($p['xray'])) {
            $shortId = trim($this->ssh('openssl rand -hex 8', 'xr'));
            $keys    = $this->ssh('xray x25519', 'xr');
            preg_match('~^PrivateKey:\s([^\s]+)~m', $keys, $m);
            $private = trim($m[1]);
            preg_match('~^Password(?:\s*\(PublicKey\))?:\s([^\s]+)~m', $keys, $m);
            $public = trim($m[1]);
            $p['xray'] = $public;
            $p['reality']['shortId']    = $shortId;
            $p['reality']['privateKey'] = $private;
        }


        $x['inbounds'][0]['protocol'] = 'vless';

        switch ($transport) {
            case 'xhttp':
                foreach ($x['inbounds'][0]['settings']['clients'] as $k => $v) {
                    unset($x['inbounds'][0]['settings']['clients'][$k]['flow']);
                }
                // TLS терминирует nginx, поэтому у inbound'а нет ни security, ни
                // tlsSettings — xray слушает голый H1/H2C на xr:443.
                // mode=auto на сервере означает «принимаю любой режим», клиент
                // выбирает сам (у нас — packet-up, см. xhttpClientExtra()).
                // Всё, кроме host/path/mode, обязано лежать в extra: при заданном
                // extra xray заменяет им внешний объект целиком.
                //
                // noSSEHeader НЕ ставим. true убирает у даунлинка заголовок
                // Content-Type: text/event-stream — а он тут работает и как
                // маскировка (поток выглядит обычным SSE), и как сигнал
                // промежуточным прокси/CDN не буферизовать ответ. Буферизация у
                // нас и так снята дважды: xray сам шлёт X-Accel-Buffering: no
                // (hub.go), а в локации /ws стоит proxy_buffering off. Дефолт
                // xray — false.
                $x['inbounds'][0]['streamSettings'] = [
                    "network"       => "xhttp",
                    "xhttpSettings" => [
                        "mode"  => "auto",
                        "path"  => "/ws$h",
                        "extra" => [
                            "xPaddingBytes"        => "100-1000",
                            "scMaxBufferedPosts"   => 30,
                            "scMaxEachPostBytes"   => 1000000,
                            "scStreamUpServerSecs" => "20-80"
                        ]
                    ],
                    // Реальный IP клиента вместо адреса nginx, см. nginxFrontedSockopt().
                    "sockopt" => $this->nginxFrontedSockopt(),
                ];
                break;

            case 'trojan-grpc':
                $x['inbounds'][0]['protocol'] = 'trojan';
                foreach ($x['inbounds'][0]['settings']['clients'] as $k => $v) {
                    unset($x['inbounds'][0]['settings']['clients'][$k]['flow']);
                    $x['inbounds'][0]['settings']['clients'][$k]['password'] = $v['password'] ?? bin2hex(random_bytes(16));
                }
                $x['inbounds'][0]['streamSettings'] = [
                    "network"      => "grpc",
                    "grpcSettings" => [
                        "serviceName" => "grpc$h",
                    ],
                    "sockopt" => $this->nginxFrontedSockopt(),
                ];
                break;

            case 'Reality':
                foreach ($x['inbounds'][0]['settings']['clients'] as $k => $v) {
                    $x['inbounds'][0]['settings']['clients'][$k]['flow'] = 'xtls-rprx-vision';
                }
                $x['inbounds'][0]['streamSettings'] = [
                    "network"         => "tcp",
                    "realitySettings" => [
                        "dest"         => $p['reality']['destination'] ?: $x['inbounds'][0]['streamSettings']['realitySettings']['dest'],
                        "maxClientVer" => "",
                        "maxTimeDiff"  => 0,
                        "minClientVer" => "0.0.0",
                        "privateKey"   => $p['reality']['privateKey'],
                        "serverNames"  => [
                            $p['reality']['domain'] ?: $x['inbounds'][0]['streamSettings']['realitySettings']['serverNames'][0]
                        ],
                        "shortIds" => [$p['reality']['shortId'] ?: $x['inbounds'][0]['streamSettings']['realitySettings']['shortIds'][0]],
                        "show"     => false,
                        "xver"     => 0
                    ],
                    "tcpSettings" => [
                        "acceptProxyProtocol" => true
                    ],
                    "sockopt" => [
                        "acceptProxyProtocol" => true
                    ],
                    "security" => "reality"
                ];
                break;

            default:
                $x['inbounds'][0]['streamSettings'] = [
                    "network"    => "ws",
                    "wsSettings" => [
                        "path" => "/ws$h"
                    ],
                    // Websocket делит с xhttp ту же локацию /ws у nginx и ту же
                    // проблему с подменой источника, см. nginxFrontedSockopt().
                    "sockopt" => $this->nginxFrontedSockopt(),
                ];
                foreach ($x['inbounds'][0]['settings']['clients'] as $k => $v) {
                    unset($x['inbounds'][0]['settings']['clients'][$k]['flow']);
                }
                break;
        }

        // Apply configurable Reality extras (item 2 mldsa seed + item 4 hardening
        // params) to whichever transport built a realitySettings block.
        if (!empty($x['inbounds'][0]['streamSettings']['realitySettings'])) {
            $this->applyRealityServerExtras($x['inbounds'][0]['streamSettings']['realitySettings'], $p);
        }

        $this->setUpstreamDomain($transport == 'Reality'
            ? ($p['reality']['domain'] ?: $x['inbounds'][0]['streamSettings']['realitySettings']['serverNames'][0])
            : 't'
        );
        $this->setPacConf($p);
        $this->restartXray($x);
        $this->xray();
    }

    public function setBackup($text)
    {
        $text = trim($text);
        $c    = $this->getPacConf();
        if (empty($text)) {
            $c['backup'] = '';
        } else {
            [$start, $period] = explode('/', $text);
            if (!empty(strtotime($start)) && !empty(strtotime($period))) {
                $c['backup'] = implode(' / ', [date('Y-m-d H:i', strtotime($start)), trim($period)]);
            } else {
                $this->send($this->input['from'], $this->input['message'] . ' - wrong format');
            }
        }
        if ($c['pinbackup']) {
            $this->pinAdmin($c['pinbackup'], 1);
            $c['pinbackup'] = '';
        }
        $this->setPacConf($c);
        $this->menu('config');
    }

    public function setAutoCleanLogs($text)
    {
        $text = trim($text);
        $c    = $this->getPacConf();
        if (empty($text)) {
            $c['autocleanlogs'] = '';
        } else {
            [$start, $period] = explode('/', $text);
            if (!empty(strtotime($start)) && !empty(strtotime($period))) {
                $c['autocleanlogs'] = implode(' / ', [date('Y-m-d H:i', strtotime($start)), trim($period)]);
            } else {
                $this->send($this->input['from'], $this->input['message'] . ' - wrong format');
            }
        }
        $this->setPacConf($c);
        $this->logs();
    }

    public function debug()
    {
        $file = __DIR__ . '/config.php';
        require $file;
        $c['debug'] = !$c['debug'];
        file_put_contents($file, "<?php\n\n\$c = " . var_export($c, true) . ";\n");
        $this->menu('config');
    }

    public function getStatusPeer(string $publickey, array $peers)
    {
        foreach ($peers as $k => $v) {
            if ($v['peer'] == $publickey) {
                return $v;
            }
        }
    }

    public function getInstanceWG($k = false)
    {
        // ?? 0 — на свежей установке pac.json = {} и ключа wg_instance нет;
        // без фолбэка каждый вызов сыпал бы «Undefined array key».
        if (!empty($k)) {
            return ($this->wg ?? $this->getPacConf()['wg_instance'] ?? 0) ? 'wg1_' : '';
        }
        return ($this->wg ?? $this->getPacConf()['wg_instance'] ?? 0) ? 'wg1' : 'wg';
    }

    public function readConfig()
    {
        $r = $this->ssh('cat /etc/wireguard/wg0.conf', $this->getInstanceWG());
        $r = explode(PHP_EOL, $r);
        $r = array_filter($r);
        // Инициализация: при недоступном контейнере ssh() отдаёт "", цикл ниже
        // не выполняется ни разу и foreach по $data сыпал «Undefined variable».
        // Возврат null сохранён — вызывающий код на него уже рассчитывает.
        $data = [];
        $d    = null;
        $i = 0;
        foreach ($r as $k => $v) {
            if (preg_match('~\[(.+)\]~', $v, $m)) {
                $i++;
                if ($m[1] == 'Interface') {
                    $data[$i]['type'] = 'interface';
                } else {
                    $data[$i]['type'] = 'peer';
                }
            } else {
                $t = explode('=', $v, 2);
                $data[$i][trim($t[0])] = trim($t[1]);
            }
        }
        foreach ($data as $v) {
            $type = $v['type'];
            unset($v['type']);
            if ($type == 'interface') {
                $d['interface'] = $v;
            } else {
                $d['peers'][] = $v;
            }
        }
        return $d;
    }

    public function nginxGetTypeCert()
    {
        $conf = $this->ssh('cat /etc/nginx/nginx.conf', 'ng');
        preg_match("/#~([^\s]+)/", $conf, $m);
        return $m[1] ?? '';
    }

    public function readStatus()
    {
        $r = $this->ssh($this->getWGType(), $this->getInstanceWG());
        $r = explode(PHP_EOL, $r);
        $r = array_filter($r);
        $i = 0;
        foreach ($r as $k => $v) {
            if (preg_match('~^(interface|peer):~', $v, $m)) {
                $i++;
                if ($m[1] == 'interface') {
                    $data[$i]['type'] = 'interface';
                } else {
                    $data[$i]['type'] = 'peer';
                }
            }
            $t = explode(':', $v, 2);
            $data[$i][trim($t[0])] = trim($t[1]);
        }
        foreach ($data as $v) {
            $type = $v['type'];
            unset($v['type']);
            if ($type == 'interface') {
                $d['interface'] = $v;
            } else {
                $d['peers'][] = $v;
            }
        }
        return $d;
    }

    public function getName(array $a): string
    {
        $name = '';
        foreach ($a as $k => $v) {
            if (preg_match('~^#.*name$~', $k)) {
                $name = $v;
            }
        }
        $name = $name ?: $a['AllowedIPs'] ?: $a['Address'];
        return $name;
    }

    // Выбранный relay для генерируемых wg/awg-конфигов текущего инстанса
    // (pacconf '{inst}relay' — имя из $pac['relays']). Возвращает запись relay
    // с awg_address или null (не выбран / удалён / адрес снят) — тогда конфиги
    // идут напрямую. Reuse awg_address/awg_portmap: это тот же wg/awg-канал
    // relay, что применяет applyAwgRelay к 'awg'-прокси в mihomo.
    public function wgRelay(): ?array
    {
        $c    = $this->getPacConf();
        $name = (string) ($c[$this->getInstanceWG(1) . 'relay'] ?? '');
        if ($name === '') {
            return null;
        }
        $r = $c['relays'][$name] ?? null;
        return (is_array($r) && !empty($r['awg_address'])) ? $r : null;
    }

    public function createConfig($data)
    {
        $pac = $this->getPacConf();
        $conf[] = "[Interface]";
        if (empty($data['interface']['ListenPort'])) {
            if (empty($data['interface']['DNS'])) {
                $data['interface']['DNS'] = $pac[$this->getInstanceWG(1) . 'dns'] ?: $this->dns;
            }
            if (empty($data['interface']['MTU'])) {
                $data['interface']['MTU'] = $pac[$this->getInstanceWG(1) . 'mtu'] ?: $this->mtu;
            }
        }
        foreach ($data['interface'] as $k => $v) {
            $conf[] = "$k = $v";
        }
        $ports = $this->getPorts();
        // Relay инстанса (если выбран в wg-меню): Endpoint подменяется на
        // адрес relay для WG/AWG, порт — через awg_portmap (как applyAwgRelay).
        // Ключи/DNS/AllowedIPs не трогаем — WG-туннель терминируется на origin.
        $relay = $this->wgRelay();
        if (!empty($data['peers'])) {
            foreach ($data['peers'] as $peer) {
                $conf[] = '';
                $conf[] = $peer['# PublicKey'] ? '# [Peer]' : '[Peer]';
                if (!empty($peer['Endpoint'])) {
                    $host = $pac[$this->getInstanceWG(1) . 'endpoint'] ? $this->ip : $this->getDomain();
                    $port = $ports[$this->getInstanceWG()]['port'];
                    if ($relay !== null) {
                        $host = $relay['awg_address'];
                        $port = $relay['awg_portmap'][$port] ?? $port;
                    }
                    $peer['Endpoint'] = "$host:$port";
                }
                foreach ($peer as $k => $v) {
                    $conf[] = "$k = $v";
                }
            }
        }
        return implode(PHP_EOL, $conf);
    }

    public function presharedKey()
    {
        $c = $this->getPacConf();
        if (empty($c[$this->getInstanceWG(1) . 'presharedkey'])) {
            $c[$this->getInstanceWG(1) . 'presharedkey'] = trim($this->ssh("{$this->getWGType()} genpsk", $this->getInstanceWG()));
            $this->setPacConf($c);
        }
        return $c[$this->getInstanceWG(1) . 'presharedkey'];
    }

    // ВАЖНО — симметрия server↔client.
    // Возвращаемый набор Jc/Jmin/Jmax/S1-S4/H1-H4/I1-I5 пишется ОДИНАКОВО
    // в [Interface] на сервере и в [Interface] каждого клиента (см. switchAmnezia).
    // Это требование протокола amneziawg-go: CPS-паттерн (I1-I5) описывает
    // junk-байты, которые сторона ВСТАВЛЯЕТ в свой исходящий handshake И
    // КОНСЬЮМИТ из входящего. Если у сервера и клиента CPS-строки разные,
    // принимающая сторона неверно вычитывает байты потока и handshake падает.
    // Поэтому раздельных server-I1 / client-I1 не существует на уровне config.
    //
    // Diversity fingerprint'а во времени обеспечивается ротацией I1-I5/S3-S4
    // (rotateAmneziaJunk + maybeRotateAmnezia, см. выше) — оба пира берут
    // новый паттерн одновременно из общего config-файла после повторного
    // импорта клиентских конфигов.
    public function amneziaKeys()
    {
        $c = $this->getPacConf();
        $k = $this->getInstanceWG(1) . 'amnezia_keys';
        if (empty($c[$k])) {
            $c[$k] = $this->generateAmneziaKeys($c[$this->getInstanceWG(1) . 'amnezia_tpl'] ?? 'standard_2');
            $this->setPacConf($c);
        }
        return $c[$k];
    }

    // Набор, который РЕАЛЬНО можно записать в конфиг прямо сейчас.
    // Отличается от amneziaKeys() (сырое хранилище) двумя срезами:
    //  1) старые amneziawg-tools роняют `setconf` на любом незнакомом ключе
    //     («Line unrecognized»), поэтому при заведомо старой версии 3.0-поля
    //     не пишем вовсе — иначе интерфейс просто не поднимется;
    //  2) HeaderProtectionKey без S1..S4 >= 12 отвергается amneziawg-go.
    // При awgSupports3() === null (ssh недоступен) НЕ срезаем: неизвестность не
    // повод выкинуть рабочую конфигурацию из конфигов всех клиентов.
    public function amneziaKeysEffective(): array
    {
        return self::amneziaKeysUsable($this->amneziaKeys(), $this->awgSupports3());
    }

    // То же решение, что awgSupports3(), но БЕЗ ssh: только кеш в pac.json,
    // который пишет awgToolsVersion(). Нужен путям подписки — они выполняются
    // на каждый запрос клиента, и лишний ssh там превратился бы в задержку и в
    // зависимость выдачи конфига от живости wg-контейнера.
    public function awgSupports3Cached(string $prefix = ''): ?bool
    {
        $v = $this->getPacConf()[$prefix . 'awg_tools_ver']['v'] ?? null;
        return $v === null ? null : version_compare(ltrim((string) $v, 'vV'), '3.0', '>=');
    }

    // Ключ header protection — тот же формат, что и обычный ключ wireguard
    // (32 байта base64), поэтому генерим его штатным `awg genkey`. Фолбэк на
    // random_bytes нужен, чтобы недоступный контейнер не блокировал настройку:
    // ключ всё равно уедет в конфиг через restartWG, когда ssh поднимется.
    public function genHeaderProtectionKey(): string
    {
        $v = trim((string) $this->ssh("{$this->getWGType()} genkey", $this->getInstanceWG()));
        if ($v === '' || strlen((string) base64_decode($v, true)) !== 32) {
            $v = base64_encode(random_bytes(32));
        }
        return $v;
    }

    // PersistentKeepalive пира. AWG 3.0 разрешает диапазон («20-30»), что убирает
    // строго периодический keepalive как признак туннеля. Значение гейтится
    // версией tools: старый клиентский стек на «20-30» упадёт при разборе.
    public function awgKeepalive()
    {
        $v = (string) ($this->getPacConf()[$this->getInstanceWG(1) . 'amnezia_keepalive'] ?? '');
        if ($v === '' || $this->awgSupports3() !== true) {
            return 20;
        }
        return $v;
    }

    // Templates for AmneziaWG key generation. Ranges follow official docs
    // (docs.amnezia.org/documentation/amnezia-wg): Jc 0–10, Jmin/Jmax 64–1024,
    // S1/S2/S3 0–64, S4 0–32. Constraints: S1+56 ≠ S2 and S1 ≠ S2.
    // I1 presence ⇒ 2.0; I1 absent ⇒ 1.x. CPS tags supported by amneziawg-go:
    // <b HEX>, <r N>, <rc N>, <rd N>, <t>. (<c> removed upstream — not used.)
    // H1–H4 format:
    //   1.x: distinct non-zero 32-bit integers.
    //   2.0: non-overlapping "MIN-MAX" ranges across uint32 space (server picks
    //        a random value per session, raising DPI cost).
    // 3.0 (шаблоны *_3) добавляет device-параметры AWG_KEYS_3: header protection
    // + рандомизированные тайминги/паддинг в виде диапазонов. Диапазоны выбраны
    // вокруг дефолтов amneziawg-go (rekey 120 / reject 180 / keepalive 10 /
    // handshake 18): слишком широкий разброс ломает совместимость с пирами,
    // которые ещё не перекачали конфиг. S1..S4 в *_3 всегда >= AWG_HPK_MIN_S —
    // иначе setconf отвергнет конфиг из-за header protection.
    //
    // $hpk — генератор ключа header protection. Вынесен параметром, чтобы
    // функция оставалась чистой и тестируемой; вызывающий код передаёт
    // genHeaderProtectionKey() (ssh `awg genkey`).
    public function generateAmneziaKeys($template = 'standard_2', ?callable $hpk = null)
    {
        $hpk = $hpk ?: fn() => base64_encode(random_bytes(32));

        // Диапазон «LO-HI»: нижняя граница из [lo_min, lo_max], ширина из
        // [span_min, span_max], верх подрезан hard_max.
        $rngRange = function (int $lo_min, int $lo_max, int $span_min, int $span_max, int $hard_max) {
            $lo = random_int($lo_min, $lo_max);
            $hi = min($hard_max, $lo + random_int($span_min, $span_max));
            return "$lo-$hi";
        };

        $rngS = function ($min, $max) {
            $s1 = random_int($min, $max);
            do {
                $s2 = random_int($min, $max);
            } while ($s1 + 56 === $s2 || $s1 === $s2);
            return [$s1, $s2];
        };

        // 2.0 H1-H4: non-overlapping ranges in AWG 2.0 "MIN-MAX" format.
        // 4 strict quarters inside signed int32 space to support all platforms.
        $rngH2 = function () {
            $segments = [
                [0x01000000, 0x1FFFFFFF],
                [0x20000000, 0x3FFFFFFF],
                [0x40000000, 0x5FFFFFFF],
                [0x60000000, 0x7FFFFFFF],
            ];
            shuffle($segments);
            $h = [];
            foreach ($segments as [$seg_min, $seg_max]) {
                // Unique range width per header increases entropy.
                $range_width = random_int(5_000_000, 50_000_000);
                $start = random_int($seg_min, $seg_max - $range_width);
                $h[] = $start . '-' . ($start + $range_width);
            }
            return ['H1' => $h[0], 'H2' => $h[1], 'H3' => $h[2], 'H4' => $h[3]];
        };

        // 1.x H1-H4: distinct non-zero 32-bit integers.
        $rngH1 = function () {
            $h = [];
            while (count($h) < 4) {
                $v = random_int(1, 4_294_967_295);
                if (!in_array($v, $h, true)) {
                    $h[] = $v;
                }
            }
            return ['H1' => $h[0], 'H2' => $h[1], 'H3' => $h[2], 'H4' => $h[3]];
        };

        switch ($template) {
            // 2.0 templates: каждое из I1–I5 даёт пакет ≥100 байт
            // (рекомендуемый минимум, habr.com/ru/companies/amnezia/articles/1014636/).
            case 'aggressive_2':
                [$s1, $s2] = $rngS(40, 64);
                return $rngH2() + [
                    'Jc' => 10, 'Jmin' => 256, 'Jmax' => 1024,
                    'S1' => $s1, 'S2' => $s2,
                    'S3' => random_int(32, 64), 'S4' => random_int(16, 32),
                    'I1' => '<b 0xc000000001><r ' . random_int(150, 250) . '>',
                    'I2' => '<t><r ' . random_int(100, 200) . '>',
                    'I3' => '<r ' . random_int(100, 200) . '>',
                    'I4' => '<rd ' . random_int(16, 24) . '><r ' . random_int(100, 150) . '>',
                    'I5' => '<rc ' . random_int(100, 150) . '>',
                ];

            case 'mobile_2':
                // Для mobile приоритет маскировки выше экономии батареи/трафика.
                [$s1, $s2] = $rngS(15, 32);
                return $rngH2() + [
                    'Jc' => random_int(2, 4), 'Jmin' => 64, 'Jmax' => 256,
                    'S1' => $s1, 'S2' => $s2,
                    'S3' => random_int(0, 32), 'S4' => random_int(0, 16),
                    'I1' => '<b 0xc000000001><r ' . random_int(100, 150) . '>',
                    'I2' => '<t><r ' . random_int(100, 130) . '>',
                    'I3' => '<r ' . random_int(100, 130) . '>',
                    'I4' => '<rd ' . random_int(6, 12) . '><r ' . random_int(100, 130) . '>',
                    'I5' => '<rc ' . random_int(100, 130) . '>',
                ];

            case 'classic_1':
                [$s1, $s2] = $rngS(15, 64);
                return $rngH1() + [
                    'Jc' => random_int(3, 10), 'Jmin' => 64, 'Jmax' => 1000,
                    'S1' => $s1, 'S2' => $s2,
                ];

            // 3.0 templates: 2.0-набор + AWG_KEYS_3. S1..S4 держим >= 12
            // (AWG_HPK_MIN_S) — обязательное условие header protection.
            // RejectAfterTime всегда начинается позже, чем заканчивается
            // RekeyAfterTime: иначе пир отбросит сессию раньше, чем попробует
            // сделать рекей, и туннель будет рвать раз в пару минут.
            case 'aggressive_3':
                [$s1, $s2] = $rngS(40, 64);
                return $rngH2() + [
                    'Jc' => 10, 'Jmin' => 256, 'Jmax' => 1024,
                    'S1' => $s1, 'S2' => $s2,
                    'S3' => random_int(32, 64), 'S4' => random_int(16, 32),
                    'I1' => '<b 0xc000000001><r ' . random_int(150, 250) . '>',
                    'I2' => '<t><r ' . random_int(100, 200) . '>',
                    'I3' => '<r ' . random_int(100, 200) . '>',
                    'I4' => '<rd ' . random_int(16, 24) . '><r ' . random_int(100, 150) . '>',
                    'I5' => '<rc ' . random_int(100, 150) . '>',
                    'HeaderProtectionKey'    => $hpk(),
                    'ContentPaddingAddition' => $rngRange(25, 30, 5, 10, 40),
                    'RekeyAfterTime'         => $rngRange(110, 118, 5, 12, 130),
                    'RekeyTimeout'           => $rngRange(5, 6, 1, 2, 8),
                    'RejectAfterTime'        => $rngRange(170, 178, 5, 7, 185),
                    'KeepaliveTimeout'       => $rngRange(10, 11, 1, 2, 13),
                    'MaxHandshakeAttempts'   => $rngRange(20, 22, 2, 3, 25),
                ];

            case 'mobile_3':
                [$s1, $s2] = $rngS(self::AWG_HPK_MIN_S, 32);
                return $rngH2() + [
                    'Jc' => random_int(2, 4), 'Jmin' => 64, 'Jmax' => 256,
                    'S1' => $s1, 'S2' => $s2,
                    'S3' => random_int(self::AWG_HPK_MIN_S, 32),
                    'S4' => random_int(self::AWG_HPK_MIN_S, 16),
                    'I1' => '<b 0xc000000001><r ' . random_int(100, 150) . '>',
                    'I2' => '<t><r ' . random_int(100, 130) . '>',
                    'I3' => '<r ' . random_int(100, 130) . '>',
                    'I4' => '<rd ' . random_int(6, 12) . '><r ' . random_int(100, 130) . '>',
                    'I5' => '<rc ' . random_int(100, 130) . '>',
                    'HeaderProtectionKey'    => $hpk(),
                    'ContentPaddingAddition' => $rngRange(10, 14, 4, 6, 20),
                    // Мобильный профиль реже дёргает рекей — экономия батареи.
                    'RekeyAfterTime'         => $rngRange(115, 122, 5, 8, 130),
                    'RekeyTimeout'           => $rngRange(6, 8, 1, 2, 10),
                    'RejectAfterTime'        => $rngRange(175, 182, 5, 8, 190),
                    'KeepaliveTimeout'       => $rngRange(12, 13, 1, 2, 15),
                    'MaxHandshakeAttempts'   => $rngRange(15, 17, 2, 3, 20),
                ];

            case 'standard_3':
                [$s1, $s2] = $rngS(self::AWG_HPK_MIN_S, 64);
                return $rngH2() + [
                    'Jc' => random_int(3, 10), 'Jmin' => 64, 'Jmax' => 1024,
                    'S1' => $s1, 'S2' => $s2,
                    'S3' => random_int(self::AWG_HPK_MIN_S, 64),
                    'S4' => random_int(self::AWG_HPK_MIN_S, 32),
                    'I1' => '<b 0xc000000001><r ' . random_int(120, 200) . '>',
                    'I2' => '<t><r ' . random_int(100, 150) . '>',
                    'I3' => '<r ' . random_int(100, 150) . '>',
                    'I4' => '<rd ' . random_int(8, 16) . '><r ' . random_int(100, 150) . '>',
                    'I5' => '<rc ' . random_int(100, 150) . '>',
                    'HeaderProtectionKey'    => $hpk(),
                    'ContentPaddingAddition' => $rngRange(10, 20, 10, 20, 40),
                    'RekeyAfterTime'         => $rngRange(110, 118, 5, 12, 130),
                    'RekeyTimeout'           => $rngRange(5, 7, 2, 3, 10),
                    'RejectAfterTime'        => $rngRange(170, 180, 5, 10, 190),
                    'KeepaliveTimeout'       => $rngRange(10, 12, 2, 3, 15),
                    'MaxHandshakeAttempts'   => $rngRange(15, 20, 3, 5, 25),
                ];

            case 'standard_2':
            default:
                [$s1, $s2] = $rngS(15, 64);
                return $rngH2() + [
                    'Jc' => random_int(3, 10), 'Jmin' => 64, 'Jmax' => 1024,
                    'S1' => $s1, 'S2' => $s2,
                    'S3' => random_int(0, 64), 'S4' => random_int(0, 32),
                    'I1' => '<b 0xc000000001><r ' . random_int(120, 200) . '>',
                    'I2' => '<t><r ' . random_int(100, 150) . '>',
                    'I3' => '<r ' . random_int(100, 150) . '>',
                    'I4' => '<rd ' . random_int(8, 16) . '><r ' . random_int(100, 150) . '>',
                    'I5' => '<rc ' . random_int(100, 150) . '>',
                ];
        }
    }

    // Шаблоны, доступные для версии протокола. Порядок = порядок кнопок.
    public static function amneziaTemplateList(int $ver): array
    {
        switch ($ver) {
            case 3:
                return ['standard_3', 'aggressive_3', 'mobile_3'];
            case 2:
                return ['standard_2', 'aggressive_2', 'mobile_2'];
            default:
                return ['classic_1'];
        }
    }

    public function createPeer($ips_user = false, $name = false)
    {
        $conf      = $this->readConfig();
        // readConfig() возвращает null, если контейнер недоступен: без проверки
        // дальше шли обращения к null и создавался пир с битым адресом.
        if (empty($conf['interface']['Address'])) {
            $this->send($this->input['chat'] ?? '', 'wireguard: конфиг недоступен (контейнер не отвечает), пир не создан', $this->input['message_id'] ?? null);
            return;
        }
        $ipnet     = explode('/', $conf['interface']['Address']);
        $server_ip = ip2long($ipnet[0]);
        $ips       = [$server_ip];
        $bitmask   = (int) $ipnet[1];
        if (!empty($conf['peers'])) {
            foreach ($conf['peers'] as $k => $v) {
                $ips[] = ip2long(explode('/', $v['AllowedIPs'] ?: $v['# AllowedIPs'])[0]);
            }
        }
        // Перебираем ВЕСЬ диапазон хостов подсети (network+1 … broadcast-1) и
        // берём первый свободный. Старый код искал `$i + $server_ip` с границей
        // `$ip_count`, которая уменьшалась с числом пиров → во фрагментированной
        // почти-полной подсети свободный адрес (например удалённый в середине) не
        // находился, $client_ip оставался undefined и создавался битый пир
        // «AllowedIPs = /32». Здесь же при исчерпании подсети выходим явно.
        $size      = 1 << (32 - $bitmask);
        $net       = $server_ip & ~($size - 1);
        $broadcast = $net | ($size - 1);
        $client_ip = null;
        for ($ip = $net + 1; $ip < $broadcast; $ip++) {
            if (!in_array($ip, $ips, true)) {
                $client_ip = long2ip($ip);
                break;
            }
        }
        if ($client_ip === null) {
            $this->send($this->input['chat'] ?? '', 'wireguard: подсеть исчерпана, свободных адресов нет', $this->input['message_id'] ?? null);
            return;
        }
        $public_server_key = trim($this->ssh("echo {$conf['interface']['PrivateKey']} | {$this->getWGType()} pubkey", $this->getInstanceWG()));
        $private_peer_key  = trim($this->ssh("{$this->getWGType()} genkey", $this->getInstanceWG()));
        $public_peer_key   = trim($this->ssh("echo $private_peer_key | {$this->getWGType()} pubkey", $this->getInstanceWG()));

        // ssh() отдаёт "" при недоступном контейнере, и раньше пир с пустыми
        // ключами молча уезжал в clients.json (локальная запись-то проходит) —
        // пользователь получал «успех» и нерабочий конфиг, который потом
        // приходилось вычищать руками. Лучше не создавать ничего.
        if ('' === $public_server_key || '' === $private_peer_key || '' === $public_peer_key) {
            $this->send($this->input['chat'] ?? '', 'wireguard: не удалось сгенерировать ключи (контейнер недоступен), пир не создан', $this->input['message_id'] ?? null);
            return;
        }

        $name = ($name ? "$name" : '') . time();

        // Один раз на инстанс: три ветки ниже читали ключ порознь и без ??,
        // что на свежей установке (pac.json = {}) давало «Undefined array key».
        $amnezia = $this->getPacConf()[$this->getInstanceWG(1) . 'amnezia'] ?? false;

        $conf['peers'][] = array_merge([
                '## name'    => $name,
                'PublicKey'  => $public_peer_key,
                'AllowedIPs' => "$client_ip/32",
            ],
            $amnezia ? ['PresharedKey' => $this->presharedKey()] : []
        );
        $client_conf = [
            'interface' => array_merge(
                [
                    '## name'    => $name,
                    'PrivateKey' => $private_peer_key,
                    'Address'    => "$client_ip/32",
                ],
                $amnezia ? $this->amneziaKeysEffective() : []
            ),
            'peers' => [
                    array_merge(
                        [
                            'PublicKey'           => $public_server_key,
                            'AllowedIPs'          => $ips_user ?: "0.0.0.0/0",
                            // AWG 3.0 допускает диапазон («20-30»); awgKeepalive()
                            // отдаёт фиксированные 20, если 3.0 недоступен.
                            'PersistentKeepalive' => $amnezia ? $this->awgKeepalive() : 20,
                        ],
                        $amnezia ? ['PresharedKey' => $this->presharedKey()] : []
                    ),
                ],
        ];
        $k = $this->saveClient($client_conf);
        $this->restartWG($this->createConfig($conf));
        $this->menu('client', "{$k}_-2");
    }

    public function deleteClient(int $client)
    {
        $clients = $this->readClients();
        unset($clients[$client]);
        $this->saveClients(array_values($clients));
    }

    public function saveClient(array $client)
    {
        $r = array_merge($this->readClients(), [$client]);
        $this->saveClients($r);
        return count($r) - 1;
    }

    public function syncPortClients()
    {
        for ($i=0; $i < 2; $i++) {
            $this->wg = $i;
            $this->saveClients($this->readClients());
        }
        unset($this->wg);
    }

    public function saveClients(array $clients)
    {
        $c      = $this->getPacConf();
        $ports  = $this->getPorts();
        $domain = ($c['domain'] ?: $this->ip) . ":" . $ports[$this->getInstanceWG()]['port'];
        foreach ($clients as $k => $v) {
            $clients[$k]['peers'][0]['Endpoint'] = $domain;
        }
        file_put_contents($this->getInstanceWG(1) ? $this->clients1 : $this->clients, json_encode($clients, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
    }

    public function getWGType($revert = 0)
    {
        // ?? false — на свежей установке pac.json = {} и ключа amnezia нет;
        // без фолбэка каждый вызов сыпал «Undefined array key» (ср. getInstanceWG).
        $wg = $this->getPacConf()[$this->getInstanceWG(1) . 'amnezia'] ?? false;
        return ($revert ? !$wg : $wg) ? 'awg' : 'wg';
    }

    public function restartWG($conf_str, $switch = false)
    {
        // Конфиг пишем через base64, а НЕ `echo '$conf_str'`. Имя клиента
        // (## name) — сырой пользовательский ввод (см. renameClient/addWg), и
        // одиночная кавычка в нём рвала bash-строку `echo '...'` →
        // wg0.conf обрезался/не записывался, а следующий wg-quick up падал с
        // битым конфигом → туннель ложился. base64 выдаёт только [A-Za-z0-9+/=],
        // что безопасно внутри одинарных кавычек при любом содержимом конфига.
        $b64 = base64_encode($conf_str);
        // Раньше возвращали true безусловно: при лежащем контейнере ssh() отдаёт
        // "" и пользователю показывался «успех» на невыполненной операции.
        // Запись конфига — единственный шаг, который обязан пройти; на down
        // ошибку игнорируем (интерфейс мог быть не поднят — это норма).
        $this->ssh("echo '$b64' | base64 -d > /etc/wireguard/wg0.conf", $this->getInstanceWG());
        if ($this->sshFailed) {
            return false;
        }
        $this->ssh("{$this->getWGType((int) $switch)}-quick down wg0", $this->getInstanceWG());
        $this->ssh("{$this->getWGType()}-quick up wg0", $this->getInstanceWG());
        return !$this->sshFailed;
    }

    public function autoupdate()
