    }

    public function ssh($cmd, $service = 'wg', $wait = true, $log = '/dev/null')
    {
        $data = "";
        $this->sshFailed = false;
        try {
            // ssh2_connect не принимает таймаут и по умолчанию ждёт TCP-коннект
            // минутами (лежащий контейнер = зависший вебхук-воркер). 5с хватает
            // внутри docker-сети с запасом.
            $prevTimeout = ini_get('default_socket_timeout');
            ini_set('default_socket_timeout', '5');
            $c = ssh2_connect($service, 22);
            ini_set('default_socket_timeout', $prevTimeout);
            if (empty($c)) {
                throw new Exception("no connection to $service: \n$cmd\n" . var_export($c, true));
            }
            $a = ssh2_auth_pubkey_file($c, 'root', '/ssh/key.pub', '/ssh/key');
            if (empty($a)) {
                throw new Exception("auth fail: \n$cmd\n" . var_export($a, true));
            }

            // Оборачиваем команду для выполнения в фоновом режиме
            if (!$wait) {
                // nohup запускает процесс независимо от SSH-сессии
                // & переносит процесс в фон
                // </dev/null >/dev/null 2>&1 перенаправляет все потоки ввода-вывода
                $cmd = "nohup sh -c \"$cmd 2>&1 | tee -a $log >&3\" 3>/proc/1/fd/1 </dev/null &";
            }


            $s = ssh2_exec($c, $cmd);
            if (empty($s)) {
                throw new Exception("exec fail: \n$cmd\n" . var_export($s, true));
            }

            if ($wait) {
                // Только для синхронных команд читаем вывод
                stream_set_blocking($s, true);
                while ($buf = fread($s, 4096)) {
                    $data .= $buf;
                }
            } else {
                // Для фоновых команд просто даем время запуститься
                stream_set_blocking($s, false);
                usleep(100000); // 100ms для запуска процесса
            }

            fclose($s);
            ssh2_disconnect($c);
        } catch (Exception | Error $e) {
            $this->sshFailed = true;
            // Молчаливое проглатывание приводило к «успеху» на сломанной
            // операции; в лог пишем всегда, пользователю — как и раньше,
            // только в debug-режиме.
            //
            // В лог идёт ТОЛЬКО первая строка сообщения: дальше в нём лежит
            // сам $cmd, а он бывает вида «echo <PrivateKey> | wg pubkey»
            // (createPeer) — писать это в лог нельзя.
            error_log('ssh(' . $service . ') failed: ' . strtok($e->getMessage(), "\n"));
            if (!empty($GLOBALS['debug'])) {
                $this->send($this->input['chat'], $e->getMessage(), $this->input['message_id']);
            }
        }
        return $data;
    }

    public function request($method, $data, $json_header = 0)
    {
        $ch = curl_init();
        curl_setopt_array($ch, [
            CURLOPT_URL            => $this->api . $method,
            CURLOPT_CUSTOMREQUEST  => 'POST',
            CURLOPT_RETURNTRANSFER => true,
            // Без таймаутов зависший Telegram API держит php-worker вечно
            // (вместе с session lock юзера). Запросам с файлом (CURLFile —
            // бэкапы через sendDocument бывают большими) даём 300с, остальным
            // хватает 30с (getUpdates long-poll timeout=5 укладывается).
            CURLOPT_CONNECTTIMEOUT => 5,
            CURLOPT_TIMEOUT        => is_array($data) && array_filter($data, fn ($v) => $v instanceof CURLFile || $v instanceof CURLStringFile) ? 300 : 30,
            CURLOPT_HTTPHEADER => $json_header ? [
                'Content-Type: application/json'
            ] : [],
            CURLOPT_POSTFIELDS     => $data,
        ]);
        $res  = curl_exec($ch);
        $cerr = $res === false ? curl_error($ch) : '';
        $r    = json_decode((string) $res, true);
        // $res — строка (или false): старая проверка $res['description']
        // не срабатывала никогда. Ошибку определяем по декодированному
        // ответу: у Telegram успех — всегда ok=true. «message is not
        // modified» — штатный ответ на перерисовку меню без изменений,
        // им лог не засоряем.
        if ((!is_array($r) || empty($r['ok']))
            && !str_contains((string) ($r['description'] ?? ''), 'message is not modified')) {
            file_put_contents('/logs/requests_error', var_export([
                'r' => [
                    'method' => $method,
                    'data'   => $data,
                ],
                'a' => is_array($r) ? $r : $res,
                'curl' => $cerr,
            ], true) . "\n", FILE_APPEND);
        }
        return $r;
    }

    public function polling()
    {
        $offset = -1;
        while (true) {
            $r = $this->request('getUpdates', [
                'offset'  => $offset,
                'limit'   => 3,
                'timeout' => 5,
            ]);
            if (!empty($r['description'])) {
                error_log('getUpdates error: ' . $r['description']);
                sleep(3);
                continue;
            }
            file_put_contents('/start', 1);
            if (!empty($r['result'])) {
                foreach ($r['result'] as $v) {
                    try {
                        $this->input($v);
                    } catch (Throwable $e) {
                        error_log($e);
                    } finally {
                        session_write_close();
                    }
                    $offset = max($offset, $v['update_id']);
                }
                $offset++;
            } else {
                sleep(1);
            }
        }
    }

